def effective_formula_policy(args: argparse.Namespace) -> str:
    if args.enable_formula_mlx:
        return "granite_mlx"
    return args.formula_policy


def validated_private_formula_ocr_url(value: str | None) -> str | None:
    """Allow formula crops to leave the process only for a local/private sidecar."""

    if not value:
        return None
    parsed = urllib.parse.urlsplit(value.rstrip("/"))
    if (
        parsed.scheme != "http"
        or parsed.hostname not in {"formula", "localhost", "127.0.0.1", "::1"}
        or parsed.username is not None
        or parsed.password is not None
        or parsed.query
        or parsed.fragment
    ):
        raise ValueError(
            "formula OCR URL must be an unauthenticated local Docker/loopback HTTP endpoint"
        )
    return value.rstrip("/")


def effective_ocr_fallback_policy(args: argparse.Namespace) -> str:
    if args.force_ocr_on_gxx:
        return "gxx"
    return args.ocr_fallback_policy


def effective_cn_ocr_parity(args: argparse.Namespace) -> bool:
    return bool(args.cn_ocr_parity)


def page_range(args: argparse.Namespace) -> list[int] | None:
    if args.page_start is None and args.page_end is None:
        return None
    if args.page_start is None or args.page_end is None:
        raise ValueError("--page-start and --page-end must be provided together")
    if args.page_start < 1 or args.page_end < args.page_start:
        raise ValueError("page range must be 1-based and page-end >= page-start")
    return [args.page_start, args.page_end]


def is_transient_http_error(exc: BaseException) -> bool:
    current: BaseException | None = exc
    while current is not None:
        if isinstance(current, urllib.error.HTTPError) and current.code in {503, 504}:
            return True
        current = current.__cause__
    return False


def _is_transient_docling_response(code: int, detail: str) -> bool:
    if code in {503, 504}:
        return True
    return code == 404 and "Task result not found" in detail


def post_json(
    url: str,
    payload: dict[str, Any],
    timeout: int,
    retries: int,
    retry_sleep_seconds: float,
) -> dict[str, Any]:
    data = json.dumps(payload).encode("utf-8")
    request = urllib.request.Request(
        url,
        data=data,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    for attempt in range(retries + 1):
        try:
            with urllib.request.urlopen(request, timeout=timeout) as response:
                return json.loads(response.read())
        except urllib.error.HTTPError as exc:
            try:
                detail = exc.read().decode("utf-8", errors="replace")
            except OSError:
                detail = ""
            if not _is_transient_docling_response(exc.code, detail) or attempt >= retries:
                message = f"Docling Serve HTTP {exc.code}"
                if detail:
                    message += f": {detail[:4000]}"
                raise RuntimeError(message) from exc
            time.sleep(retry_sleep_seconds * (attempt + 1))
    raise RuntimeError("unreachable retry state")


def get_json(url: str, timeout: int = 10) -> dict[str, Any]:
    with urllib.request.urlopen(url, timeout=timeout) as response:
        return json.loads(response.read())


def release_backend_converter_cache(args: argparse.Namespace) -> dict[str, Any]:
    """Release Linux parser models before the isolated formula stage starts."""

    if effective_formula_policy(args) != "formula_service":
        return {"ok": True, "applied": False, "reason": "not_docker_formula_profile"}
    url = f"{args.serve_url.rstrip('/')}/v1/clear/converters"
    started = time.perf_counter()
    try:
        response = get_json(url, timeout=120)
    except Exception as exc:
        return {
            "ok": False,
            "applied": True,
            "url": url,
            "elapsed_seconds": time.perf_counter() - started,
            "error_type": exc.__class__.__name__,
            "error": str(exc),
        }
    return {
        "ok": True,
        "applied": True,
        "url": url,
        "elapsed_seconds": time.perf_counter() - started,
        "response": response,
    }


def iter_nodes(value: Any):
    if isinstance(value, dict):
        yield value
        for child in value.values():
            yield from iter_nodes(child)
    elif isinstance(value, list):
        for child in value:
            yield from iter_nodes(child)


def label_counts(document_json: Any) -> dict[str, int]:
    counts: dict[str, int] = {}
    for node in iter_nodes(document_json):
        label = node.get("label") if isinstance(node, dict) else None
        if isinstance(label, str):
            counts[label] = counts.get(label, 0) + 1
    return counts


def extract_table_nodes(document_json: Any) -> list[dict[str, Any]]:
    tables: list[dict[str, Any]] = []
    for node in iter_nodes(document_json):
        if isinstance(node, dict) and str(node.get("label", "")).lower() == "table":
            tables.append(node)
    return tables


def extract_label_nodes(document_json: Any, label_name: str) -> list[dict[str, Any]]:
    wanted = label_name.lower()
    nodes: list[dict[str, Any]] = []
    for node in iter_nodes(document_json):
        if isinstance(node, dict) and str(node.get("label", "")).lower() == wanted:
            nodes.append(node)
    return nodes


def combined_text(document: dict[str, Any]) -> str:
    parts = [
        document.get("md_content") or "",
        document.get("html_content") or "",
        document.get("text_content") or "",
    ]
    if document.get("json_content") is not None:
        parts.append(json.dumps(document["json_content"], ensure_ascii=False))
    return DATA_IMAGE_RE.sub("data:image/<stripped>", "\n".join(parts))


def gxx_quality(document: dict[str, Any]) -> dict[str, Any]:
    text = combined_text(document)
    count = len(GXX_RE.findall(text))
    length = max(len(text), 1)
    return {
        "text_quality_gxx_count": count,
        "text_quality_gxx_density": count / length,
        "text_length": len(text),
    }


def formula_metrics(document: dict[str, Any]) -> dict[str, Any]:
    text = combined_text(document)
    document_json = document.get("json_content")
    labels = label_counts(document_json)
    formula_examples: list[str] = []
    for node in iter_nodes(document_json):
        if not isinstance(node, dict):
            continue
        if str(node.get("label", "")).lower() != "formula":
            continue
        formula_text = str(node.get("text") or "")
        if formula_text:
            formula_examples.append(formula_text[:240])
    return {
        "formula_count": labels.get("formula", 0),
        "formula_placeholder_count": text.count("Formula not decoded"),
        "formula_latex_like_count": len(
            re.findall(
                r"\\(?:frac|sum|int|alpha|beta|gamma|theta|math|mathbf|mathrm|sqrt|infty|cdot|left|right|sigma|mu)",
                text,
            )
        ),
        "formula_examples": formula_examples[:5],
    }


def html_ref_metrics(document: dict[str, Any]) -> dict[str, Any]:
    html = document.get("html_content") or ""
    markdown = document.get("md_content") or ""
    refs = re.findall(r'(?:src|href)="([^"]+)"', html)
    md_images = re.findall(r"!\[[^\]]*\]\(([^)]+)\)", markdown)
    return {
        "html_len": len(html),
        "html_src_href_count": len(refs),
        "markdown_image_ref_count": len(md_images),
        "image_refs_embedded": html.count("data:image/") + markdown.count("data:image/"),
        "image_refs_external": len(
            [
                ref
                for ref in [*refs, *md_images]
                if ref and not ref.startswith(("data:", "http://", "https://", "#"))
            ]
        ),
    }


def _markdown_strip_container_prefix(line: str) -> str:
    """Remove Markdown container markers only for fence recognition."""

    value = line.rstrip("\r\n")
    while True:
        quote = re.match(r"^[ \t]{0,3}>[ \t]?", value)
        if quote:
            value = value[quote.end() :]
            continue
        list_item = re.match(
            r"^[ \t]{0,3}(?:[-+*]|\d{1,9}[.)])[ \t]+",
            value,
        )
        if list_item:
            value = value[list_item.end() :]
            continue
        return value


def _markdown_fenced_ranges(markdown: str) -> list[tuple[int, int]]:
    """Return byte ranges occupied by backtick/tilde fenced code blocks.

    The scanner is line based and understands blockquote/list container
    prefixes.  An unmatched opening fence protects the remainder of the
    document, which is the conservative behavior for mutation gates.
    """

    ranges: list[tuple[int, int]] = []
    open_start: int | None = None
    open_char = ""
    open_length = 0
    offset = 0
    for line in markdown.splitlines(keepends=True):
        candidate = _markdown_strip_container_prefix(line)
        if open_start is None:
            opening = re.match(
                r"^[ \t]{0,3}(?P<fence>`{3,}|~{3,})(?P<info>[^\r\n]*)$",
                candidate,
            )
            if opening:
                fence = opening.group("fence")
                # CommonMark forbids backticks in a backtick fence's info
                # string.  Treating such a line as prose avoids masking an
                # unrelated inline literal through end-of-document.
                if fence[0] == "`" and "`" in opening.group("info"):
                    offset += len(line)
                    continue
                open_start = offset
                open_char = fence[0]
                open_length = len(fence)
        else:
            closing = re.fullmatch(
                rf"[ \t]{{0,3}}{re.escape(open_char)}{{{open_length},}}[ \t]*",
                candidate,
            )
            if closing:
                ranges.append((open_start, offset + len(line)))
                open_start = None
                open_char = ""
                open_length = 0
        offset += len(line)
    if open_start is not None:
        ranges.append((open_start, len(markdown)))
    return ranges


def _markdown_inline_code_ranges(
    markdown: str,
    start: int,
    end: int,
) -> list[tuple[int, int]]:
    ranges: list[tuple[int, int]] = []
    position = start
    while position < end:
        opening = markdown.find("`", position, end)
        if opening < 0:
            break
        opening_end = opening + 1
        while opening_end < end and markdown[opening_end] == "`":
            opening_end += 1
        length = opening_end - opening
        delimiter = "`" * length
        search_at = opening_end
        closing = -1
        while search_at < end:
            probe = markdown.find(delimiter, search_at, end)
            if probe < 0:
                break
            before_same = probe > start and markdown[probe - 1] == "`"
            after = probe + length
            after_same = after < end and markdown[after] == "`"
            if not before_same and not after_same:
                closing = probe
                break
            search_at = probe + length
        if closing < 0:
            position = opening_end
            continue
        ranges.append((opening, closing + length))
        position = closing + length
    return ranges


def _markdown_code_ranges(markdown: str) -> list[tuple[int, int]]:
    fenced = _markdown_fenced_ranges(markdown)
    ranges = list(fenced)
    cursor = 0
    for start, end in [*fenced, (len(markdown), len(markdown))]:
        if cursor < start:
            ranges.extend(_markdown_inline_code_ranges(markdown, cursor, start))
        cursor = max(cursor, end)
    return sorted(ranges)


def _markdown_non_code_ranges(markdown: str) -> list[tuple[int, int]]:
    ranges: list[tuple[int, int]] = []
    cursor = 0
    for start, end in _markdown_code_ranges(markdown):
        if cursor < start:
            ranges.append((cursor, start))
        cursor = max(cursor, end)
    if cursor < len(markdown):
        ranges.append((cursor, len(markdown)))
    return ranges


def _markdown_mask_code(markdown: str) -> str:
    """Mask code bytes while retaining offsets and line boundaries."""

    pieces: list[str] = []
    cursor = 0
    for start, end in _markdown_code_ranges(markdown):
        pieces.append(markdown[cursor:start])
        pieces.append(
            "".join("\n" if char == "\n" else "\r" if char == "\r" else " " for char in markdown[start:end])
        )
        cursor = end
    pieces.append(markdown[cursor:])
    return "".join(pieces)


def _markdown_display_math_spans(markdown: str) -> list[tuple[int, int]]:
    spans: list[tuple[int, int]] = []
    for start, end in _markdown_non_code_ranges(markdown):
        for match in re.finditer(r"\$\$.*?\$\$", markdown[start:end], flags=re.S):
            spans.append((start + match.start(), start + match.end()))
    return spans


def _markdown_formula_slots(markdown: str) -> list[tuple[int, int]]:
    slots = list(_markdown_display_math_spans(markdown))
    for start, end in _markdown_non_code_ranges(markdown):
        for match in re.finditer(
            r"<!--\s*formula-not-decoded\s*-->",
            markdown[start:end],
        ):
            slots.append((start + match.start(), start + match.end()))
    return sorted(slots)


def _markdown_sub_outside_code(
    markdown: str,
    pattern: str | re.Pattern[str],
    replacement: str | Any,
    *,
    flags: int = 0,
) -> tuple[str, int]:
    compiled = re.compile(pattern, flags) if isinstance(pattern, str) else pattern
    edits: list[tuple[int, int, str]] = []
    for start, end in _markdown_non_code_ranges(markdown):
        for match in compiled.finditer(markdown[start:end]):
            value = (
                replacement(match)
                if callable(replacement)
                else match.expand(str(replacement))
            )
            edits.append((start + match.start(), start + match.end(), value))
    for start, end, value in reversed(edits):
        markdown = markdown[:start] + value + markdown[end:]
    return markdown, len(edits)


def _markdown_source_formula_anchor_spans(
    markdown: str,
) -> list[tuple[int, int, int]]:
    spans: list[tuple[int, int, int]] = []
    pattern = re.compile(r"<!--\s*source-formula-anchor:(?P<index>\d+)\s*-->")
    for start, end in _markdown_non_code_ranges(markdown):
        for match in pattern.finditer(markdown[start:end]):
            spans.append(
                (
                    start + match.start(),
                    start + match.end(),
                    int(match.group("index")),
                )
            )
    return spans


def _markdown_tagged_formula_spans(
    markdown: str,
) -> tuple[list[tuple[int, int, int | None, bool]], bool]:
    """Return display blocks carrying a numeric ``\\tag{N}`` identity.

    The boolean indicates that a tag marker was present even when malformed or
    non-numeric.  Callers use it to disable positional fallback in that case;
    a malformed/duplicate tag must fail closed rather than silently binding a
    crop by display order.
    """

    tag_marker_re = re.compile(r"\\tag\*?\s*\{")
    numeric_tag_re = re.compile(
        r"\\tag\*?\s*\{\s*\(?\s*(?P<index>\d+)\s*\)?\s*\}"
    )
    tagged: list[tuple[int, int, int | None, bool]] = []
    marker_seen = False
    for start, end in _markdown_display_math_spans(markdown):
        block = markdown[start:end]
        raw_tags = list(tag_marker_re.finditer(block))
        if not raw_tags:
            continue
        marker_seen = True
        numeric_tags = list(numeric_tag_re.finditer(block))
        valid = len(raw_tags) == 1 and len(numeric_tags) == 1
        index = (
            int(numeric_tags[0].group("index"))
            if numeric_tags
            else None
        )
        tagged.append((start, end, index, valid))
    return tagged, marker_seen


def _markdown_adjacent_text_fence_end(markdown: str, end: int) -> int:
    """Include an immediately following generated ``text`` evidence fence."""

    for start, fence_end in _markdown_fenced_ranges(markdown):
        if start < end:
            continue
        if markdown[end:start].strip():
            return end
        first_line = markdown[start:fence_end].splitlines()[0]
        opening = _markdown_strip_container_prefix(first_line)
        if re.match(r"^[ \t]{0,3}(?:`{3,}|~{3,})[ \t]*text\b", opening, re.I):
            return fence_end
        return end
    return end


def broken_local_refs(output_dir: Path, document: dict[str, Any]) -> list[str]:
    html_content = document.get("html_content") or ""
    markdown = document.get("md_content") or ""
    refs = re.findall(
        r"(?:src|href)\s*=\s*[\"']([^\"']+)[\"']",
        html_content,
        flags=re.I,
    )
    markdown_without_code = _markdown_mask_code(markdown)
    refs.extend(
        re.findall(r"!?\[[^\]]*\]\(([^)]+)\)", markdown_without_code)
    )
    refs.extend(
        re.findall(
            r"<img\b[^>]*\bsrc\s*=\s*[\"']([^\"']+)[\"'][^>]*>",
            markdown_without_code,
            flags=re.I,
        )
    )
    broken: list[str] = []
    output_root = output_dir.resolve()
    for ref in refs:
        ref = html.unescape(ref).strip().strip("<>")
        if not ref or ref.startswith(("data:", "http://", "https://", "#", "mailto:")):
            continue
        path_ref = urllib.parse.unquote(
            ref.split("#", 1)[0].split("?", 1)[0]
        )
        if not path_ref:
            continue
        raw_path = Path(path_ref)
        if raw_path.is_absolute():
            broken.append(path_ref)
            continue
        candidate = (output_dir / raw_path).resolve()
        try:
            candidate.relative_to(output_root)
        except ValueError:
            broken.append(path_ref)
            continue
        if not candidate.exists():
            broken.append(path_ref)
    return sorted(set(broken))


def refresh_final_broken_local_refs(
    output_dir: Path,
    metadata: dict[str, Any],
    status: dict[str, Any],
) -> list[str]:
    """Audit the final post-processed HTML/Markdown, not only the Serve response."""
    final_document = {
        "html_content": (
            (output_dir / "document.html").read_text(encoding="utf-8")
            if (output_dir / "document.html").exists()
            else ""
        ),
        "md_content": (
            (output_dir / "document.md").read_text(encoding="utf-8")
            if (output_dir / "document.md").exists()
            else ""
        ),
    }
    broken = broken_local_refs(output_dir, final_document)
    metadata["broken_local_refs_count"] = len(broken)
    metadata["broken_local_refs"] = broken[:20]
    status.setdefault("quality_signals", {})["broken_local_refs_count"] = len(broken)
    if broken:
        status["ok"] = False
        status["success_class"] = "degraded_failure"
        status.setdefault("warnings", []).append(
            "final_output_broken_local_refs:" + ",".join(broken[:20])
        )
    return broken


def _pdf_literal_to_text(value: bytes) -> str:
    text = value.decode("latin-1", errors="ignore")
    text = text.replace(r"\(", "(").replace(r"\)", ")").replace(r"\\", "\\")
    return text


def pdf_annotation_link_diagnostics(input_file: Path) -> dict[str, Any]:
    """Extract lightweight PDF link evidence without depending on Docling internals."""
    try:
        pdf_bytes = input_file.read_bytes()
    except OSError as exc:
        return {"ok": False, "error": str(exc)}

    uri_values = [
        _pdf_literal_to_text(match.group(1))
        for match in re.finditer(rb"/URI\s*\((.*?)\)", pdf_bytes, flags=re.DOTALL)
    ]
    goto_values = [
        _pdf_literal_to_text(match.group(1))
        for match in re.finditer(rb"/D\s*\((.*?)\)\s*/S\s*/GoTo", pdf_bytes, flags=re.DOTALL)
    ]
    return {
        "ok": True,
        "pdf_annotation_link_count": len(re.findall(rb"/Subtype\s*/Link\b", pdf_bytes)),
        "pdf_uri_link_count": len(uri_values),
        "pdf_goto_link_count": len(goto_values),
        "pdf_uri_links": sorted(set(uri_values))[:50],
        "pdf_goto_destinations": sorted(set(goto_values))[:50],
    }


def json_hyperlink_count(document_json: Any) -> int:
    count = 0
    for node in iter_nodes(document_json):
        if isinstance(node, dict) and node.get("hyperlink"):
            count += 1
    return count


def apply_cn_ocr_options(options: dict[str, Any], args: argparse.Namespace) -> None:
    options["force_ocr"] = True
    if args.cn_ocr_request_shape == "custom":
        options["ocr_preset"] = "auto"
        options.pop("ocr_lang", None)
        options["ocr_custom_config"] = {
            "kind": "ocrmac",
            "lang": CN_OCR_LANG,
            "recognition": "accurate",
            "framework": "vision",
        }
    else:
        options["ocr_preset"] = "ocrmac"
        options["ocr_lang"] = CN_OCR_LANG
        options.pop("ocr_custom_config", None)


def base_options(
    args: argparse.Namespace,
    *,
    force_ocr: bool,
    page_range_override: list[int] | None = None,
    cn_ocr_parity: bool = False,
) -> dict[str, Any]:
    options: dict[str, Any] = {
        "from_formats": ["pdf"],
        "to_formats": ["md", "json", "html"],
        "image_export_mode": args.image_export_mode,
        "do_ocr": True,
        "force_ocr": force_ocr,
        "ocr_preset": "auto",
        "do_table_structure": True,
        "table_mode": "accurate",
        "table_cell_matching": True,
        "include_images": True,
        "images_scale": 2.0,
        "document_timeout": float(getattr(args, "timeout_seconds", 1200)),
        "do_formula_enrichment": effective_formula_policy(args)
        in {"granite_mlx", "granite_transformers", "codeformula_transformers"},
        "do_code_enrichment": False,
    }
    selected_page_range = page_range_override or page_range(args)
    if selected_page_range:
        options["page_range"] = selected_page_range
    if cn_ocr_parity and force_ocr:
        apply_cn_ocr_options(options, args)
    if effective_formula_policy(args) == "granite_mlx":
        options["code_formula_custom_config"] = GRANITE_MLX_CODE_FORMULA_CONFIG
    elif effective_formula_policy(args) == "granite_transformers":
        # Server-side presets retain enum-typed Transformers overrides. Sending
        # the same overrides through JSON turns those enum values into strings
        # and Docling 2.95 fails later in the worker. On Linux auto_inline
        # deterministically selects Transformers; macOS keeps its accepted MLX
        # custom configuration above.
        options["code_formula_preset"] = "granite_docling"
    elif effective_formula_policy(args) == "codeformula_transformers":
        options["code_formula_preset"] = "codeformulav2"
    return options


def custom_config_mapping(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return {}
        return parsed if isinstance(parsed, dict) else {}
    return {}


def request_payload(args: argparse.Namespace, options: dict[str, Any]) -> dict[str, Any]:
    snapshot = getattr(args, "_input_snapshot", None)
    pdf_bytes = (
        snapshot.read_bytes()
        if isinstance(snapshot, _ImmutableInputSnapshot)
        else args.input_file.read_bytes()
    )
    filename = str(
        getattr(args, "_submitted_input_name", None) or args.input_file.name
    )
    return {
        "sources": [
            {
                "kind": "file",
                "filename": filename,
                "base64_string": base64.b64encode(pdf_bytes).decode("ascii"),
            }
        ],
        "target": {"kind": "inbody"},
        "options": options,
    }


def pdf_text_layer_profile(path: Path) -> dict[str, Any]:
    """Return lightweight PDF features used for scan/source recovery decisions."""
    try:
        import fitz  # type: ignore
    except Exception:
        fitz = None
    if fitz is not None:
        try:
            doc = fitz.open(path)
        except Exception as exc:
            return {"path": str(path), "error": f"pdf_open_failed:{exc}"}
        text_chars = 0
        page_sizes: list[tuple[float, float]] = []
        image_counts: list[int] = []
        for page in doc:
            try:
                text_chars += len(page.get_text().strip())
            except Exception:
                pass
            rect = page.rect
            page_sizes.append((round(float(rect.width), 1), round(float(rect.height), 1)))
            try:
                image_counts.append(len(page.get_images(full=True)))
            except Exception:
                image_counts.append(0)
        page_count = doc.page_count
        doc.close()
    else:
        try:
            import pdfplumber  # type: ignore

            text_chars = 0
            page_sizes = []
            image_counts = []
            with pdfplumber.open(path) as pdf:
                page_count = len(pdf.pages)
                for page in pdf.pages:
                    text_chars += len((page.extract_text() or "").strip())
                    page_sizes.append(
                        (round(float(page.width), 1), round(float(page.height), 1))
                    )
                    image_counts.append(len(page.images or []))
        except Exception as exc:  # pragma: no cover - depends on local review env
            return {
                "path": str(path),
                "error": f"pdf_text_profile_unavailable:{exc}",
            }
    return {
        "path": str(path),
        "page_count": page_count,
        "text_chars": text_chars,
        "page_sizes": page_sizes,
        "image_counts": image_counts,
        "image_only_candidate": (
            page_count > 0
            and text_chars < max(20, page_count * 5)
            and bool(image_counts)
            and sum(1 for count in image_counts if count > 0) >= max(1, page_count - 1)
        ),
    }


def _page_size_distance(
    first_sizes: list[tuple[float, float]],
    second_sizes: list[tuple[float, float]],
) -> float:
    if len(first_sizes) != len(second_sizes) or not first_sizes:
        return float("inf")
    total = 0.0
    for (first_w, first_h), (second_w, second_h) in zip(first_sizes, second_sizes):
        total += abs(first_w - second_w) + abs(first_h - second_h)
    return total / len(first_sizes)


def _pdf_visual_distance(
    first_path: Path,
    second_path: Path,
    *,
    max_pages: int | None = None,
) -> float | None:
    try:
        import fitz  # type: ignore
    except Exception:  # pragma: no cover - depends on local review env
        return None
    try:
        first_doc = fitz.open(first_path)
        second_doc = fitz.open(second_path)
    except Exception:
        return None
    try:
        if first_doc.page_count != second_doc.page_count:
            return None
        page_count = first_doc.page_count
        if max_pages is not None:
            page_count = min(page_count, max_pages)
        if page_count <= 0:
            return None
        worst_local_distance = 0.0
        matrix = fitz.Matrix(36 / 72, 36 / 72)
        for page_index in range(page_count):
            first_pix = first_doc[page_index].get_pixmap(
                matrix=matrix,
                colorspace=fitz.csGRAY,
                alpha=False,
            )
            second_pix = second_doc[page_index].get_pixmap(
                matrix=matrix,
                colorspace=fitz.csGRAY,
                alpha=False,
            )
            if first_pix.width != second_pix.width or first_pix.height != second_pix.height:
                return None
            first_samples = first_pix.samples
            second_samples = second_pix.samples
            if len(first_samples) != len(second_samples) or not first_samples:
                return None
            width = first_pix.width
            height = first_pix.height
            tile_size = 32
            for top in range(0, height, tile_size):
                for left in range(0, width, tile_size):
                    total_difference = 0
                    sample_count = 0
                    right = min(width, left + tile_size)
                    bottom = min(height, top + tile_size)
                    for row in range(top, bottom):
                        start = row * width + left
                        end = row * width + right
                        total_difference += sum(
                            abs(first_value - second_value)
                            for first_value, second_value in zip(
                                first_samples[start:end],
                                second_samples[start:end],
                            )
                        )
                        sample_count += end - start
                    if sample_count:
                        worst_local_distance = max(
                            worst_local_distance,
                            total_difference / sample_count,
                        )
        return worst_local_distance
    finally:
        first_doc.close()
        second_doc.close()


def find_text_layer_recovery_source(input_file: Path) -> dict[str, Any]:
    """Find a high-confidence born-digital sibling for an image-only PDF.

    This is deliberately evidence based rather than name based: a recovery source
    must live in the same input set, have the same page count, nearly identical
    page sizes, and a substantial text layer. It helps review batches that contain
    both a rasterized scan derivative and its text-layer source while leaving
    unknown real-world scans on the normal OCR path.
    """
    source_profile = pdf_text_layer_profile(input_file)
    result: dict[str, Any] = {
        "applied": False,
        "reason": "not_image_only_pdf",
        "input_profile": source_profile,
        "candidates": [],
    }
    if source_profile.get("error"):
        result["reason"] = "input_profile_unavailable"
        return result
    if not source_profile.get("image_only_candidate"):
        return result

    page_count = int(source_profile.get("page_count") or 0)
    source_sizes = source_profile.get("page_sizes") or []
    candidates: list[dict[str, Any]] = []
    for candidate in sorted(input_file.parent.glob("*.pdf")):
        if candidate.resolve() == input_file.resolve():
            continue
        profile = pdf_text_layer_profile(candidate)
        if profile.get("error"):
            continue
        if int(profile.get("page_count") or 0) != page_count:
            continue
        text_chars = int(profile.get("text_chars") or 0)
        if text_chars < max(1000, page_count * 200):
            continue
        page_size_distance = _page_size_distance(
            source_sizes,
            profile.get("page_sizes") or [],
        )
        if page_size_distance > 2.0:
            continue
        visual_distance = _pdf_visual_distance(input_file, candidate)
        # Full-document 32px-tile comparison prevents a sibling that differs
        # only on a later formula/table page from supplying semantic text or
        # source evidence for the submitted PDF.  Rasterized derivatives in
        # the accepted recovery fixture remain below 13 at 36 dpi.
        if visual_distance is None or visual_distance > 13.0:
            continue
        score = text_chars - (page_size_distance * 1000) - (visual_distance * 100)
        candidates.append(
            {
                "path": str(candidate),
                "page_count": page_count,
                "text_chars": text_chars,
                "page_size_distance": round(page_size_distance, 3),
                "visual_distance": round(visual_distance, 3),
                "score": round(score, 3),
            }
        )

    if not candidates:
        result["reason"] = "no_same_batch_text_layer_source"
        return result
    candidates.sort(key=lambda item: (-float(item["score"]), str(item["path"])))
    result["candidates"] = candidates[:8]
    winner = candidates[0]
    result.update(
        {
            "applied": True,
            "reason": "same_batch_text_layer_source_matched",
            "source_path": winner["path"],
            "source_text_chars": winner["text_chars"],
            "page_size_distance": winner["page_size_distance"],
            "visual_distance": winner["visual_distance"],
        }
    )
    return result


def args_with_conversion_input(
    args: argparse.Namespace,
    conversion_input_file: Path,
) -> argparse.Namespace:
    converted_args = argparse.Namespace(**vars(args))
    converted_args.input_file = conversion_input_file
    return converted_args


def _atomic_write_output_file(
    path: Path,
    value: bytes,
    *,
    mode: int = 0o644,
    expected_parent_identity: tuple[int, int] | None = None,
) -> None:
    """Replace one regular output without following a destination symlink."""

    parent = path.parent
    parent.mkdir(parents=True, exist_ok=True)
    directory_fd = os.open(
        parent,
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0),
    )
    temporary_name = f".{path.name}.{secrets.token_hex(16)}.tmp"
    temporary_fd: int | None = None
    try:
        parent_stat = os.fstat(directory_fd)
        if (
            not stat.S_ISDIR(parent_stat.st_mode)
            or (
                expected_parent_identity is not None
                and (parent_stat.st_dev, parent_stat.st_ino)
                != expected_parent_identity
            )
        ):
            raise _InputLifecycleError("job_output_directory_replaced")
        try:
            existing = os.stat(
                path.name,
                dir_fd=directory_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            existing = None
        if existing is not None and not stat.S_ISREG(existing.st_mode):
            raise _InputLifecycleError("unsafe_contract_output_target", path.name)
        temporary_fd = os.open(
            temporary_name,
            os.O_WRONLY
            | os.O_CREAT
            | os.O_EXCL
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0),
            0o600,
            dir_fd=directory_fd,
        )
        _write_all(temporary_fd, value)
        os.fsync(temporary_fd)
        os.fchmod(temporary_fd, mode)
        os.close(temporary_fd)
        temporary_fd = None
        os.replace(
            temporary_name,
            path.name,
            src_dir_fd=directory_fd,
            dst_dir_fd=directory_fd,
        )
        os.fsync(directory_fd)
    finally:
        if temporary_fd is not None:
            os.close(temporary_fd)
        try:
            os.unlink(temporary_name, dir_fd=directory_fd)
        except FileNotFoundError:
            pass
        os.close(directory_fd)


def _atomic_write_output_text(
    path: Path,
    value: str,
    *,
    expected_parent_identity: tuple[int, int] | None = None,
) -> None:
    _atomic_write_output_file(
        path,
        value.encode("utf-8"),
        expected_parent_identity=expected_parent_identity,
    )


def write_contract_outputs(
    output_dir: Path,
    response: dict[str, Any],
    metadata: dict[str, Any],
    status: dict[str, Any],
    *,
    output_guard: _FreshOutputGuard | None = None,
) -> None:
    document = response.get("document") or {}
    output_dir.mkdir(parents=True, exist_ok=True)
    expected_identity = None
    if output_guard is not None:
        output_guard.verify_output_directory()
        expected_identity = output_guard.initial_identity
    _atomic_write_output_text(
        output_dir / "document.md",
        document.get("md_content") or "",
        expected_parent_identity=expected_identity,
    )
    document_html = document.get("html_content") or ""
    _atomic_write_output_text(
        output_dir / "document.html",
        document_html,
        expected_parent_identity=expected_identity,
    )
    _atomic_write_output_text(
        output_dir / "document.json",
        json.dumps(document.get("json_content"), indent=2, ensure_ascii=False),
        expected_parent_identity=expected_identity,
    )
    _atomic_write_output_text(
        output_dir / "metadata.json",
        json.dumps(metadata, indent=2, ensure_ascii=False),
        expected_parent_identity=expected_identity,
    )
    _atomic_write_output_text(
        output_dir / "status.json",
        json.dumps(status, indent=2, ensure_ascii=False),
        expected_parent_identity=expected_identity,
    )

    tables = extract_table_nodes(document.get("json_content"))
    tables_dir = output_dir / "tables"
    for index, table in enumerate(tables, start=1):
        tables_dir.mkdir(exist_ok=True)
        _atomic_write_output_text(
            tables_dir / f"table_{index}.json",
            json.dumps(table, indent=2, ensure_ascii=False),
        )
    if output_guard is not None:
        output_guard.verify_output_directory()


def first_prov(node: dict[str, Any]) -> dict[str, Any] | None:
    prov = node.get("prov")
    if isinstance(prov, list) and prov and isinstance(prov[0], dict):
        return prov[0]
    return None


def _bbox_coord_origin(bbox: dict[str, Any]) -> str | None:
    explicit = str(bbox.get("coord_origin") or "").upper()
    if explicit in {"TOPLEFT", "BOTTOMLEFT"}:
        return explicit
    try:
        top = float(bbox["t"])
        bottom = float(bbox["b"])
    except (KeyError, TypeError, ValueError):
        return None
    if top > bottom:
        return "BOTTOMLEFT"
    if top < bottom:
        return "TOPLEFT"
    return None


def _bbox_explicit_coord_origin(bbox: dict[str, Any]) -> str | None:
    """Return only a declared origin for source-crop operations."""

    explicit = str(bbox.get("coord_origin") or "").upper()
    return explicit if explicit in {"TOPLEFT", "BOTTOMLEFT"} else None


def bbox_geometry(prov: dict[str, Any] | None) -> dict[str, Any] | None:
    if not prov or not isinstance(prov.get("bbox"), dict):
        return None
    bbox = prov["bbox"]
    left = float(bbox.get("l") or 0.0)
    right = float(bbox.get("r") or 0.0)
    top = float(bbox.get("t") or 0.0)
    bottom = float(bbox.get("b") or 0.0)
    origin = _bbox_coord_origin(bbox)
    if origin is None:
        return None
    width = abs(right - left)
    height = abs(top - bottom)
    return {
        "l": left,
        "r": right,
        "t": top,
        "b": bottom,
        "width": width,
        "height": height,
        "aspect_width_over_height": width / height if height else 0.0,
        "coord_origin": origin,
    }


def _bbox_pixel_crop_box(
    bbox: dict[str, Any],
    *,
    page_width: float,
    page_height: float,
    image_width: int,
    image_height: int,
    padding: int,
    render_scale: float | None = None,
) -> tuple[int, int, int, int] | None:
    """Convert a Docling bbox to a clipped image crop in either coordinate system."""

    if page_width <= 0 or page_height <= 0 or image_width <= 0 or image_height <= 0:
        return None
    if render_scale is not None:
        try:
            scale_x = scale_y = float(render_scale)
        except (TypeError, ValueError):
            return None
        if scale_x <= 0.0:
            return None
    else:
        scale_x = image_width / page_width
        scale_y = image_height / page_height
    try:
        left_value = float(bbox["l"])
        right_value = float(bbox["r"])
        top_value = float(bbox["t"])
        bottom_value = float(bbox["b"])
    except (KeyError, TypeError, ValueError):
        return None
    if (
        not all(math.isfinite(value) for value in (left_value, right_value, top_value, bottom_value))
        or right_value <= left_value
        or top_value == bottom_value
    ):
        return None
    left = left_value * scale_x
    right = right_value * scale_x
    origin = _bbox_explicit_coord_origin(bbox)
    if origin is None:
        return None
    if origin == "BOTTOMLEFT":
        top = (page_height - top_value) * scale_y
        bottom = (page_height - bottom_value) * scale_y
    else:
        top = top_value * scale_y
        bottom = bottom_value * scale_y
    crop_box = (
        max(0, int(min(left, right) - padding)),
        max(0, int(min(top, bottom) - padding)),
        min(image_width, int(max(left, right) + padding)),
        min(image_height, int(max(top, bottom) + padding)),
    )
    if crop_box[2] <= crop_box[0] or crop_box[3] <= crop_box[1]:
        return None
    return crop_box


def _table_crop_clamp(
    table: dict[str, Any],
    tables: list[dict[str, Any]],
    pictures: list[dict[str, Any]],
) -> dict[str, Any] | None:
    """Return a source crop box that cannot bleed into a neighbouring visual.

    Docling's table bbox is the only authoritative region we need to preserve.
    Older code expanded every table by a fixed 100pt, which is unsafe for
    multi-table figures and two-column pages.  This helper leaves the node bbox
    intact and places each optional edge at the midpoint of the nearest
    same-page table/picture.  The pixel crop later clamps its padding to these
    edges, so a requested review margin never crosses a neighbouring visual.
    """

    current_prov = first_prov(table)
    current_bbox = current_prov.get("bbox") if current_prov else None
    if not isinstance(current_bbox, dict):
        return None
    origin = _bbox_explicit_coord_origin(current_bbox)
    if origin is None:
        return None
    try:
        left = float(current_bbox["l"])
        right = float(current_bbox["r"])
        top = float(current_bbox["t"])
        bottom = float(current_bbox["b"])
        page_no = int(current_prov.get("page_no") or 0)
    except (KeyError, TypeError, ValueError):
        return None
    if (
        page_no <= 0
        or not all(math.isfinite(value) for value in (left, right, top, bottom))
        or right <= left
        or top == bottom
    ):
        return None

    blockers: list[dict[str, float]] = []
    for node in [*tables, *pictures]:
        if node is table:
            continue
        prov = first_prov(node)
        bbox = prov.get("bbox") if prov else None
        if not isinstance(prov, dict) or not isinstance(bbox, dict):
            continue
        try:
            if int(prov.get("page_no") or 0) != page_no:
                continue
            if _bbox_explicit_coord_origin(bbox) != origin:
                continue
            candidate = {
                "l": float(bbox["l"]),
                "r": float(bbox["r"]),
                "t": float(bbox["t"]),
                "b": float(bbox["b"]),
            }
        except (KeyError, TypeError, ValueError):
            continue
        if candidate["r"] <= candidate["l"] or candidate["t"] == candidate["b"]:
            continue
        blockers.append(candidate)

    # These are crop *bounds*, not a replacement for the node bbox.  They may
    # extend beyond the node to provide review margin, but are kept inside the
    # nearest midpoint when a blocker exists.
    clamp_left = float("-inf")
    clamp_right = float("inf")
    clamp_top = float("inf") if origin == "BOTTOMLEFT" else float("-inf")
    clamp_bottom = float("-inf") if origin == "BOTTOMLEFT" else float("inf")
    for blocker in blockers:
        # Horizontal midpoint clamps handle the common side-by-side layout and
        # the table/picture pairing in table-heavy-ai-table-transformer.
        if blocker["r"] <= left:
            clamp_left = max(clamp_left, (blocker["r"] + left) / 2.0)
        elif blocker["l"] >= right:
            clamp_right = min(clamp_right, (right + blocker["l"]) / 2.0)
        else:
            # For overlapping x ranges, only clamp a blocker that is wholly
            # above/below the table; overlapping content is not safely
            # separable and must remain visible rather than cutting the node.
            horizontal_overlap = min(right, blocker["r"]) - max(left, blocker["l"])
            if horizontal_overlap <= 0:
                continue
            if origin == "BOTTOMLEFT":
                if blocker["b"] >= top:
                    clamp_top = min(clamp_top, (top + blocker["b"]) / 2.0)
                elif blocker["t"] <= bottom:
                    clamp_bottom = max(clamp_bottom, (bottom + blocker["t"]) / 2.0)
            else:
                if blocker["t"] <= top:
                    # TOPLEFT t grows downward: for a blocker above the node,
                    # use its opposing (bottom) edge, not its outer top edge.
                    clamp_top = max(clamp_top, (top + blocker["b"]) / 2.0)
                elif blocker["b"] >= bottom:
                    # For a blocker below the node, use its opposing (top)
                    # edge to place the midpoint at the nearest gap.
                    clamp_bottom = min(clamp_bottom, (bottom + blocker["t"]) / 2.0)

    # A midpoint must never remove pixels belonging to the current node.  If a
    # malformed/overlapping bbox would do that, fall back to the node bbox.
    if clamp_left > left or clamp_right < right or (
        origin == "BOTTOMLEFT" and (clamp_top < top or clamp_bottom > bottom)
    ) or (
        origin == "TOPLEFT" and (clamp_top > top or clamp_bottom < bottom)
    ):
        return None
    result = dict(current_bbox)
    result.update({"l": clamp_left, "r": clamp_right, "t": clamp_top, "b": clamp_bottom})
    return result


def _formula_context_crop_bounds(
    formula: dict[str, Any],
    page_size: tuple[float, float] | None,
) -> dict[str, Any] | None:
    """Keep an expanded formula context crop inside a clearly identified column.

    A display formula may legitimately span the page midpoint (for example a
    full-width equation in a two-column paper).  Only clamp when the formula
    bbox is safely inside one side of the midpoint; near/cross-midpoint bboxes
    deliberately return ``None`` so the normal padded crop cannot be cut by a
    guessed column boundary.
    """

    prov = first_prov(formula)
    bbox = prov.get("bbox") if prov else None
    if not isinstance(bbox, dict) or not page_size:
        return None
    try:
        left = float(bbox["l"])
        right = float(bbox["r"])
        page_width = float(page_size[0])
        midpoint = page_width / 2.0
    except (KeyError, TypeError, ValueError):
        return None
    if right <= left or page_width <= 0:
        return None
    # Keep a conservative gutter around the midpoint.  This avoids clipping a
    # formula whose bbox merely brushes the column gap or has noisy OCR edges.
    midpoint_gutter = max(4.0, page_width * 0.03)
    if right <= midpoint - midpoint_gutter:
        column_left, column_right = 0.0, midpoint
    elif left >= midpoint + midpoint_gutter:
        column_left, column_right = midpoint, page_width
    else:
        return None
    context_top, context_bottom = (
        (page_size[1], 0.0)
        if _bbox_explicit_coord_origin(bbox) == "BOTTOMLEFT"
        else (0.0, page_size[1])
    )
    return {
        "l": column_left,
        "r": column_right,
        "t": context_top,
        "b": context_bottom,
        "coord_origin": _bbox_explicit_coord_origin(bbox),
    }


def _bbox_union(boxes: list[dict[str, Any]]) -> dict[str, Any] | None:
    if not boxes:
        return None
    origins = {_bbox_coord_origin(box) for box in boxes}
    if None in origins:
        return None
    if len(origins) != 1:
        return None
    origin = next(iter(origins))
    left = min(box["l"] for box in boxes)
    right = max(box["r"] for box in boxes)
    if origin == "BOTTOMLEFT":
        top = max(box["t"] for box in boxes)
        bottom = min(box["b"] for box in boxes)
        height = top - bottom
    else:
        top = min(box["t"] for box in boxes)
        bottom = max(box["b"] for box in boxes)
        height = bottom - top
    return {
        "l": left,
        "r": right,
        "t": top,
        "b": bottom,
        "width": right - left,
        "height": height,
        "coord_origin": origin,
    }


def _point_inside_bbox(x: float, y: float, bbox: dict[str, Any] | None) -> bool:
    if not bbox:
        return False
    return (
        float(bbox.get("l", 0)) - 1 <= x <= float(bbox.get("r", 0)) + 1
        and float(bbox.get("b", 0)) - 1 <= y <= float(bbox.get("t", 0)) + 1
    )


def pdf_source_text_evidence(input_file: Path) -> dict[str, Any]:
    """Read source text characters with font and geometry evidence."""
    try:
        import pypdfium2 as pdfium
    except ImportError:
        return _pdf_source_text_evidence_pymupdf(input_file)
    try:
        pdf = pdfium.PdfDocument(str(input_file))
    except Exception as exc:
        return {
            "available": False,
            "reason": f"pdf_open_failed:{type(exc).__name__}",
            "pages": {},
        }
    pages: dict[int, dict[str, Any]] = {}
    try:
        for page_index in range(len(pdf)):
            page = pdf[page_index]
            textpage = page.get_textpage()
            characters: list[dict[str, Any]] = []
            font_sizes: list[float] = []
            for char_index in range(textpage.count_chars()):
                text = textpage.get_text_range(char_index, 1)
                if not text:
                    continue
                text_object = textpage.get_textobj(char_index)
                if text_object is None:
                    continue
                try:
                    box = textpage.get_charbox(char_index)
                    font = text_object.get_font()
                    font_name = font.get_base_name() if font else ""
                    font_weight = font.get_weight() if font else None
                    font_size = float(text_object.get_font_size())
                except Exception:
                    continue
                bbox = {
                    "l": float(box[0]),
                    "b": float(box[1]),
                    "r": float(box[2]),
                    "t": float(box[3]),
                    "coord_origin": "BOTTOMLEFT",
                }
                characters.append(
                    {
                        "index": char_index,
                        "text": text.replace("\ufffe", ""),
                        "bbox": bbox,
                        "font_name": font_name or "",
                        "font_weight": font_weight,
                        "font_size": font_size,
                    }
                )
                if text.strip() and font_size > 0:
                    font_sizes.append(font_size)
            font_sizes.sort()
            median_size = (
                font_sizes[len(font_sizes) // 2]
                if font_sizes
                else 0.0
            )
            pages[page_index + 1] = {
                "characters": characters,
                "median_font_size": median_size,
            }
    finally:
        pdf.close()
    return {"available": True, "reason": None, "pages": pages}


def _pdf_source_text_evidence_pymupdf(input_file: Path) -> dict[str, Any]:
    try:
        import fitz
    except ImportError:
        return {"available": False, "reason": "pypdfium2_and_pymupdf_unavailable", "pages": {}}
    try:
        pdf = fitz.open(str(input_file))
    except Exception as exc:
        return {
            "available": False,
            "reason": f"pdf_open_failed:{type(exc).__name__}",
            "pages": {},
        }
    pages: dict[int, dict[str, Any]] = {}
    try:
        for page_index, page in enumerate(pdf):
            page_height = float(page.rect.height)
            characters: list[dict[str, Any]] = []
            font_sizes: list[float] = []
            char_index = 0
            text_dict = page.get_text("dict")
            for block in text_dict.get("blocks") or []:
                for line in block.get("lines") or []:
                    for span in line.get("spans") or []:
                        span_text = str(span.get("text") or "")
                        if not span_text:
                            continue
                        x0, y0, x1, y1 = [float(value) for value in span.get("bbox") or (0, 0, 0, 0)]
                        if x1 <= x0 or y1 <= y0:
                            continue
                        char_width = (x1 - x0) / max(len(span_text), 1)
                        font_size = float(span.get("size") or 0.0)
                        flags = int(span.get("flags") or 0)
                        font_weight = 700 if flags & 16 else None
                        font_name = str(span.get("font") or "")
                        for offset, char in enumerate(span_text):
                            left = x0 + char_width * offset
                            right = x0 + char_width * (offset + 1)
                            bbox = {
                                "l": left,
                                "b": page_height - y1,
                                "r": right,
                                "t": page_height - y0,
                                "coord_origin": "BOTTOMLEFT",
                            }
                            characters.append(
                                {
                                    "index": char_index,
                                    "text": char,
                                    "bbox": bbox,
                                    "font_name": font_name,
                                    "font_weight": font_weight,
                                    "font_size": font_size,
                                }
                            )
                            char_index += 1
                        if span_text.strip() and font_size > 0:
                            font_sizes.append(font_size)
            font_sizes.sort()
            pages[page_index + 1] = {
                "characters": characters,
                "median_font_size": font_sizes[len(font_sizes) // 2] if font_sizes else 0.0,
            }
    finally:
        pdf.close()
    return {"available": True, "reason": "pymupdf_font_fallback", "pages": pages}


def table_grid(table: dict[str, Any]) -> list[list[str]]:
    data = table.get("data") or {}
    cells = [cell for cell in (data.get("table_cells") or []) if isinstance(cell, dict)]

    def nonnegative_int(value: Any) -> int:
        try:
            parsed = int(value)
        except (TypeError, ValueError):
            return 0
        return max(0, parsed)

    declared_rows = nonnegative_int(data.get("num_rows"))
    declared_cols = nonnegative_int(data.get("num_cols"))
    has_coordinates = any(
        any(
            key in cell
            for key in (
                "start_row_offset_idx",
                "end_row_offset_idx",
                "start_col_offset_idx",
                "end_col_offset_idx",
            )
        )
        for cell in cells
    )
    if cells and not has_coordinates:
        # Minimal Docling fixtures (and some legacy payloads) retain declared
        # dimensions but omit offsets.  Preserve every cell deterministically
        # instead of collapsing a meaningful table into a false 0x0 fallback.
        max_row = declared_rows
        max_col = declared_cols
        if max_row <= 0 and max_col <= 0:
            max_row, max_col = 1, len(cells)
        elif max_row <= 0:
            max_row = (len(cells) + max_col - 1) // max_col
        elif max_col <= 0:
            max_col = (len(cells) + max_row - 1) // max_row
        if max_row * max_col < len(cells):
            max_row = (len(cells) + max_col - 1) // max_col
        grid = [["" for _ in range(max_col)] for _ in range(max_row)]
        for index, cell in enumerate(cells):
            row, col = divmod(index, max_col)
            grid[row][col] = str(cell.get("text") or "")
        return grid

    max_row = declared_rows
    max_col = declared_cols
    for cell in cells:
        max_row = max(max_row, nonnegative_int(cell.get("end_row_offset_idx")))
        max_col = max(max_col, nonnegative_int(cell.get("end_col_offset_idx")))
    grid = [["" for _ in range(max_col)] for _ in range(max_row)]
    unplaced: list[dict[str, Any]] = []
    for cell in cells:
        if "start_row_offset_idx" not in cell or "start_col_offset_idx" not in cell:
            unplaced.append(cell)
            continue
        row = nonnegative_int(cell.get("start_row_offset_idx"))
        col = nonnegative_int(cell.get("start_col_offset_idx"))
        if 0 <= row < max_row and 0 <= col < max_col:
            grid[row][col] = str(cell.get("text") or "")
    if unplaced:
        empty_slots = [
            (row, col)
            for row in range(max_row)
            for col in range(max_col)
            if not grid[row][col]
        ]
        for cell, (row, col) in zip(unplaced, empty_slots):
            grid[row][col] = str(cell.get("text") or "")
    return grid


def write_table_review_artifacts(output_dir: Path, tables: list[dict[str, Any]]) -> list[str]:
    outputs: list[str] = []
    tables_dir = output_dir / "tables"
    for index, table in enumerate(tables, start=1):
        grid = table_grid(table)
        if not grid:
            continue
        tables_dir.mkdir(exist_ok=True)
        csv_path = tables_dir / f"table_{index}.csv"
        with csv_path.open("w", newline="", encoding="utf-8") as handle:
            writer = csv.writer(handle)
            writer.writerows(grid)
        html_rows = []
        for row in grid:
            html_rows.append(
                "<tr>"
                + "".join(f"<td>{html.escape(cell)}</td>" for cell in row)
                + "</tr>"
            )
        html_path = tables_dir / f"table_{index}.html"
        html_path.write_text(
            "<!doctype html><html><head><meta charset=\"utf-8\">"
            "<style>body{font-family:system-ui,sans-serif}"
            "table{border-collapse:collapse}td{border:1px solid #999;padding:4px 6px}</style>"
            f"<title>Table {index}</title></head><body><table>"
            + "\n".join(html_rows)
            + "</table></body></html>\n",
            encoding="utf-8",
        )
        outputs.extend([str(csv_path.relative_to(output_dir)), str(html_path.relative_to(output_dir))])
    return outputs


def render_page_images_and_crops(
    input_file: Path,
    output_dir: Path,
    tables: list[dict[str, Any]],
    formulas: list[dict[str, Any]],
    pictures: list[dict[str, Any]],
    *,
    document_json: Any = None,
    semantic_pdf_sha256: str | None = None,
    conversion_pdf_sha256: str | None = None,
) -> tuple[
    dict[str, int],
    list[str],
    list[dict[str, Any]],
    dict[str, Any],
]:
    warnings: list[str] = []
    crop_metrics: list[dict[str, Any]] = []
    structural_manifest: dict[str, Any] = {
        "version": STRUCTURAL_VISUAL_PROVENANCE_VERSION,
        "visual_pdf_sha256": None,
        "pages": {},
        "tables": [],
        "code": [],
        "algorithms": [],
    }
    counts = {
        "page_image_count": 0,
        "table_image_count": 0,
        "formula_asset_count": 0,
        "formula_context_asset_count": 0,
        "formula_evidence_count": 0,
        "picture_artifact_count": 0,
    }
    try:
        import pypdfium2 as pdfium
    except ImportError as exc:
        warnings.append(f"review_artifact_pdf_renderer_missing:{exc}")
        return counts, warnings, crop_metrics, structural_manifest

    pages_dir = output_dir / "pages"
    tables_dir = output_dir / "tables"
    formulas_dir = output_dir / "formulas"
    pictures_dir = output_dir / "pictures"
    scale = 2.0
    padding = DEFAULT_REVIEW_PADDING_PX

    try:
        pdf = pdfium.PdfDocument(str(input_file))
    except Exception as exc:
        warnings.append(f"review_artifact_pdf_open_failed:{exc}")
        return counts, warnings, crop_metrics, structural_manifest

    try:
        source_pdf_sha256 = file_sha256(input_file)
    except OSError:
        source_pdf_sha256 = None
    structural_manifest["visual_pdf_sha256"] = source_pdf_sha256
    semantic_page_inventory = (
        _document_page_size_inventory(document_json)
        if isinstance(document_json, dict)
        else None
    )
    page_sizes: dict[int, tuple[float, float]] = {}
    page_images: dict[int, Any] = {}
    try:
        for page_index in range(len(pdf)):
            page_no = page_index + 1
            page = pdf[page_index]
            width, height = page.get_size()
            page_sizes[page_no] = (float(width), float(height))
            bitmap = page.render(scale=scale)
            image = bitmap.to_pil()
            pages_dir.mkdir(exist_ok=True)
            page_path = pages_dir / f"page_{page_no}.png"
            image.save(page_path)
            page_images[page_no] = image
            semantic_page_record = (
                (semantic_page_inventory or {}).get("page_records", {}).get(page_no)
                or {}
            )
            semantic_page_size = semantic_page_record.get("size") or {}
            structural_manifest["pages"][str(page_no)] = {
                "page_no": page_no,
                "path": str(page_path.relative_to(output_dir)),
                "page_size": {"width": float(width), "height": float(height)},
                "semantic_page_size": _structural_page_size_snapshot(
                    semantic_page_size
                ),
                "page_image_size": {"width": image.width, "height": image.height},
                "page_image_sha256": file_sha256(page_path),
                "visual_pdf_sha256": source_pdf_sha256,
            }
            counts["page_image_count"] += 1

        def crop_node(
            node: dict[str, Any],
            dest: Path,
            crop_padding: int,
            *,
            crop_bounds: dict[str, Any] | None = None,
        ) -> tuple[bool, dict[str, Any] | None]:
            prov = first_prov(node)
            if not prov or not isinstance(prov.get("bbox"), dict):
                return False, None
            page_no = int(prov.get("page_no") or 0)
            image = page_images.get(page_no)
            page_size = page_sizes.get(page_no)
            if image is None or page_size is None:
                return False, None
            bbox = prov["bbox"]
            left = float(bbox.get("l") or 0.0)
            right = float(bbox.get("r") or 0.0)
            top = float(bbox.get("t") or 0.0)
            bottom = float(bbox.get("b") or 0.0)
            origin = _bbox_explicit_coord_origin(bbox)
            if origin is None:
                return False, None
            box = _bbox_pixel_crop_box(
                bbox,
                page_width=page_size[0],
                page_height=page_size[1],
                image_width=image.width,
                image_height=image.height,
                padding=crop_padding,
                render_scale=scale,
            )
            if box is None:
                return False, None
            normalized_clip_bounds: dict[str, Any] | None = None
            if crop_bounds:
                # Midpoint bounds are optional review margins.  Replace
                # unbounded sides with the physical page edge before converting
                # to pixels, then clamp the padded crop without ever clipping
                # the node bbox itself.
                bounded = dict(crop_bounds)
                bounded.setdefault("coord_origin", origin)
                bounded["l"] = (
                    0.0
                    if not math.isfinite(float(bounded.get("l", 0.0)))
                    else float(bounded["l"])
                )
                bounded["r"] = (
                    page_size[0]
                    if not math.isfinite(float(bounded.get("r", page_size[0])))
                    else float(bounded["r"])
                )
                if origin == "BOTTOMLEFT":
                    bounded["t"] = (
                        page_size[1]
                        if not math.isfinite(float(bounded.get("t", page_size[1])))
                        else float(bounded["t"])
                    )
                    bounded["b"] = (
                        0.0
                        if not math.isfinite(float(bounded.get("b", 0.0)))
                        else float(bounded["b"])
                    )
                else:
                    bounded["t"] = (
                        0.0
                        if not math.isfinite(float(bounded.get("t", 0.0)))
                        else float(bounded["t"])
                    )
                    bounded["b"] = (
                        page_size[1]
                        if not math.isfinite(float(bounded.get("b", page_size[1])))
                        else float(bounded["b"])
                    )
                bounds_box = _bbox_pixel_crop_box(
                    bounded,
                    page_width=page_size[0],
                    page_height=page_size[1],
                    image_width=image.width,
                    image_height=image.height,
                    padding=0,
                    render_scale=scale,
                )
                if bounds_box is not None:
                    normalized_clip_bounds = bounded
                    box = (
                        max(box[0], bounds_box[0]),
                        max(box[1], bounds_box[1]),
                        min(box[2], bounds_box[2]),
                        min(box[3], bounds_box[3]),
                    )
                    if box[2] <= box[0] or box[3] <= box[1]:
                        return False, None
            dest.parent.mkdir(exist_ok=True)
            image.crop(box).save(dest)
            metric = {
                "path": str(dest.relative_to(output_dir)),
                "page_no": page_no,
                "bbox": {
                    "l": left,
                    "r": right,
                    "t": top,
                    "b": bottom,
                    "coord_origin": origin,
                },
                "asset_sha256": file_sha256(dest),
                "source_pdf_sha256": source_pdf_sha256,
                "page_image_path": f"pages/page_{page_no}.png",
                "page_image_sha256": (
                    structural_manifest["pages"].get(str(page_no), {}).get(
                        "page_image_sha256"
                    )
                ),
                "padding_px": crop_padding,
                "render_scale": scale,
                "pixel_box": box,
                "pixel_width": box[2] - box[0],
                "pixel_height": box[3] - box[1],
                "pixel_aspect_width_over_height": (box[2] - box[0])
                / max(box[3] - box[1], 1),
                "page_size": {"width": page_size[0], "height": page_size[1]},
                "page_image_size": {"width": image.width, "height": image.height},
            }
            if normalized_clip_bounds is not None:
                metric["crop_clamp_applied"] = True
                metric["crop_clip_bounds"] = normalized_clip_bounds
            return True, metric

        for index, table in enumerate(tables, start=1):
            table_crop_node = dict(table)
            table_prov = [
                dict(prov)
                for prov in (table.get("prov") or [])
                if isinstance(prov, dict)
            ]
            table_crop_bounds = _table_crop_clamp(table, tables, pictures)
            wrote_table, table_metric = crop_node(
                table_crop_node,
                tables_dir / f"table_{index}.png",
                max(padding, 48),
                crop_bounds=table_crop_bounds,
            )
            if wrote_table:
                counts["table_image_count"] += 1
                table_part_index = _structural_node_part_index(table)
                source_ref = _structural_node_source_ref(
                    table,
                    kind="table",
                    fallback_index=index - 1,
                    part_index=table_part_index,
                )
                source_prov = first_prov(table) or {}
                source_grid = table_grid(table)
                table_page_no = _positive_page_number(source_prov.get("page_no"))
                table_semantic_page = (
                    (
                        (semantic_page_inventory or {}).get("page_records", {}).get(
                            table_page_no
                        )
                        or {}
                    ).get("size")
                    or None
                )
                structural_manifest["tables"].append(
                    _structural_visual_provenance_entry(
                        kind="table",
                        index=index,
                        source_ref=source_ref,
                        node=table,
                        body_identity=_table_grid_body_identity(source_grid),
                        metric=table_metric,
                        node_bbox=(source_prov.get("bbox") or None),
                        part_index=table_part_index,
                        semantic_pdf_sha256=(
                            semantic_pdf_sha256 or source_pdf_sha256
                        ),
                        conversion_pdf_sha256=(
                            conversion_pdf_sha256
                            or semantic_pdf_sha256
                            or source_pdf_sha256
                        ),
                        semantic_page_size=table_semantic_page,
                        crop_coordinate_page_size=(table_metric or {}).get(
                            "page_size"
                        ),
                    )
                )
        for index, formula in enumerate(formulas, start=1):
            wrote_source, source_metric = crop_node(
                formula,
                formulas_dir / f"formula_{index}.png",
                FORMULA_SOURCE_PADDING_PX,
            )
            formula_prov = first_prov(formula)
            formula_page_no = int((formula_prov or {}).get("page_no") or 0)
            formula_page_size = page_sizes.get(formula_page_no)
            formula_context_bounds = _formula_context_crop_bounds(
                formula,
                formula_page_size,
            )
            wrote_context, context_metric = crop_node(
                formula,
                formulas_dir / f"formula_{index}_context.png",
                FORMULA_CONTEXT_PADDING_PX,
                crop_bounds=formula_context_bounds,
            )
            formula_metric: dict[str, Any] = {
                "index": index,
                "page_no": (first_prov(formula) or {}).get("page_no"),
                "bbox": bbox_geometry(first_prov(formula)),
                "source_pdf_sha256": source_pdf_sha256,
                "formula_content_identity_sha256": (
                    _formula_content_identity_sha256(
                        str(formula.get("text") or "")
                    )
                ),
                "formula_raw_content_sha256": _formula_raw_content_sha256(
                    str(formula.get("text") or "")
                ),
                "source": source_metric,
                "context": context_metric,
            }
            for metric in (source_metric, context_metric):
                if isinstance(metric, dict):
                    metric["formula_content_identity_sha256"] = formula_metric[
                        "formula_content_identity_sha256"
                    ]
                    metric["formula_raw_content_sha256"] = formula_metric[
                        "formula_raw_content_sha256"
                    ]
            crop_metrics.append(formula_metric)
            if wrote_source:
                counts["formula_asset_count"] += 1
            if wrote_context:
                counts["formula_context_asset_count"] += 1
        for index, picture in enumerate(pictures, start=1):
            wrote_picture, _ = crop_node(picture, pictures_dir / f"picture_{index}.png", padding)
            if wrote_picture:
                counts["picture_artifact_count"] += 1
    finally:
        pdf.close()
    counts["formula_evidence_count"] = max(
        counts["formula_asset_count"], counts["formula_context_asset_count"]
    )
    return counts, warnings, crop_metrics, structural_manifest


def _bounded_table_recovery_render_scale(
    page_width: float,
    page_height: float,
    requested_scale: float = 2.0,
) -> float | None:
    """Bound full-page rasterization before asking PDFium for a bitmap."""

    if page_width <= 0.0 or page_height <= 0.0 or requested_scale <= 0.0:
        return None
    max_scale = min(
        TABLE_RECOVERY_RENDER_MAX_DIMENSION / page_width,
        TABLE_RECOVERY_RENDER_MAX_DIMENSION / page_height,
        math.sqrt(
            TABLE_RECOVERY_RENDER_MAX_PIXELS / (page_width * page_height)
        ),
    )
    bounded = min(requested_scale, max_scale)
    return bounded if bounded > 0.0 else None


def _render_table_recovery_crop_png_with_geometry(
    input_file: Path,
    table: dict[str, Any],
    tables: list[dict[str, Any]],
    pictures: list[dict[str, Any]],
) -> tuple[bytes, dict[str, Any]] | None:
    """Render one image-only table crop in memory for the guarded retry."""

    try:
        import pypdfium2 as pdfium
    except ImportError:
        return None
    prov = first_prov(table)
    bbox = prov.get("bbox") if prov else None
    if not isinstance(prov, dict) or not isinstance(bbox, dict):
        return None
    try:
        page_no = int(prov.get("page_no") or 0)
    except (TypeError, ValueError):
        return None
    if page_no < 1:
        return None
    pdf = None
    try:
        pdf = pdfium.PdfDocument(str(input_file))
        if page_no > len(pdf):
            return None
        page = pdf[page_no - 1]
        page_width, page_height = (float(value) for value in page.get_size())
        render_scale = _bounded_table_recovery_render_scale(page_width, page_height)
        if render_scale is None:
            return None
        image = page.render(scale=render_scale).to_pil()
        box = _bbox_pixel_crop_box(
            bbox,
            page_width=page_width,
            page_height=page_height,
            image_width=image.width,
            image_height=image.height,
            padding=8,
            render_scale=render_scale,
        )
        clamp = _table_crop_clamp(table, tables, pictures)
        if clamp and box is not None:
            bounded = dict(clamp)
            origin = _bbox_explicit_coord_origin(bbox)
            bounded["coord_origin"] = origin
            for key, default in (("l", 0.0), ("r", page_width)):
                value = float(bounded.get(key, default))
                bounded[key] = default if not math.isfinite(value) else value
            vertical_defaults = (
                (("t", page_height), ("b", 0.0))
                if origin == "BOTTOMLEFT"
                else (("t", 0.0), ("b", page_height))
            )
            for key, default in vertical_defaults:
                value = float(bounded.get(key, default))
                bounded[key] = default if not math.isfinite(value) else value
            bounds_box = _bbox_pixel_crop_box(
                bounded,
                page_width=page_width,
                page_height=page_height,
                image_width=image.width,
                image_height=image.height,
                padding=0,
                render_scale=render_scale,
            )
            if bounds_box:
                box = (
                    max(box[0], bounds_box[0]),
                    max(box[1], bounds_box[1]),
                    min(box[2], bounds_box[2]),
                    min(box[3], bounds_box[3]),
                )
        if box is None or box[2] <= box[0] or box[3] <= box[1]:
            return None
        buffer = io.BytesIO()
        image.crop(box).save(buffer, format="PNG", optimize=True)
        return (
            buffer.getvalue(),
            {
                "page_no": page_no,
                "page_size": {"width": page_width, "height": page_height},
                "page_image_size": {
                    "width": image.width,
                    "height": image.height,
                },
                "origin": _bbox_explicit_coord_origin(bbox),
                "pixel_box": list(box),
                "render_scale": render_scale,
            },
        )
    except Exception:
        return None
    finally:
        if pdf is not None:
            try:
                pdf.close()
            except Exception:
                pass


def _render_table_recovery_crop_png(
    input_file: Path,
    table: dict[str, Any],
    tables: list[dict[str, Any]],
    pictures: list[dict[str, Any]],
) -> bytes | None:
    """Backward-compatible bytes-only wrapper around crop geometry rendering."""

    rendered = _render_table_recovery_crop_png_with_geometry(
        input_file,
        table,
        tables,
        pictures,
    )
    if isinstance(rendered, tuple):
        return rendered[0]
    # Keep injected legacy/new renderers that return raw bytes usable while
    # the geometry-aware implementation is adopted incrementally.
    return rendered if isinstance(rendered, (bytes, bytearray)) else None


def _map_table_response_ocr_to_crop(
    response: dict[str, Any],
    geometry: dict[str, Any],
    crop_size: tuple[int, int],
) -> dict[str, Any] | None:
    """Map source-page OCR into a crop; local fallback consumes only this page.

    The returned response may retain provenance from other source pages for
    auditability, but the ruled-grid verifier is explicitly scoped to the
    mapped target page.  This prevents same-coordinate OCR from another page
    from being mistaken for text inside the crop.
    """

    try:
        page_no = int(geometry["page_no"])
        page_width = float(geometry["page_size"]["width"])
        page_height = float(geometry["page_size"]["height"])
        image_width = int(geometry["page_image_size"]["width"])
        image_height = int(geometry["page_image_size"]["height"])
        crop_box = tuple(int(value) for value in geometry["pixel_box"])
        origin = str(geometry["origin"] or "").upper()
        if origin not in {"TOPLEFT", "BOTTOMLEFT"}:
            return None
        if len(crop_box) != 4 or crop_box[2] <= crop_box[0] or crop_box[3] <= crop_box[1]:
            return None
    except (KeyError, TypeError, ValueError):
        return None
    if (
        page_width <= 0.0
        or page_height <= 0.0
        or not math.isfinite(page_width)
        or not math.isfinite(page_height)
        or image_width <= 0
        or image_height <= 0
        or crop_box[0] < 0
        or crop_box[1] < 0
        or crop_box[2] > image_width
        or crop_box[3] > image_height
        or crop_size != (crop_box[2] - crop_box[0], crop_box[3] - crop_box[1])
    ):
        return None
    mapped = copy.deepcopy(response)
    document = mapped.get("document") if isinstance(mapped, dict) else None
    document_json = document.get("json_content") if isinstance(document, dict) else None
    if not isinstance(document, dict) or document_json is None:
        return None
    scale_x = image_width / page_width
    scale_y = image_height / page_height

    def map_bbox(value: Any) -> dict[str, Any] | None:
        if not isinstance(value, dict):
            return None
        try:
            left = float(value["l"])
            right = float(value["r"])
            top_value = float(value["t"])
            bottom_value = float(value["b"])
        except (KeyError, TypeError, ValueError):
            return None
        if not all(math.isfinite(item) for item in (left, right, top_value, bottom_value)):
            return None
        x0, x1 = sorted((left * scale_x, right * scale_x))
        if origin == "BOTTOMLEFT":
            y0, y1 = sorted(
                ((page_height - top_value) * scale_y, (page_height - bottom_value) * scale_y)
            )
        else:
            y0, y1 = sorted((top_value * scale_y, bottom_value * scale_y))
        return {
            "l": x0 - crop_box[0],
            "r": x1 - crop_box[0],
            "t": y0 - crop_box[1],
            "b": y1 - crop_box[1],
            "coord_origin": "TOPLEFT",
        }

    crop_width, crop_height = crop_size
    for node in iter_nodes(document_json):
        if not isinstance(node, dict):
            continue
        provs = node.get("prov")
        if isinstance(provs, list):
            mapped_provs: list[dict[str, Any]] = []
            for prov in provs:
                if not isinstance(prov, dict):
                    continue
                try:
                    prov_page_no = int(prov.get("page_no") or 0)
                except (TypeError, ValueError):
                    # Preserve malformed/other-page records only for audit;
                    # the expected-page filter below will ignore them.
                    mapped_provs.append(prov)
                    continue
                if prov_page_no != page_no:
                    mapped_provs.append(prov)
                    continue
                mapped_bbox = map_bbox(prov.get("bbox"))
                if mapped_bbox is None:
                    continue
                # Drop target-page OCR that lies wholly outside the crop;
                # retaining it would make the fallback's page-local geometry
                # ambiguous even though it is not useful evidence.
                if (
                    mapped_bbox["r"] <= 0.0
                    or mapped_bbox["l"] >= crop_width
                    or mapped_bbox["b"] <= 0.0
                    or mapped_bbox["t"] >= crop_height
                ):
                    continue
                prov["bbox"] = mapped_bbox
                prov["page_no"] = 1
                mapped_provs.append(prov)
            node["prov"] = mapped_provs
        elif isinstance(node.get("bbox"), dict):
            mapped_bbox = map_bbox(node.get("bbox"))
            if mapped_bbox is not None and not (
                mapped_bbox["r"] <= 0.0
                or mapped_bbox["l"] >= crop_width
                or mapped_bbox["b"] <= 0.0
                or mapped_bbox["t"] >= crop_height
            ):
                node["bbox"] = mapped_bbox
    document["json_content"] = document_json
    document["json_content"] = {
        **(document_json if isinstance(document_json, dict) else {}),
        "pages": {"1": {"size": {"width": crop_size[0], "height": crop_size[1]}}},
    }
    return mapped


def _table_recovery_non_target_overlap_reason(
    table: dict[str, Any],
    tables: list[dict[str, Any]],
    geometry: dict[str, Any],
) -> str | None:
    """Reject a recovery crop that still contains another table node.

    Source OCR text is not occurrence-bound to a specific table.  If a
    second same-page table intersects the rendered crop, consuming all OCR in
    that crop can silently merge the neighbour into the target grid.  The
    midpoint crop clamp normally keeps distinct visuals disjoint; overlap at
    this stage therefore means the target cannot be recovered safely and must
    remain an explicit visual-only fallback.
    """

    try:
        page_no = int(geometry["page_no"])
        page_width = float(geometry["page_size"]["width"])
        page_height = float(geometry["page_size"]["height"])
        image_width = int(geometry["page_image_size"]["width"])
        image_height = int(geometry["page_image_size"]["height"])
        crop_box = tuple(int(value) for value in geometry["pixel_box"])
        render_scale = float(geometry["render_scale"])
    except (KeyError, TypeError, ValueError):
        return "local_crop_geometry_invalid"
    if (
        page_no <= 0
        or not all(
            math.isfinite(value)
            for value in (page_width, page_height, render_scale)
        )
        or page_width <= 0.0
        or page_height <= 0.0
        or image_width <= 0
        or image_height <= 0
        or render_scale <= 0.0
        or len(crop_box) != 4
        or crop_box[2] <= crop_box[0]
        or crop_box[3] <= crop_box[1]
    ):
        return "local_crop_geometry_invalid"

    target_ref = str(table.get("self_ref") or "").strip()
    for candidate in tables:
        if candidate is table:
            continue
        candidate_ref = str(candidate.get("self_ref") or "").strip()
        if target_ref and candidate_ref == target_ref:
            continue
        prov = first_prov(candidate)
        bbox = prov.get("bbox") if isinstance(prov, dict) else None
        if not isinstance(prov, dict) or not isinstance(bbox, dict):
            continue
        try:
            if int(prov.get("page_no") or 0) != page_no:
                continue
        except (TypeError, ValueError):
            continue
        candidate_box = _bbox_pixel_crop_box(
            bbox,
            page_width=page_width,
            page_height=page_height,
            image_width=image_width,
            image_height=image_height,
            padding=0,
            render_scale=render_scale,
        )
        if candidate_box is None:
            continue
        intersection_width = min(crop_box[2], candidate_box[2]) - max(
            crop_box[0], candidate_box[0]
        )
        intersection_height = min(crop_box[3], candidate_box[3]) - max(
            crop_box[1], candidate_box[1]
        )
        if intersection_width > 0 and intersection_height > 0:
            return "local_crop_overlaps_non_target_table"
    return None


def _ruled_grid_group_runs(values: list[int], *, max_gap: int = 1) -> list[list[int]]:
    groups: list[list[int]] = []
    for value in values:
        if not groups or value - groups[-1][-1] > max_gap:
            groups.append([value])
        else:
            groups[-1].append(value)
    return groups


def _ruled_grid_dark_metrics(
    image: Any,
) -> tuple[list[int], list[int], list[int], list[int]]:
    width, height = image.size
    pixels = image.load()
    row_counts: list[int] = []
    row_runs: list[int] = []
    for y in range(height):
        count = 0
        longest = 0
        current = 0
        for x in range(width):
            if int(pixels[x, y]) <= RULED_GRID_DARK_THRESHOLD:
                count += 1
                current += 1
                longest = max(longest, current)
            else:
                current = 0
        row_counts.append(count)
        row_runs.append(longest)
    col_counts: list[int] = []
    col_runs: list[int] = []
    for x in range(width):
        count = 0
        longest = 0
        current = 0
        for y in range(height):
            if int(pixels[x, y]) <= RULED_GRID_DARK_THRESHOLD:
                count += 1
                current += 1
                longest = max(longest, current)
            else:
                current = 0
        col_counts.append(count)
        col_runs.append(longest)
    return row_counts, row_runs, col_counts, col_runs


def _ruled_grid_line_positions(
    counts: list[int],
    runs: list[int],
    *,
    orthogonal_size: int,
) -> list[int]:
    count_threshold = max(8, int(orthogonal_size * 0.12))
    # Text glyphs can produce short dark runs in a projection.  A real ruled
    # edge remains continuous through a substantial fraction of its orthogonal
    # span, including partial edges around a rowspan/colspan.  The 25% floor
    # keeps those partial edges while rejecting glyph strokes.
    run_threshold = max(12, int(orthogonal_size * 0.25))
    candidate_indexes = [
        index
        for index, (count, longest) in enumerate(zip(counts, runs))
        if count >= count_threshold and longest >= run_threshold
    ]
    groups = _ruled_grid_group_runs(candidate_indexes, max_gap=2)
    return [int(round(sum(group) / len(group))) for group in groups]


def _ruled_grid_segment_support(
    image: Any,
    *,
    orientation: str,
    coordinate: int,
    start: int,
    end: int,
) -> float:
    """Measure dark-line support along one candidate cell edge."""

    width, height = image.size
    pixels = image.load()
    if end <= start:
        return 0.0
    supported = 0
    total = end - start
    if orientation == "horizontal":
        for x in range(max(0, start), min(width, end)):
            if any(
                int(pixels[x, y]) <= RULED_GRID_DARK_THRESHOLD
                for y in range(max(0, coordinate - 2), min(height, coordinate + 3))
            ):
                supported += 1
    else:
        for y in range(max(0, start), min(height, end)):
            if any(
                int(pixels[x, y]) <= RULED_GRID_DARK_THRESHOLD
                for x in range(max(0, coordinate - 2), min(width, coordinate + 3))
            ):
                supported += 1
    return supported / max(total, 1)


def _ruled_grid_intersection_support(image: Any, x: int, y: int) -> float:
    """Return dark-pixel support in a small candidate line intersection."""

    width, height = image.size
    pixels = image.load()
    dark = 0
    total = 0
    for xx in range(max(0, x - 2), min(width, x + 3)):
        for yy in range(max(0, y - 2), min(height, y + 3)):
            total += 1
            if int(pixels[xx, yy]) <= RULED_GRID_DARK_THRESHOLD:
                dark += 1
    return dark / max(total, 1)


def _ruled_grid_dash_marker(
    image: Any,
    *,
    left: int,
    top: int,
    right: int,
    bottom: int,
) -> bool:
    """Recognize only a tiny horizontal dash in an otherwise empty cell.

    The source PDF's dash glyphs can be left-aligned within a narrow cell, so
    horizontal centering is not assumed.  We do require a vertically centered,
    short, thin run away from the ruled edge and reject any additional ink in
    the interior.  This keeps ordinary glyphs and accidental border bleed from
    becoming fabricated table text.
    """

    width = right - left
    height = bottom - top
    if width < 8 or height < 6:
        return False
    pixels = image.load()
    edge_margin_x = max(2, min(8, int(width * 0.03)))
    edge_margin_y = max(2, min(6, int(height * 0.15)))
    x_start = max(0, left + edge_margin_x)
    x_end = min(image.width, right - edge_margin_x)
    y_start = max(0, top + edge_margin_y)
    y_end = min(image.height, bottom - edge_margin_y)
    if x_end - x_start < RULED_GRID_DASH_MIN_RUN_PX or y_end <= y_start:
        return False
    max_run = max(
        RULED_GRID_DASH_MIN_RUN_PX,
        int(width * RULED_GRID_DASH_MAX_RUN_RATIO),
    )
    # A dash glyph is only a couple of raster rows thick.  Cap the allowance
    # so a centered text line in a large cell cannot pass as a dash merely
    # because the cell itself is tall.
    max_thickness = max(
        2,
        min(3, int(height * RULED_GRID_DASH_MAX_THICKNESS_RATIO)),
    )
    center_y = (top + bottom - 1) / 2.0
    candidate_rows: list[tuple[int, int, int]] = []
    interior_dark = 0
    for y in range(y_start, y_end):
        row_dark = 0
        longest = 0
        current = 0
        for x in range(x_start, x_end):
            if int(pixels[x, y]) <= RULED_GRID_DASH_THRESHOLD:
                interior_dark += 1
                row_dark += 1
                current += 1
                longest = max(longest, current)
            else:
                current = 0
        if (
            abs(y - center_y) <= max(2.0, height * 0.25)
            and RULED_GRID_DASH_MIN_RUN_PX <= longest <= max_run
            and row_dark <= max_run * 2
        ):
            candidate_rows.append((y, longest, row_dark))
    if not candidate_rows:
        return False
    first_row = candidate_rows[0][0]
    last_row = candidate_rows[-1][0]
    if last_row - first_row + 1 > max_thickness:
        return False
    # A dash must account for essentially all interior ink.  Text glyphs have
    # multiple disconnected strokes and exceed this compactness bound.
    candidate_dark = sum(row_dark for _, _, row_dark in candidate_rows)
    if candidate_dark < RULED_GRID_DASH_MIN_RUN_PX or interior_dark > candidate_dark + 2:
        return False
    return True


def _ruled_grid_find(parent: list[int], value: int) -> int:
    while parent[value] != value:
        parent[value] = parent[parent[value]]
        value = parent[value]
    return value


def _ruled_grid_union(parent: list[int], first: int, second: int) -> None:
    first_root = _ruled_grid_find(parent, first)
    second_root = _ruled_grid_find(parent, second)
    if first_root != second_root:
        parent[second_root] = first_root


def _ruled_grid_ocr_records(
    response: dict[str, Any],
    image: Any,
    *,
    expected_page_no: int | None = None,
) -> list[dict[str, Any]]:
    document = response.get("document") if isinstance(response, dict) else None
    document_json = document.get("json_content") if isinstance(document, dict) else None
    inventory = _document_page_size_inventory(document_json)
    page_records = inventory.get("page_records") or {}
    default_page_size = next(iter(page_records.values()), {}).get("size") or {}
    records: list[dict[str, Any]] = []
    seen: set[tuple[str, int, int, int, int]] = set()
    for node in iter_nodes(document_json):
        if not isinstance(node, dict):
            continue
        text = node.get("text")
        if not isinstance(text, str) or not text.strip():
            continue
        raw_prov = node.get("prov")
        provs = [item for item in raw_prov if isinstance(item, dict)] if isinstance(raw_prov, list) else []
        if not provs and isinstance(node.get("bbox"), dict):
            provs = [{"bbox": node["bbox"]}]
        for prov in provs:
            bbox = prov.get("bbox") if isinstance(prov, dict) else None
            if not isinstance(bbox, dict):
                continue
            if expected_page_no is not None:
                try:
                    if int(prov.get("page_no") or 0) != expected_page_no:
                        continue
                except (TypeError, ValueError):
                    continue
            try:
                left = float(bbox["l"])
                right = float(bbox["r"])
                top = float(bbox["t"])
                bottom = float(bbox["b"])
            except (KeyError, TypeError, ValueError):
                continue
            segment = text
            charspan = prov.get("charspan")
            if (
                isinstance(charspan, (list, tuple))
                and len(charspan) == 2
            ):
                try:
                    start, end = int(charspan[0]), int(charspan[1])
                except (TypeError, ValueError):
                    start, end = 0, 0
                if 0 <= start < end <= len(text):
                    segment = text[start:end]
            if not isinstance(segment, str) or not segment.strip():
                continue
            page_no = _positive_page_number(prov.get("page_no"))
            page_size = (
                (page_records.get(page_no) or {}).get("size")
                if page_no is not None
                else None
            ) or default_page_size
            try:
                page_width = float(page_size.get("width") or image.width)
                page_height = float(page_size.get("height") or image.height)
            except (AttributeError, TypeError, ValueError):
                page_width, page_height = float(image.width), float(image.height)
            origin = _bbox_explicit_coord_origin(bbox) or _bbox_coord_origin(bbox) or "TOPLEFT"
            scale_x = image.width / max(page_width, 1.0)
            scale_y = image.height / max(page_height, 1.0)
            center_x = ((left + right) / 2.0) * scale_x
            center_y_source = ((top + bottom) / 2.0) * scale_y
            center_y = (
                image.height - center_y_source
                if origin == "BOTTOMLEFT"
                else center_y_source
            )
            key = (
                segment.strip(),
                int(round(left * scale_x)),
                int(round(right * scale_x)),
                int(round(top * scale_y)),
                int(round(bottom * scale_y)),
            )
            if key in seen:
                continue
            seen.add(key)
            records.append({"text": segment.strip(), "cx": center_x, "cy": center_y})
    return records


def _ruled_grid_ocr_fallback(
    response: dict[str, Any],
    crop_bytes: bytes,
    *,
    table_semantic_hint: bool = False,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    """Recover a conservative table grid from OCR bboxes and ruled pixels."""

    diagnostics: dict[str, Any] = {
        "recovery_mode": "ruled_grid_ocr_fallback",
        "table_semantic_hint": bool(table_semantic_hint),
    }
    if not table_semantic_hint:
        diagnostics["reason"] = "ruled_grid_table_semantic_hint_missing"
        return None, diagnostics
    try:
        from PIL import Image

        with Image.open(io.BytesIO(crop_bytes)) as loaded:
            image = loaded.convert("L")
            width, height = image.size
            if (
                width < 32
                or height < 32
                or width > RULED_GRID_MAX_DIMENSION
                or height > RULED_GRID_MAX_DIMENSION
                or width * height > RULED_GRID_MAX_PIXELS
            ):
                diagnostics["reason"] = "ruled_grid_dimensions_out_of_bounds"
                return None, diagnostics
            row_counts, row_runs, col_counts, col_runs = _ruled_grid_dark_metrics(image)
            horizontal = _ruled_grid_line_positions(row_counts, row_runs, orthogonal_size=width)
            vertical = _ruled_grid_line_positions(col_counts, col_runs, orthogonal_size=height)
            diagnostics.update({"horizontal_line_count": len(horizontal), "vertical_line_count": len(vertical)})
            grid_span_width = vertical[-1] - vertical[0] if vertical else 0
            grid_span_height = horizontal[-1] - horizontal[0] if horizontal else 0
            diagnostics.update(
                {
                    "grid_span_width": grid_span_width,
                    "grid_span_height": grid_span_height,
                }
            )
            if (
                len(horizontal) < 3
                or len(vertical) < 3
                or len(horizontal) > RULED_GRID_MAX_LINES
                or len(vertical) > RULED_GRID_MAX_LINES
                or grid_span_width < max(24, int(width * 0.15))
                or grid_span_height < max(24, int(height * 0.15))
            ):
                diagnostics["reason"] = "ruled_grid_geometry_not_strong"
                return None, diagnostics

            intersection_matrix = [
                [
                    _ruled_grid_intersection_support(image, x, y)
                    >= RULED_GRID_INTERSECTION_MIN_RATIO
                    for x in vertical
                ]
                for y in horizontal
            ]
            outer_intersections = sum(
                intersection_matrix[row][col]
                for row, col in ((0, 0), (0, len(vertical) - 1),
                                 (len(horizontal) - 1, 0),
                                 (len(horizontal) - 1, len(vertical) - 1))
            )
            outer_supports = [
                _ruled_grid_intersection_support(image, x, y)
                for x, y in (
                    (vertical[0], horizontal[0]),
                    (vertical[-1], horizontal[0]),
                    (vertical[0], horizontal[-1]),
                    (vertical[-1], horizontal[-1]),
                )
            ]
            diagnostics["outer_intersection_support"] = outer_supports
            horizontal_with_intersection = [
                any(row_values) for row_values in intersection_matrix
            ]
            vertical_with_intersection = [
                any(intersection_matrix[row][col] for row in range(len(horizontal)))
                for col in range(len(vertical))
            ]
            if (
                outer_intersections < 3
                or sum(support >= RULED_GRID_INTERSECTION_MIN_RATIO for support in outer_supports) < 3
                or not all(horizontal_with_intersection)
                or not all(vertical_with_intersection)
            ):
                diagnostics["reason"] = "ruled_grid_intersections_not_strong"
                return None, diagnostics

            rows = len(horizontal) - 1
            cols = len(vertical) - 1
            if rows < 2 or cols < 2 or rows > TABLE_RECOVERY_MAX_ROWS or cols > TABLE_RECOVERY_MAX_COLS:
                diagnostics["reason"] = "ruled_grid_dimensions_not_supported"
                return None, diagnostics
            # A crop-local response is always normalized to page 1.  Keeping
            # this explicit avoids same-coordinate OCR from another source
            # page contaminating the recovered grid.
            records = _ruled_grid_ocr_records(response, image, expected_page_no=1)
            inside_records = [
                record
                for record in records
                if vertical[0] <= record["cx"] <= vertical[-1]
                and horizontal[0] <= record["cy"] <= horizontal[-1]
            ]
            if len(inside_records) < 4:
                diagnostics["reason"] = "ruled_grid_ocr_text_insufficient"
                return None, diagnostics

            total_cells = rows * cols
            if total_cells > TABLE_RECOVERY_MAX_CELLS:
                diagnostics["reason"] = "ruled_grid_cell_limit_exceeded"
                return None, diagnostics
            parent = list(range(total_cells))
            def cell_index(row: int, col: int) -> int:
                return row * cols + col

            def centered_text_in_rect(left: float, top: float, right: float, bottom: float) -> bool:
                for record in inside_records:
                    if not (left <= record["cx"] <= right and top <= record["cy"] <= bottom):
                        continue
                    x_ratio = (record["cx"] - left) / max(right - left, 1.0)
                    y_ratio = (record["cy"] - top) / max(bottom - top, 1.0)
                    if 0.2 <= x_ratio <= 0.8 and 0.2 <= y_ratio <= 0.8:
                        return True
                return False

            # Missing internal lines are treated as merges only when OCR places
            # text centrally in the combined rectangle.  Blank regions remain
            # explicit empty cells instead of being guessed as spans.
            for row in range(rows):
                for col in range(cols - 1):
                    support = _ruled_grid_segment_support(
                        image,
                        orientation="vertical",
                        coordinate=vertical[col + 1],
                        start=horizontal[row] + 2,
                        end=horizontal[row + 1] - 2,
                    )
                    if support < 0.35 and centered_text_in_rect(
                        vertical[col], horizontal[row], vertical[col + 2], horizontal[row + 1]
                    ):
                        _ruled_grid_union(parent, cell_index(row, col), cell_index(row, col + 1))
            for row in range(rows - 1):
                for col in range(cols):
                    support = _ruled_grid_segment_support(
                        image,
                        orientation="horizontal",
                        coordinate=horizontal[row + 1],
                        start=vertical[col] + 2,
                        end=vertical[col + 1] - 2,
                    )
                    if support < 0.35 and centered_text_in_rect(
                        vertical[col], horizontal[row], vertical[col + 1], horizontal[row + 2]
                    ):
                        _ruled_grid_union(parent, cell_index(row, col), cell_index(row + 1, col))

            components: dict[int, list[tuple[int, int]]] = {}
            for row in range(rows):
                for col in range(cols):
                    components.setdefault(_ruled_grid_find(parent, cell_index(row, col)), []).append((row, col))
            component_bounds: list[dict[str, Any]] = []
            for coordinates in components.values():
                min_row = min(row for row, _ in coordinates)
                max_row = max(row for row, _ in coordinates)
                min_col = min(col for _, col in coordinates)
                max_col = max(col for _, col in coordinates)
                if len(coordinates) != (max_row - min_row + 1) * (max_col - min_col + 1):
                    diagnostics["reason"] = "ruled_grid_non_rectangular_component"
                    return None, diagnostics
                component_bounds.append(
                    {
                        "rows": set(range(min_row, max_row + 1)),
                        "cols": set(range(min_col, max_col + 1)),
                        "min_row": min_row,
                        "max_row": max_row,
                        "min_col": min_col,
                        "max_col": max_col,
                        "text": [],
                    }
                )
            merged_component_count = sum(
                len(component["rows"]) > 1 or len(component["cols"]) > 1
                for component in component_bounds
            )
            for record in inside_records:
                component = next(
                    (
                        item
                        for item in component_bounds
                        if vertical[item["min_col"]] <= record["cx"] <= vertical[item["max_col"] + 1]
                        and horizontal[item["min_row"]] <= record["cy"] <= horizontal[item["max_row"] + 1]
                    ),
                    None,
                )
                if component is not None:
                    component["text"].append(record)
            # A fully labelled 2x2 ruled box is indistinguishable from a tiny
            # chart/legend (four labels and no table-specific structure).  The
            # fallback is intentionally conservative: dense semantic tables
            # are accepted by the structured path, while visual-only retries
            # require more than four independent components before we infer a
            # table from pixels and OCR alone.
            if len(component_bounds) <= 4:
                diagnostics.update(
                    {
                        "reason": "ruled_grid_semantics_insufficient",
                        "nonempty_components": sum(
                            bool(item["text"]) for item in component_bounds
                        ),
                        "component_count": len(component_bounds),
                    }
                )
                return None, diagnostics
            dash_marker_count = 0
            for component in component_bounds:
                if component["text"] or len(component["rows"]) != 1 or len(component["cols"]) != 1:
                    continue
                row = component["min_row"]
                col = component["min_col"]
                if _ruled_grid_dash_marker(
                    image,
                    left=vertical[col],
                    top=horizontal[row],
                    right=vertical[col + 1],
                    bottom=horizontal[row + 1],
                ):
                    component["text"].append({"text": "-", "cx": 0.0, "cy": 0.0})
                    dash_marker_count += 1
            nonempty_components = sum(bool(item["text"]) for item in component_bounds)
            nonempty_rows = {
                item["min_row"]
                for item in component_bounds
                if item["text"]
            }
            nonempty_cols = {
                item["min_col"]
                for item in component_bounds
                if item["text"]
            }
            component_coverage = nonempty_components / max(len(component_bounds), 1)
            plain_grid = merged_component_count == 0
            minimum_nonempty_components = (
                max(6, int(math.ceil(len(component_bounds) * 0.8)))
                if plain_grid
                else max(4, int(math.ceil(len(component_bounds) * 0.5)))
            )
            if (
                len(inside_records) < 4
                or (plain_grid and len(inside_records) < 6)
                or (plain_grid and len(component_bounds) < 6)
                or nonempty_components < minimum_nonempty_components
                or len(nonempty_rows) < (rows if plain_grid else 2)
                or len(nonempty_cols) < (cols if plain_grid else 2)
            ):
                diagnostics.update(
                    {
                        "reason": (
                            "ruled_grid_nested_semantics_required"
                            if plain_grid and not table_semantic_hint
                            else "ruled_grid_cell_coverage_insufficient"
                        ),
                        "nonempty_components": nonempty_components,
                        "component_count": len(component_bounds),
                        "component_coverage": round(component_coverage, 3),
                        "merged_component_count": merged_component_count,
                    }
                )
                return None, diagnostics
            if plain_grid and not table_semantic_hint:
                diagnostics.update(
                    {
                        "reason": "ruled_grid_nested_semantics_required",
                        "merged_component_count": merged_component_count,
                    }
                )
                return None, diagnostics
            table_cells: list[dict[str, Any]] = []
            for component in sorted(component_bounds, key=lambda item: (item["min_row"], item["min_col"])):
                texts = sorted(component["text"], key=lambda item: (item["cy"], item["cx"]))
                table_cells.append(
                    {
                        "start_row_offset_idx": component["min_row"],
                        "end_row_offset_idx": component["max_row"] + 1,
                        "start_col_offset_idx": component["min_col"],
                        "end_col_offset_idx": component["max_col"] + 1,
                        "text": " ".join(item["text"] for item in texts),
                    }
                )
            diagnostics.update(
                {
                    "accepted": True,
                    "rows": rows,
                    "cols": cols,
                    "cell_count": len(table_cells),
                    "ocr_nonempty_count": len(inside_records),
                    "dash_marker_count": dash_marker_count,
                    "nonempty_components": nonempty_components,
                    "component_count": len(component_bounds),
                    "component_coverage": round(component_coverage, 3),
                    "merged_component_count": merged_component_count,
                    "rectangular_components": True,
                    "confidence": "high",
                    "validation_mode": "validated_ruled_grid_ocr",
                }
            )
            return {"num_rows": rows, "num_cols": cols, "table_cells": table_cells}, diagnostics
    except Exception as exc:
        diagnostics.update({"reason": "ruled_grid_decode_failed", "error": f"{type(exc).__name__}:{exc}"})
        return None, diagnostics


def _table_recovery_raw_limits(table: dict[str, Any]) -> str | None:
    """Validate untrusted dimensions/offsets before any grid allocation."""

    data = table.get("data") if isinstance(table, dict) else None
    if not isinstance(data, dict):
        return "table_data_missing"
    cells = data.get("table_cells")
    if not isinstance(cells, list):
        return "table_cells_missing"
    raw_rows = data.get("num_rows")
    raw_cols = data.get("num_cols")
    if isinstance(raw_rows, bool) or isinstance(raw_cols, bool):
        return "table_grid_dimensions_invalid"
    try:
        rows = int(raw_rows or 0)
        cols = int(raw_cols or 0)
    except (TypeError, ValueError):
        return "table_grid_dimensions_invalid"
    if rows < 0 or cols < 0:
        return "table_grid_dimensions_invalid"
    if rows > TABLE_RECOVERY_MAX_ROWS or cols > TABLE_RECOVERY_MAX_COLS:
        return "table_grid_limits_exceeded"
    if len(cells) > TABLE_RECOVERY_MAX_CELLS:
        return "table_grid_limits_exceeded"
    offset_keys = (
        "start_row_offset_idx",
        "end_row_offset_idx",
        "start_col_offset_idx",
        "end_col_offset_idx",
    )
    for cell in cells:
        if not isinstance(cell, dict):
            return "table_cell_invalid"
        present = [key in cell for key in offset_keys]
        if not any(present):
            # Legacy/minimal payloads may omit all offsets; table_grid() will
            # place those cells deterministically into declared slots.
            continue
        if not all(present):
            return "table_cell_offsets_invalid"
        values = [cell[key] for key in offset_keys]
        if any(isinstance(value, bool) or not isinstance(value, int) for value in values):
            return "table_cell_offsets_invalid"
        start_row, end_row, start_col, end_col = values
        if (
            start_row < 0
            or start_col < 0
            or end_row <= start_row
            or end_col <= start_col
            or end_row > rows
            or end_col > cols
        ):
            return "table_cell_offsets_out_of_bounds"
    return None


def _table_recovery_candidate_needs_retry(table: dict[str, Any]) -> bool:
    """Identify only image-only/empty tables for a retry.

    A bounded but sparse table can still be a legitimate semantic result (for
    example a one-cell ``Total = 12`` table).  Retrying those tables and then
    marking the whole conversion degraded would discard valid semantics.  The
    retry path is therefore reserved for nodes with no non-empty cell text;
    raw dimensions are checked only after that semantic guard so even hostile
    dimensions on a valid table are never sent back to the service.
    """

    data = table.get("data") if isinstance(table, dict) else None
    cells = data.get("table_cells") if isinstance(data, dict) else None
    if not isinstance(cells, list) or not cells:
        return True
    if any(
        isinstance(cell, dict)
        and isinstance(cell.get("text"), str)
        and cell.get("text", "").strip()
        for cell in cells
    ):
        return False
    # Every cell is empty (or malformed) -- this is the explicit image-only
    # recovery case, including a declared 1x1/2x2 grid with no text.
    return True


_TABLE_SEMANTIC_HINT_RE = re.compile(
    r"(?i)(?<![A-Za-z])table(?![A-Za-z])|"
    r"(?:^|[\s:：。．,，;；(\[【])表(?:\s*(?:\d+|[A-Za-z]?\d+)|格)"
)


def _table_has_semantic_hint(table: dict[str, Any], document_json: Any) -> bool:
    """Require explicit nearby table wording before OCR grid inference."""

    table_prov = first_prov(table) or {}
    table_bbox = table_prov.get("bbox") if isinstance(table_prov, dict) else None
    try:
        table_page = int(table_prov.get("page_no") or 0)
        table_left = float(table_bbox["l"])
        table_right = float(table_bbox["r"])
        table_top = float(table_bbox["t"])
        table_bottom = float(table_bbox["b"])
    except (KeyError, TypeError, ValueError):
        table_page = 0
        table_left = table_right = table_top = table_bottom = 0.0
    valid_table_geometry = not (
        table_page <= 0
        or not all(math.isfinite(value) for value in (
            table_left, table_right, table_top, table_bottom
        ))
        or table_right <= table_left
        or table_bottom == table_top
    )

    def has_hint(value: Any) -> bool:
        return bool(_TABLE_SEMANTIC_HINT_RE.search(str(value or "")))

    # Captions are the strongest source-side signal.  Resolve both direct
    # strings and Docling ``$ref`` caption nodes without trusting label names.
    caption_refs = table.get("captions") if isinstance(table, dict) else None
    for caption in caption_refs or []:
        if isinstance(caption, str) and has_hint(caption):
            return True
        if isinstance(caption, dict):
            if has_hint(caption.get("text")):
                return True
            ref = str(caption.get("$ref") or "")
            if ref:
                for node in iter_nodes(document_json):
                    if isinstance(node, dict) and str(node.get("self_ref") or "") == ref:
                        if has_hint(node.get("text")):
                            return True

    # Fall back to a same-page, nearby text/caption node.  The horizontal
    # relation prevents an unrelated column heading from authorizing a crop.
    if not valid_table_geometry or not isinstance(table_bbox, dict):
        return False
    for node in iter_nodes(document_json):
        if not isinstance(node, dict) or str(node.get("label") or "").lower() == "table":
            continue
        text = node.get("text")
        if not has_hint(text):
            continue
        for prov in node.get("prov") or []:
            if not isinstance(prov, dict):
                continue
            try:
                if int(prov.get("page_no") or 0) != table_page:
                    continue
            except (TypeError, ValueError):
                continue
            bbox = prov.get("bbox")
            if not isinstance(bbox, dict):
                continue
            try:
                left = float(bbox["l"])
                right = float(bbox["r"])
                top = float(bbox["t"])
                bottom = float(bbox["b"])
            except (KeyError, TypeError, ValueError):
                continue
            if not all(math.isfinite(value) for value in (left, right, top, bottom)):
                continue
            vertical_gap = max(
                0.0,
                min(table_top, table_bottom) - max(top, bottom),
                min(top, bottom) - max(table_top, table_bottom),
            )
            horizontal_overlap = min(table_right, right) - max(table_left, left)
            caption_center = (left + right) / 2.0
            center_in_table = table_left <= caption_center <= table_right
            if vertical_gap <= 48.0 and (horizontal_overlap > 0.0 or center_in_table):
                return True
    return False


def _recovered_table_data_from_response(
    response: dict[str, Any],
    *,
    crop_bytes: bytes | None = None,
    table_semantic_hint: bool = False,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    """Accept one dense, two-dimensional table from a crop retry."""

    document = response.get("document") if isinstance(response, dict) else None
    candidates = extract_table_nodes(
        document.get("json_content") if isinstance(document, dict) else None
    )
    diagnostics: dict[str, Any] = {
        "response_status": response.get("status") if isinstance(response, dict) else None,
        "candidate_count": len(candidates),
        "accepted": False,
        "reason": None,
    }
    if not isinstance(response, dict) or response.get("status") not in {"success", "partial_success"}:
        diagnostics["reason"] = "response_not_success"
        return None, diagnostics
    if len(candidates) == 0 and crop_bytes:
        ruled_data, ruled_diagnostics = _ruled_grid_ocr_fallback(
            response,
            crop_bytes,
            table_semantic_hint=table_semantic_hint,
        )
        diagnostics.update(ruled_diagnostics)
        if ruled_data is not None:
            diagnostics.update(
                {
                    "accepted": True,
                    "confidence": "high",
                    "validation_mode": "validated_ruled_grid_ocr",
                }
            )
            return ruled_data, diagnostics
        # Preserve the conservative ruled-grid rejection reason for callers and
        # diagnostics; do not hide it behind the generic non-unique candidate
        # message when the retry returned OCR but no semantic table.
        return None, diagnostics
    if len(candidates) != 1:
        diagnostics["reason"] = "table_candidate_not_unique"
        return None, diagnostics
    candidate = candidates[0]
    raw_limit_reason = _table_recovery_raw_limits(candidate)
    if raw_limit_reason is not None:
        diagnostics["reason"] = raw_limit_reason
        return None, diagnostics
    confidence = str(candidate.get("confidence") or "").strip().lower()
    if confidence in {"low", "medium"}:
        structured_reason = "table_confidence_not_high"
        diagnostics.update(
            {"structured_rejection_reason": structured_reason, "confidence": confidence}
        )
        if crop_bytes:
            ruled_data, ruled_diagnostics = _ruled_grid_ocr_fallback(
                response,
                crop_bytes,
                table_semantic_hint=table_semantic_hint,
            )
            diagnostics.update(ruled_diagnostics)
            if ruled_data is not None:
                diagnostics.update(
                    {
                        "accepted": True,
                        "confidence": "high",
                        "validation_mode": "validated_ruled_grid_ocr",
                    }
                )
                return ruled_data, diagnostics
            return None, diagnostics
        diagnostics["reason"] = structured_reason
        return None, diagnostics
    data = candidate.get("data")
    grid = table_grid(candidate)
    rows = len(grid)
    cols = max((len(row) for row in grid), default=0)
    nonempty = sum(bool(str(cell).strip()) for row in grid for cell in row)
    total = rows * cols
    cells = [cell for cell in (data or {}).get("table_cells", []) if isinstance(cell, dict)]
    fill = nonempty / total if total else 0.0
    diagnostics.update({"rows": rows, "cols": cols, "cell_count": len(cells), "fill_ratio": round(fill, 3)})
    if (
        rows < 2
        or cols < 2
        or rows > TABLE_RECOVERY_MAX_ROWS
        or cols > TABLE_RECOVERY_MAX_COLS
        or len(cells) > TABLE_RECOVERY_MAX_CELLS
        or total < 4
        or len(cells) < 4
        or fill < 0.6
    ):
        structured_reason = "table_grid_not_dense_enough"
        diagnostics["structured_rejection_reason"] = structured_reason
        if crop_bytes:
            ruled_data, ruled_diagnostics = _ruled_grid_ocr_fallback(
                response,
                crop_bytes,
                table_semantic_hint=table_semantic_hint,
            )
            diagnostics.update(ruled_diagnostics)
            if ruled_data is not None:
                diagnostics.update(
                    {
                        "accepted": True,
                        "confidence": "high",
                        "validation_mode": "validated_ruled_grid_ocr",
                    }
                )
                return ruled_data, diagnostics
            return None, diagnostics
        diagnostics["reason"] = structured_reason
        return None, diagnostics
    if not isinstance(data, dict) or not isinstance(data.get("table_cells"), list):
        diagnostics["reason"] = "table_data_missing_cells"
        return None, diagnostics
    sanitized_data = copy.deepcopy(data)
    for cell in sanitized_data.get("table_cells") or []:
        if isinstance(cell, dict):
            # Retry coordinates are local to the PNG crop, not the submitted
            # PDF page.  Keeping them would falsely claim PDF provenance.
            cell.pop("bbox", None)
    diagnostics.update(
        {
            "accepted": True,
            "confidence": "high",
            "validation_mode": "validated_dense_table",
        }
    )
    return sanitized_data, diagnostics


def recover_image_only_tables_from_serve(
    response: dict[str, Any],
    input_file: Path,
    args: argparse.Namespace,
    metadata: dict[str, Any],
    status: dict[str, Any],
) -> dict[str, Any]:
    """Recover empty image tables locally, then optionally retry via Serve.

    The local path uses only source-page OCR already present in the conversion
    response plus bounded crop pixels.  A remote retry is attempted only for a
    trusted loopback endpoint; derived crops are never sent elsewhere.
    Failures leave the original 0x0 table for the explicit visual-only fallback.
    """

    endpoint_parse_error: str | None = None
    try:
        endpoint = urllib.parse.urlparse(str(getattr(args, "serve_url", "")))
        trusted_host = endpoint.hostname in {"127.0.0.1", "localhost", "::1"}
        trusted_endpoint = bool(
            endpoint.scheme in {"http", "https"}
            and trusted_host
            and not endpoint.username
            and not endpoint.password
        )
    except ValueError as exc:
        # urlparse raises on malformed bracketed hosts.  Treat that exactly as
        # any other untrusted endpoint: record a rejection and never issue a
        # crop upload request.
        endpoint = None
        endpoint_parse_error = f"{type(exc).__name__}:{exc}"
        trusted_endpoint = False
    document = response.get("document") if isinstance(response, dict) else None
    document_json = document.get("json_content") if isinstance(document, dict) else None
    tables = extract_table_nodes(document_json)
    pictures = extract_label_nodes(document_json, "picture")
    # Check raw dimensions before table_grid() so hostile payloads cannot force
    # a giant allocation during candidate discovery.  Sparse but bounded grids
    # are still sent through the guarded retry path.
    candidates = [table for table in tables if _table_recovery_candidate_needs_retry(table)]
    diagnostics: dict[str, Any] = {
        "attempted_count": 0,
        "accepted_count": 0,
        "accepted_source_refs": [],
        "rejected": [],
        "limits": {
            "max_crops": TABLE_RECOVERY_MAX_CROPS,
            "max_crop_bytes": TABLE_RECOVERY_MAX_CROP_BYTES,
            "timeout_seconds": TABLE_RECOVERY_TIMEOUT_SECONDS,
        },
        "endpoint_trusted": trusted_endpoint,
    }
    if endpoint_parse_error:
        diagnostics["endpoint_parse_error"] = endpoint_parse_error
    for table_index, table in enumerate(candidates[:TABLE_RECOVERY_MAX_CROPS], start=1):
        source_ref = _structural_node_source_ref(
            table,
            kind="table",
            fallback_index=table_index - 1,
            part_index=_structural_node_part_index(table),
        )
        record: dict[str, Any] = {"source_ref": source_ref, "table_index": table_index}
        table_semantic_hint = _table_has_semantic_hint(table, document_json)
        record["table_semantic_hint"] = table_semantic_hint
        raw_limit_reason = _table_recovery_raw_limits(table)
        if raw_limit_reason is not None:
            record["reason"] = raw_limit_reason
            diagnostics["rejected"].append(record)
            continue
        rendered = _render_table_recovery_crop_png_with_geometry(
            input_file,
            table,
            tables,
            pictures,
        )
        geometry = rendered[1] if isinstance(rendered, tuple) else None
        crop_bytes = rendered[0] if isinstance(rendered, tuple) else None
        # Preserve injected/test renderers and legacy environments where only
        # the bytes-only helper is available.
        if crop_bytes is None:
            crop_bytes = _render_table_recovery_crop_png(
                input_file,
                table,
                tables,
                pictures,
            )
        diagnostics["attempted_count"] += 1
        if not crop_bytes:
            # A failed local render is still a failed recovery attempt.  When
            # the configured endpoint is untrusted, retain that trust-boundary
            # outcome as the public reason (while preserving the concrete
            # render failure for diagnostics); do not ever send an absent crop.
            if not trusted_endpoint:
                record["reason"] = "image_table_recovery_remote_endpoint_disallowed"
                record["render_failure_reason"] = "table_crop_render_failed"
                if endpoint_parse_error:
                    record["endpoint_parse_error"] = endpoint_parse_error
            else:
                record["reason"] = "table_crop_render_failed"
            diagnostics["rejected"].append(record)
            continue
        record["crop_bytes"] = len(crop_bytes)
        if len(crop_bytes) > TABLE_RECOVERY_MAX_CROP_BYTES:
            record["reason"] = "table_crop_bytes_exceeded_limit"
            diagnostics["rejected"].append(record)
            continue
        if geometry is not None:
            record["crop_geometry"] = copy.deepcopy(geometry)
            overlap_reason = _table_recovery_non_target_overlap_reason(
                table,
                tables,
                geometry,
            )
            if overlap_reason is not None:
                record["reason"] = overlap_reason
                record["local_recovery"] = {
                    "accepted": False,
                    "reason": overlap_reason,
                }
                diagnostics["rejected"].append(record)
                continue
            try:
                from PIL import Image

                with Image.open(io.BytesIO(crop_bytes)) as crop_image:
                    crop_size = (crop_image.width, crop_image.height)
                local_response = _map_table_response_ocr_to_crop(
                    response,
                    geometry,
                    crop_size,
                )
            except Exception:
                local_response = None
            if local_response is not None:
                # The source response can contain the empty table being
                # recovered plus unrelated semantic tables.  Calling the
                # general verifier would treat those nodes as retry
                # candidates and reject the local path as non-unique.  The
                # local-first path intentionally consumes only mapped OCR and
                # crop pixels; structured retry responses are handled below.
                local_data, local_diagnostics = _ruled_grid_ocr_fallback(
                    local_response,
                    crop_bytes,
                    table_semantic_hint=table_semantic_hint,
                )
                record["local_recovery"] = local_diagnostics
                if local_data is not None:
                    record.update(local_diagnostics)
                    record["recovery_origin"] = "local_crop"
                    table["data"] = local_data
                    table.setdefault("local_ai_lab_qc", {})[
                        "image_table_semantic_recovery"
                    ] = record
                    diagnostics["accepted_count"] += 1
                    diagnostics["accepted_source_refs"].append(source_ref)
                    continue
        if not trusted_endpoint:
            record["reason"] = "image_table_recovery_remote_endpoint_disallowed"
            diagnostics["rejected"].append(record)
            continue
        payload = {
            "sources": [{
                "kind": "file",
                "filename": f"table-recovery-{table_index}.png",
                "base64_string": base64.b64encode(crop_bytes).decode("ascii"),
            }],
            "target": {"kind": "inbody"},
            "options": {
                "from_formats": ["image"],
                "to_formats": ["json"],
                "do_ocr": True,
                "force_ocr": True,
                "ocr_preset": "auto",
                "do_table_structure": True,
                "table_mode": "accurate",
                "table_cell_matching": True,
                "include_images": False,
                "document_timeout": TABLE_RECOVERY_TIMEOUT_SECONDS,
            },
        }
        try:
            retry_response = post_json(
                f"{args.serve_url.rstrip('/')}/v1/convert/source",
                payload,
                timeout=min(
                    int(getattr(args, "timeout_seconds", TABLE_RECOVERY_TIMEOUT_SECONDS)),
                    TABLE_RECOVERY_TIMEOUT_SECONDS,
                ),
                retries=0,
                retry_sleep_seconds=0.0,
            )
        except Exception as exc:
            record.update({"reason": "table_recovery_request_failed", "error": f"{type(exc).__name__}:{exc}"})
            diagnostics["rejected"].append(record)
            continue
        recovered_data, retry_diagnostics = _recovered_table_data_from_response(
            retry_response,
            crop_bytes=crop_bytes,
            table_semantic_hint=table_semantic_hint,
        )
        record.update(retry_diagnostics)
        if recovered_data is None:
            diagnostics["rejected"].append(record)
            continue
        table["data"] = recovered_data
        table.setdefault("local_ai_lab_qc", {})["image_table_semantic_recovery"] = record
        diagnostics["accepted_count"] += 1
        diagnostics["accepted_source_refs"].append(source_ref)
    if len(candidates) > TABLE_RECOVERY_MAX_CROPS:
        diagnostics["rejected"].append(
            {
                "reason": "table_recovery_max_crops_exceeded",
                "count": len(candidates) - TABLE_RECOVERY_MAX_CROPS,
            }
        )
    if diagnostics["rejected"]:
        status["ok"] = False
        status["success_class"] = "degraded_failure"
        for item in diagnostics["rejected"]:
            reason = str(item.get("reason") or "unknown")
            ref = str(item.get("source_ref") or "")
            # The aggregate remote-endpoint record is explanatory metadata;
            # emit one warning per affected source ref below, not an extra
            # ``unknown`` warning that hides the actual table identities.
            if not ref and reason == "image_table_recovery_remote_endpoint_disallowed":
                continue
            warning = (
                f"image_table_semantic_recovery_unavailable:{ref}:{reason}"
                if ref
                else f"image_table_semantic_recovery_unavailable:{reason}"
            )
            if warning not in status.setdefault("warnings", []):
                status["warnings"].append(warning)
    metadata["image_table_semantic_recovery"] = diagnostics
    status.setdefault("quality_signals", {})["image_table_semantic_recovery"] = diagnostics
    return diagnostics


def inject_empty_table_visual_fallbacks(
    output_dir: Path,
    document_json: Any,
    tables: list[dict[str, Any]],
    *,
    provenance_manifest: dict[str, Any] | None = None,
    expected_visual_pdf_sha256: str | None = None,
    expected_semantic_pdf_sha256: str | None = None,
) -> dict[str, Any]:
    nodes_by_ref = _structural_nodes_by_part_ref(document_json)
    page_inventory = _document_page_size_inventory(document_json)
    candidates: list[dict[str, Any]] = []
    provenance_verified_refs: list[str] = []
    provenance_mismatch_refs: list[str] = []
    provenance_diagnostics: dict[str, list[str]] = {}
    for index, table in enumerate(tables, start=1):
        table_part_index = _structural_node_part_index(table)
        data = table.get("data") or {}
        if data.get("table_cells") or data.get("num_rows") or data.get("num_cols"):
            continue
        image_path = output_dir / "tables" / f"table_{index}.png"
        if not image_path.exists():
            continue
        caption_texts = []
        for caption in table.get("captions") or []:
            reference = str(caption.get("$ref") or "")
            node = nodes_by_ref.get((table_part_index, reference))
            text = str((node or {}).get("text") or "").strip()
            if text:
                caption_texts.append(text)
        source_ref = _structural_node_source_ref(
            table,
            kind="table",
            fallback_index=index - 1,
            part_index=table_part_index,
        )
        page_no = _positive_page_number((first_prov(table) or {}).get("page_no"))
        page_size = (
            (
                (page_inventory.get("page_records") or {}).get(page_no)
                or {}
            ).get("size")
            or None
        )
        manifest_entry, lookup_reasons = _structural_manifest_entry_for_ref(
            provenance_manifest,
            kind="tables",
            source_ref=source_ref,
            index=index,
        )
        verified, verify_reasons = _structural_provenance_verify(
            output_dir,
            manifest_entry,
            current_source_ref=source_ref,
            current_page_no=page_no,
            current_bbox=(first_prov(table) or {}).get("bbox"),
            current_body_identity=_table_grid_body_identity([]),
            current_self_ref=str(table.get("self_ref") or ""),
            current_part_index=table_part_index,
            current_semantic_page_size=page_size,
            expected_visual_pdf_sha256=expected_visual_pdf_sha256,
            expected_semantic_pdf_sha256=expected_semantic_pdf_sha256,
            expected_asset_path=f"tables/table_{index}.png",
            expected_kind="table",
        )
        reasons = sorted(set(lookup_reasons + verify_reasons))
        if verified and not lookup_reasons:
            provenance_verified_refs.append(source_ref)
        else:
            provenance_mismatch_refs.append(source_ref)
            provenance_diagnostics[source_ref] = reasons
        candidates.append(
            {
                "table_index": index,
                "image": f"tables/table_{index}.png",
                "caption": " ".join(caption_texts) or f"Table {index}",
                "page_no": page_no,
                "source_ref": source_ref,
                "provenance_verified": verified and not lookup_reasons,
                "provenance_reasons": reasons,
                "reason": "empty_structural_grid_with_source_bbox_and_caption",
            }
        )
        table.setdefault("local_ai_lab_qc", {})["visual_fallback"] = candidates[-1]

    html_count = 0
    html_path = output_dir / "document.html"
    if candidates and html_path.exists():
        document_html = html_path.read_text(encoding="utf-8")

        def fallback_figure(candidate: dict[str, Any], *, exact: bool = True) -> str:
            suffix = " — exact source rendering from the original PDF" if exact else ""
            return (
                '<figure class="docling-table-visual-fallback docling-source-visual-only" '
                f'data-source-ref="{html.escape(str(candidate["source_ref"]), quote=True)}">'
                '<div class="docling-visual-only-label">Visual-only source crop; '
                "semantic table recovery unavailable</div>"
                f'<img src="{candidate["image"]}" '
                f'alt="{html.escape(candidate["caption"], quote=True)}">'
                f'<figcaption>{html.escape(candidate["caption"])}{suffix}</figcaption>'
                "</figure>"
            )

        for candidate in reversed(candidates):
            target = _normalized_noise_text(candidate["caption"])
            applied = False
            matching_figures = []
            for figure in re.finditer(
                r'<figure\b[^>]*class="[^"]*\bsemantic-table\b[^"]*"[^>]*>'
                r"(?P<body>.*?)</figure>",
                document_html,
                flags=re.I | re.S,
            ):
                table_match = re.search(
                    r"<table\b(?P<attrs>[^>]*)>(?P<body>.*?)</table>",
                    figure.group("body"),
                    flags=re.I | re.S,
                )
                if (
                    table_match
                    and _html_source_ref(table_match.group("attrs"))
                    == str(candidate["source_ref"])
                    and not re.search(r"<(?:td|th)\b", table_match.group("body"), re.I)
                ):
                    matching_figures.append(figure)
            if len(matching_figures) == 1:
                figure = matching_figures[0]
                document_html = (
                    document_html[: figure.start()]
                    + fallback_figure(candidate)
                    + document_html[figure.end() :]
                )
                html_count += 1
                applied = True
            if applied:
                continue
            for match in re.finditer(
                r"<table\b[^>]*>(?P<body>.*?)</table>",
                document_html,
                flags=re.I | re.S,
            ):
                body = match.group("body")
                visible = _normalized_noise_text(
                    html.unescape(HTML_TAG_RE.sub(" ", body))
                )
                if visible != target:
                    continue
                replacement = fallback_figure(candidate, exact=False)
                document_html = (
                    document_html[: match.start()]
                    + replacement
                    + document_html[match.end() :]
                )
                html_count += 1
                applied = True
                break
            if applied:
                continue
            semantic_figures = list(
                re.finditer(
                    r'<figure\b[^>]*class="[^"]*\bsemantic-table\b[^"]*"[^>]*>'
                    r"(?P<body>.*?)</figure>",
                    document_html,
                    flags=re.I | re.S,
                )
            )
            table_index = int(candidate["table_index"]) - 1
            if not (0 <= table_index < len(semantic_figures)):
                continue
            figure = semantic_figures[table_index]
            figure_body = figure.group("body")
            table_match = re.search(
                r"<table\b[^>]*>(?P<body>.*?)</table>",
                figure_body,
                flags=re.I | re.S,
            )
            if table_match and re.search(r"<(?:td|th)\b", table_match.group("body"), re.I):
                continue
            replacement = fallback_figure(candidate)
            document_html = (
                document_html[: figure.start()]
                + replacement
                + document_html[figure.end() :]
            )
            html_count += 1
        html_path.write_text(document_html, encoding="utf-8")
    final_html = html_path.read_text(encoding="utf-8") if html_path.exists() else ""
    html_bound_refs: list[str] = []
    for candidate in candidates:
        source_ref = str(candidate["source_ref"])
        blocks = [
            match.group("body")
            for match in re.finditer(
                r'<figure\b(?P<attrs>[^>]*)class="[^"]*\bdocling-table-visual-fallback\b[^"]*"'
                r'(?P<tail>[^>]*)>(?P<body>.*?)</figure>',
                final_html,
                flags=re.I | re.S,
            )
            if _html_source_ref(match.group("attrs") + match.group("tail"))
            == source_ref
        ]
        if len(blocks) == 1 and str(candidate["image"]) in blocks[0]:
            html_bound_refs.append(source_ref)

    markdown_count = 0
    md_path = output_dir / "document.md"
    if candidates and md_path.exists():
        document_markdown = md_path.read_text(encoding="utf-8")
        for candidate in candidates:
            source_ref = str(candidate["source_ref"])
            source_marker = f"<!-- source-table-ref:{source_ref} -->"
            fallback_marker = f"<!-- source-empty-table-ref:{source_ref} -->"
            # Remove only the prior fallback evidence, retaining the source
            # marker and semantic Markdown table/caption for a fresh bind.
            cleanup_pattern = re.compile(
                r"<!--\s*source-empty-table-ref:\s*"
                + re.escape(source_ref)
                + r"\s*-->\s*"
                r"\*\*Visual-only source crop; semantic table recovery unavailable\.\*\*\s*"
                r"!\[[^\n]*\]\("
                + re.escape(str(candidate["image"]))
                + r"\)\s*",
                flags=re.I,
            )
            document_markdown, _ = _markdown_sub_outside_code(
                document_markdown,
                cleanup_pattern,
                "",
            )
            source_evidence = (
                source_marker
                + "\n"
                + fallback_marker
                + "\n\n"
                + "**Visual-only source crop; semantic table recovery unavailable.**\n\n"
                + _markdown_image(candidate["caption"], candidate["image"])
            )
            if document_markdown.count(source_marker) == 1:
                document_markdown = document_markdown.replace(
                    source_marker,
                    source_evidence,
                    1,
                )
                markdown_count += 1
                continue
            caption_pattern = re.compile(
                r"(?m)^(?P<caption>"
                + re.escape(candidate["caption"])
                + r")\s*$"
            )
            replacement = (
                fallback_marker
                + "\n\n"
                + "**Visual-only source crop; semantic table recovery unavailable.**\n\n"
                + _markdown_image(candidate["caption"], candidate["image"]) + "\n\n"
                r"\g<caption>"
            )
            document_markdown, changed = caption_pattern.subn(
                replacement,
                document_markdown,
                count=1,
            )
            markdown_count += changed
        md_path.write_text(document_markdown, encoding="utf-8")
    final_markdown = md_path.read_text(encoding="utf-8") if md_path.exists() else ""
    markdown_bound_refs: list[str] = []
    for candidate in candidates:
        source_ref = str(candidate["source_ref"])
        marker = f"<!-- source-empty-table-ref:{source_ref} -->"
        if final_markdown.count(marker) != 1:
            continue
        start = final_markdown.index(marker)
        next_marker = re.search(
            r"<!--\s*source-(?:empty-table|table|code|algorithm)-ref:",
            final_markdown[start + len(marker) :],
            flags=re.I,
        )
        end = (
            start + len(marker) + next_marker.start()
            if next_marker
            else len(final_markdown)
        )
        if str(candidate["image"]) in final_markdown[start:end]:
            markdown_bound_refs.append(source_ref)

    return {
        "candidate_count": len(candidates),
        "html_applied_count": html_count,
        "markdown_applied_count": markdown_count,
        "candidate_source_refs": [str(item["source_ref"]) for item in candidates],
        "html_bound_source_refs": html_bound_refs,
        "markdown_bound_source_refs": markdown_bound_refs,
        "html_unbound_source_refs": sorted(
            set(str(item["source_ref"]) for item in candidates)
            - set(html_bound_refs)
        ),
        "markdown_unbound_source_refs": sorted(
            set(str(item["source_ref"]) for item in candidates)
            - set(markdown_bound_refs)
        ),
        "provenance_verified_refs": sorted(set(provenance_verified_refs)),
        "provenance_mismatch_refs": sorted(set(provenance_mismatch_refs)),
        "provenance_diagnostics": provenance_diagnostics,
        "candidates": candidates,
    }


def _structural_node_source_ref(
    node: dict[str, Any],
    *,
    kind: str,
    fallback_index: int,
    part_index: int | None = None,
) -> str:
    """Return the same stable source identity used by semantic reflow."""

    source_ref = str(node.get("self_ref") or "").strip()
    if source_ref:
        source_ref = (
            source_ref.replace("\r", " ")
            .replace("\n", " ")
            .replace("--", "- -")
        )
    else:
        source_ref = f"{kind}:{fallback_index}"
    if part_index is None:
        candidate_part = node.get("_local_ai_lab_chunk_part_index")
        if isinstance(candidate_part, int) and not isinstance(candidate_part, bool):
            part_index = candidate_part
    return f"chunk:{part_index}:{source_ref}" if part_index is not None else source_ref


def _structural_node_part_index(node: dict[str, Any]) -> int | None:
    value = node.get("_local_ai_lab_chunk_part_index")
    return value if isinstance(value, int) and not isinstance(value, bool) else None


def _structural_nodes_by_part_ref(
    document_json: Any,
) -> dict[tuple[int | None, str], dict[str, Any]]:
    return {
        (_structural_node_part_index(node), str(node.get("self_ref"))): node
        for node in iter_nodes(document_json)
        if isinstance(node, dict) and node.get("self_ref")
    }


_STRUCTURAL_BODY_TOKEN_RE = re.compile(
    r"\\[A-Za-z]+|[A-Za-z_][A-Za-z0-9_]*|\d+(?:\.\d+)*|"
    r"===|!==|==|!=|<=|>=|:=|->|<-|=>|\+\+|--|\*\*|//|&&|\|\||<<|>>|[^\s]"
)


def _structural_visible_body_text(value: str, *, html_markup: bool = False) -> str:
    """Return visible structural body text without discarding operators."""

    visible = value
    if html_markup:
        visible = re.sub(
            r"<(?:script|style|template)\b.*?</(?:script|style|template)>",
            " ",
            visible,
            flags=re.I | re.S,
        )
        # A source table footnote marker is part of the visible cell text.
        # Remove only the hyperlink/superscript presentation wrapper; keeping
        # the marker itself makes ``PDF*`` identical to ``PDF<sup>*</sup>``
        # without weakening ordinary mathematical superscript checks.
        visible = re.sub(
            r"<sup\b(?=[^>]*(?:"
            r"\bclass\s*=\s*[\"'][^\"']*\bfootnote[^\"']*[\"']|"
            r"\bid\s*=\s*[\"'][^\"']*\bfnref-[^\"']*[\"']))[^>]*>",
            "",
            visible,
            flags=re.I | re.S,
        )
        visible = re.sub(r"<sub\b[^>]*>", "_", visible, flags=re.I)
        visible = re.sub(r"</sub\s*>", "", visible, flags=re.I)
        visible = re.sub(r"<sup\b[^>]*>", "^", visible, flags=re.I)
        visible = re.sub(r"</sup\s*>", "", visible, flags=re.I)
        visible = re.sub(r"<br\s*/?>", "\n", visible, flags=re.I)
        visible = re.sub(
            r"</(?:p|pre|li|tr|section|article|h[1-6])\s*>",
            "\n",
            visible,
            flags=re.I,
        )
        visible = re.sub(r"<[^>]+>", "", visible)
    visible = html.unescape(visible)
    visible = visible.translate(
        str.maketrans(
            {
                "\u00a0": " ",
                "−": "-",
                "–": "-",
                "—": "-",
                "（": "(",
                "）": ")",
            }
        )
    )
    return visible.replace("\r\n", "\n").replace("\r", "\n")


def _source_disclosure_html(
    body: str,
    *,
    summary: str,
    extra_class: str = "",
    attrs: str = "",
) -> str:
    """Wrap source evidence in an accessible, closed-by-default disclosure."""

    classes = "docling-source-disclosure"
    if extra_class:
        classes += " " + extra_class
    return (
        f'<details class="{classes}"{attrs}>'
        f"<summary>{html.escape(summary)}</summary>"
        f"{body}</details>"
    )


def _source_disclosure_markdown(
    body: str,
    *,
    summary: str,
    extra_class: str = "",
) -> str:
    classes = "docling-source-disclosure" + (
        f" {extra_class}" if extra_class else ""
    )
    return (
        f'<details class="{classes}"><summary>{html.escape(summary)}</summary>\n\n'
        f"{body}\n\n</details>"
    )


_SAFE_MARKDOWN_IMAGE_PATH_RE = re.compile(
    r"(?:[A-Za-z0-9._-]+/)*[A-Za-z0-9._-]+"
)


def _markdown_image(caption: Any, path: Any) -> str:
    """Render a local image reference without allowing caption/path injection."""

    # Markdown image alt text is bracket-delimited; escape delimiters and
    # collapse line breaks so PDF-derived captions cannot create a new link,
    # heading, or raw block.  Backslashes are escaped first to avoid creating a
    # second escape sequence during rendering.
    safe_caption = " ".join(str(caption or "").replace("\r", "\n").splitlines())
    safe_caption = (
        safe_caption.replace("\\", "\\\\")
        .replace("[", "\\[")
        .replace("]", "\\]")
        .replace("(", "\\(")
        .replace(")", "\\)")
        .replace("`", "\\`")
    )
    safe_path = str(path or "").replace("\\", "/")
    path_parts = safe_path.split("/")
    if (
        not _SAFE_MARKDOWN_IMAGE_PATH_RE.fullmatch(safe_path)
        or any(part in {"", ".", ".."} for part in path_parts)
        or safe_path.startswith("/")
    ):
        # Keep the evidence body renderable while refusing arbitrary URLs or
        # traversal paths supplied by a malformed source record.
        safe_path = "#"
    return f"![{safe_caption}]({safe_path})"


def _strip_source_disclosure_blocks(value: str, *, extra_class: str) -> str:
    """Remove prior evidence wrappers and their bodies before rebinding.

    Source figures are regenerated from the current candidate inventory.  Keeping
    an old wrapper body would leave a raw figure behind when the caller inserts a
    fresh disclosure on a subsequent pass.
    """

    pattern = re.compile(
        r'<details\b[^>]*class\s*=\s*(?P<quote>["\'])'
        r'(?=[^"\']*\bdocling-source-disclosure\b)'
        r'(?=[^"\']*\b' + re.escape(extra_class) + r'\b)'
        r'[^"\']*(?P=quote)[^>]*>'
        r'.*?</details>',
        flags=re.I | re.S,
    )
    return pattern.sub("", value)


def _structural_body_identity(value: str, *, html_markup: bool = False) -> str:
    """Normalize presentation while retaining token order, variables, and operators."""

    visible = _structural_visible_body_text(value, html_markup=html_markup)
    visible = visible.replace(r"\(", "").replace(r"\)", "")
    identities: list[str] = []
    for line in visible.splitlines() or [visible]:
        tokens = _STRUCTURAL_BODY_TOKEN_RE.findall(line)
        if tokens:
            identities.append(" ".join(tokens))
    return "\n".join(identities)


def _code_body_identity(value: str, *, html_markup: bool = False) -> str:
    """Ignore physical code wrapping while retaining every semantic token."""

    return " ".join(
        _structural_body_identity(value, html_markup=html_markup).splitlines()
    )


def _algorithm_body_identity(value: str, *, html_markup: bool = False) -> str:
    """Normalize algorithm line-number presentation and soft wrapping only."""

    visible = _structural_visible_body_text(value, html_markup=html_markup)
    lines = []
    for line in visible.splitlines() or [visible]:
        # HTML line-number spans omit the source colon.  The number and body
        # token sequence remain authoritative, so normalize only that optional
        # delimiter and then ignore physical wrapping within a step.
        lines.append(re.sub(r"^\s*(\d{1,3})\s*:\s*", r"\1 ", line))
    return " ".join(_structural_body_identity("\n".join(lines)).splitlines())


def _table_grid_body_identity(grid: list[list[Any]]) -> str:
    if not grid:
        return ""

    def cell_identity(value: Any) -> str:
        # Soft wrapping and explicit <br> presentation inside a single cell do
        # not alter table identity.  Cell/row boundaries stay encoded by the
        # surrounding JSON grid, while token/operator order remains strict.
        visible = re.sub(r"\s+", " ", str(value or "")).strip()
        # Docling/PDF extraction can insert or remove spacing between a math
        # symbol and its numeric index (``C 2``/``C2``, ``mn 2``/``mn2``).
        # Normalize only letter-digit boundaries; letter-letter and all
        # operators remain strict.
        visible = re.sub(r"(?<=[A-Za-z])\s+(?=\d)", "", visible)
        visible = re.sub(r"(?<=\d)\s+(?=[A-Za-z])", "", visible)
        return _structural_body_identity(
            visible,
            html_markup=bool(re.search(r"</?[A-Za-z][^>]*>", visible)),
        )

    return json.dumps(
        [[cell_identity(cell) for cell in row] for row in grid],
        ensure_ascii=False,
        separators=(",", ":"),
    )


def _structural_body_identity_sha256(kind: str, identity: str) -> str:
    """Hash an already-normalized body without making an empty grid vacuous."""

    return hashlib.sha256(
        (str(kind).casefold() + "\0" + str(identity)).encode("utf-8")
    ).hexdigest()


def _structural_bbox_snapshot(value: Any) -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None
    origin = _bbox_explicit_coord_origin(value)
    if origin is None:
        return None
    try:
        result = {
            key: float(value[key])
            for key in ("l", "r", "t", "b")
        }
    except (KeyError, TypeError, ValueError):
        return None
    if (
        not all(math.isfinite(result[key]) for key in ("l", "r", "t", "b"))
        or result["r"] <= result["l"]
        or result["t"] == result["b"]
    ):
        return None
    result["coord_origin"] = origin
    return result


def _structural_page_size_snapshot(value: Any) -> dict[str, float] | None:
    if not isinstance(value, dict):
        return None
    try:
        width = float(value.get("width") or 0.0)
        height = float(value.get("height") or 0.0)
    except (TypeError, ValueError):
        return None
    if width <= 0.0 or height <= 0.0:
        return None
    return {"width": width, "height": height}


def _structural_geometry_compatibility(
    semantic_page_size: Any,
    visual_page_size: Any,
) -> dict[str, Any]:
    semantic = _structural_page_size_snapshot(semantic_page_size)
    visual = _structural_page_size_snapshot(visual_page_size)
    if semantic is None or visual is None:
        return {
            "compatible": False,
            "reason": "missing_page_size",
            "scale_x": None,
            "scale_y": None,
        }
    scale_x = visual["width"] / semantic["width"]
    scale_y = visual["height"] / semantic["height"]
    relative_delta = abs(scale_x - scale_y) / max(scale_x, scale_y, 1e-12)
    absolute_scale_delta = max(abs(scale_x - 1.0), abs(scale_y - 1.0))
    compatible = relative_delta <= 0.01 and absolute_scale_delta <= 0.005
    return {
        "compatible": compatible,
        "reason": (
            None
            if compatible
            else (
                "page_aspect_ratio_mismatch"
                if relative_delta > 0.01
                else "semantic_visual_page_size_mismatch"
            )
        ),
        "scale_x": scale_x,
        "scale_y": scale_y,
    }


def _structural_visual_provenance_entry(
    *,
    kind: str,
    index: int,
    source_ref: str,
    node: dict[str, Any] | None,
    body_identity: str,
    metric: dict[str, Any] | None,
    node_bbox: Any,
    part_index: int | None,
    semantic_pdf_sha256: str | None,
    conversion_pdf_sha256: str | None,
    semantic_page_size: Any = None,
    crop_coordinate_page_size: Any = None,
    source_node_bindings: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    metric = metric if isinstance(metric, dict) else {}
    visual_page_size = _structural_page_size_snapshot(metric.get("page_size"))
    semantic_page_size = _structural_page_size_snapshot(semantic_page_size)
    page_no = _positive_page_number(metric.get("page_no"))
    if page_no is None and isinstance(node, dict):
        page_no = _positive_page_number((first_prov(node) or {}).get("page_no"))
    source_node_bindings = list(source_node_bindings or [])
    if not source_node_bindings and isinstance(node, dict):
        source_node_bindings = [
            {
                "source_ref": source_ref,
                "self_ref": str(node.get("self_ref") or ""),
                "part_index": part_index,
                "page_no": page_no,
                "bbox": _structural_bbox_snapshot(node_bbox),
                "body_identity_sha256": _structural_body_identity_sha256(
                    str(kind), body_identity
                ),
            }
        ]
    return {
        "version": STRUCTURAL_VISUAL_PROVENANCE_VERSION,
        "kind": str(kind),
        "index": int(index),
        "source_ref": str(source_ref),
        "self_ref": str((node or {}).get("self_ref") or ""),
        "part_index": part_index,
        "page_no": page_no,
        "node_bbox": _structural_bbox_snapshot(node_bbox),
        "crop_bbox": _structural_bbox_snapshot(metric.get("bbox")),
        "crop_clamp_applied": bool(metric.get("crop_clamp_applied")),
        "crop_clip_bounds": _structural_bbox_snapshot(metric.get("crop_clip_bounds")),
        "padding_px": metric.get("padding_px"),
        "render_scale": metric.get("render_scale"),
        "pixel_box": list(metric.get("pixel_box") or []),
        "page_size": visual_page_size,
        "semantic_page_size": semantic_page_size,
        "crop_coordinate_page_size": (
            _structural_page_size_snapshot(crop_coordinate_page_size)
            or visual_page_size
        ),
        "page_image_size": metric.get("page_image_size"),
        "page_image_path": str(metric.get("page_image_path") or ""),
        "page_image_sha256": str(metric.get("page_image_sha256") or "").lower(),
        "asset_path": str(metric.get("path") or ""),
        "asset_sha256": str(metric.get("asset_sha256") or "").lower(),
        "visual_pdf_sha256": str(metric.get("source_pdf_sha256") or "").lower(),
        "semantic_pdf_sha256": str(semantic_pdf_sha256 or "").lower(),
        "conversion_pdf_sha256": str(conversion_pdf_sha256 or "").lower(),
        "geometry_compatibility": _structural_geometry_compatibility(
            semantic_page_size,
            visual_page_size,
        ),
        "structural_body_identity_sha256": _structural_body_identity_sha256(
            str(kind), body_identity
        ),
        "source_node_bindings": source_node_bindings,
    }


def _strict_output_asset_path(output_dir: Path, relative_value: Any) -> Path | None:
    relative = Path(str(relative_value or ""))
    if not str(relative) or relative.is_absolute() or ".." in relative.parts:
        return None
    if output_dir.is_symlink():
        return None
    candidate = output_dir / relative
    current = output_dir
    for part in relative.parts:
        current = current / part
        if current.is_symlink():
            return None
    try:
        candidate.resolve(strict=False).relative_to(output_dir.resolve())
    except (OSError, ValueError):
        return None
    return candidate if candidate.is_file() and not candidate.is_symlink() else None


def _structural_provenance_verify(
    output_dir: Path,
    entry: Any,
    *,
    current_source_ref: str,
    current_page_no: Any,
    current_bbox: Any,
    current_body_identity: str,
    current_self_ref: str = "",
    current_part_index: int | None = None,
    current_semantic_page_size: Any = None,
    expected_visual_pdf_sha256: str | None,
    expected_semantic_pdf_sha256: str | None = None,
    expected_asset_path: str | None = None,
    expected_kind: str | None = None,
) -> tuple[bool, list[str]]:
    """Recompute every file/geometry/body binding used by a structural crop."""

    reasons: list[str] = []
    if not isinstance(entry, dict):
        return False, ["missing_manifest_entry"]
    if entry.get("version") != STRUCTURAL_VISUAL_PROVENANCE_VERSION:
        reasons.append("manifest_version_mismatch")
    if expected_kind and str(entry.get("kind") or "") != expected_kind:
        reasons.append("structural_kind_mismatch")
    if str(entry.get("source_ref") or "") != str(current_source_ref):
        reasons.append("source_ref_mismatch")
    if str(entry.get("self_ref") or "") != str(current_self_ref or ""):
        reasons.append("self_ref_mismatch")
    if entry.get("part_index") != current_part_index:
        reasons.append("part_index_mismatch")
    page_no = _positive_page_number(entry.get("page_no"))
    if page_no is None or page_no != _positive_page_number(current_page_no):
        reasons.append("page_no_mismatch")
    entry_bbox = _structural_bbox_snapshot(entry.get("node_bbox"))
    current_bbox_snapshot = _structural_bbox_snapshot(current_bbox)
    if entry_bbox is None or current_bbox_snapshot is None:
        reasons.append("missing_node_bbox_or_origin")
    elif any(
        entry_bbox[key] != current_bbox_snapshot[key]
        for key in ("l", "r", "t", "b", "coord_origin")
    ):
        reasons.append("node_bbox_mismatch")
    expected_body_sha = _structural_body_identity_sha256(
        str(entry.get("kind") or ""), current_body_identity
    )
    if (
        not re.fullmatch(
            r"[0-9a-f]{64}",
            str(entry.get("structural_body_identity_sha256") or "").lower(),
        )
        or str(entry.get("structural_body_identity_sha256") or "").lower()
        != expected_body_sha
    ):
        reasons.append("structural_body_identity_mismatch")

    expected_visual_sha = str(expected_visual_pdf_sha256 or "").strip().lower()
    declared_visual_sha = str(entry.get("visual_pdf_sha256") or "").lower()
    if not re.fullmatch(r"[0-9a-f]{64}", expected_visual_sha):
        reasons.append("missing_expected_visual_pdf_sha256")
    if (
        not re.fullmatch(r"[0-9a-f]{64}", declared_visual_sha)
        or declared_visual_sha != expected_visual_sha
    ):
        reasons.append("visual_pdf_sha256_mismatch")
    declared_semantic_sha = str(entry.get("semantic_pdf_sha256") or "").lower()
    declared_conversion_sha = str(entry.get("conversion_pdf_sha256") or "").lower()
    if not re.fullmatch(r"[0-9a-f]{64}", declared_semantic_sha):
        reasons.append("missing_semantic_pdf_sha256")
    if not re.fullmatch(r"[0-9a-f]{64}", declared_conversion_sha):
        reasons.append("missing_conversion_pdf_sha256")
    if expected_semantic_pdf_sha256:
        expected_semantic_sha = str(expected_semantic_pdf_sha256).strip().lower()
        if declared_semantic_sha != expected_semantic_sha:
            reasons.append("semantic_pdf_sha256_mismatch")
        if declared_conversion_sha != expected_semantic_sha:
            reasons.append("conversion_pdf_sha256_mismatch")

    visual_page_size = _structural_page_size_snapshot(entry.get("page_size"))
    semantic_page_size = _structural_page_size_snapshot(
        entry.get("semantic_page_size")
    )
    current_semantic_size = _structural_page_size_snapshot(
        current_semantic_page_size
    )
    if visual_page_size is None or semantic_page_size is None:
        reasons.append("missing_page_size")
    if (
        current_semantic_size is not None
        and semantic_page_size is not None
        and current_semantic_size != semantic_page_size
    ):
        reasons.append("semantic_page_size_mismatch")
    compatibility = entry.get("geometry_compatibility")
    if not isinstance(compatibility, dict) or compatibility.get("compatible") is not True:
        reasons.append("visual_semantic_geometry_incompatible")
    if entry_bbox is not None and semantic_page_size is not None:
        if (
            entry_bbox["l"] < 0.0
            or entry_bbox["r"] <= entry_bbox["l"]
            or entry_bbox["r"] > semantic_page_size["width"]
            or min(entry_bbox["t"], entry_bbox["b"]) < 0.0
            or max(entry_bbox["t"], entry_bbox["b"])
            > semantic_page_size["height"]
            or entry_bbox["t"] == entry_bbox["b"]
        ):
            reasons.append("node_bbox_out_of_page_bounds")

    page_image_path = _strict_output_asset_path(
        output_dir, entry.get("page_image_path")
    )
    expected_page_path = f"pages/page_{page_no}.png" if page_no else ""
    if str(entry.get("page_image_path") or "") != expected_page_path:
        reasons.append("page_image_path_mismatch")
    declared_page_sha = str(entry.get("page_image_sha256") or "").lower()
    if page_image_path is None:
        reasons.append("page_image_missing_or_unsafe")
    elif not re.fullmatch(r"[0-9a-f]{64}", declared_page_sha):
        reasons.append("missing_page_image_sha256")
    else:
        try:
            if file_sha256(page_image_path) != declared_page_sha:
                reasons.append("page_image_sha256_mismatch")
        except OSError:
            reasons.append("page_image_hash_failed")

    asset_path_value = str(entry.get("asset_path") or "")
    if expected_asset_path and asset_path_value != expected_asset_path:
        reasons.append("asset_path_mismatch")
    asset_path = _strict_output_asset_path(output_dir, asset_path_value)
    declared_asset_sha = str(entry.get("asset_sha256") or "").lower()
    if asset_path is None:
        reasons.append("asset_missing_or_unsafe")
    elif not re.fullmatch(r"[0-9a-f]{64}", declared_asset_sha):
        reasons.append("missing_asset_sha256")
    else:
        try:
            if file_sha256(asset_path) != declared_asset_sha:
                reasons.append("asset_sha256_mismatch")
        except OSError:
            reasons.append("asset_hash_failed")

    crop_bbox = _structural_bbox_snapshot(entry.get("crop_bbox"))
    crop_clamp_applied = bool(entry.get("crop_clamp_applied"))
    crop_clip_bounds = _structural_bbox_snapshot(entry.get("crop_clip_bounds"))
    if crop_clamp_applied and crop_clip_bounds is None:
        reasons.append("missing_crop_clip_bounds")
    coordinate_page_size = _structural_page_size_snapshot(
        entry.get("crop_coordinate_page_size")
    )
    page_image_size = entry.get("page_image_size")
    try:
        image_width = int((page_image_size or {}).get("width") or 0)
        image_height = int((page_image_size or {}).get("height") or 0)
        padding = int(entry.get("padding_px"))
    except (TypeError, ValueError):
        image_width = image_height = 0
        padding = -1
    declared_pixel_box = entry.get("pixel_box")
    clip_valid = crop_clip_bounds is None
    if crop_clip_bounds is not None:
        clip_values = [
            crop_clip_bounds[key] for key in ("l", "r", "t", "b")
        ]
        clip_origin = crop_clip_bounds.get("coord_origin")
        bbox_origin = (entry_bbox or {}).get("coord_origin")
        crop_origin = (crop_bbox or {}).get("coord_origin")
        if (
            any(not math.isfinite(float(value)) for value in clip_values)
            or clip_origin not in {"TOPLEFT", "BOTTOMLEFT"}
            or (bbox_origin and clip_origin != bbox_origin)
            or (crop_origin and clip_origin != crop_origin)
        ):
            reasons.append("crop_clip_bounds_invalid")
        elif coordinate_page_size is None:
            reasons.append("crop_clip_bounds_missing_page_size")
        else:
            clip_left = float(crop_clip_bounds["l"])
            clip_right = float(crop_clip_bounds["r"])
            clip_top = float(crop_clip_bounds["t"])
            clip_bottom = float(crop_clip_bounds["b"])
            page_width = coordinate_page_size["width"]
            page_height = coordinate_page_size["height"]
            clip_low_y = min(clip_top, clip_bottom)
            clip_high_y = max(clip_top, clip_bottom)
            node_low_y = (
                min(entry_bbox["t"], entry_bbox["b"])
                if entry_bbox is not None
                else float("inf")
            )
            node_high_y = (
                max(entry_bbox["t"], entry_bbox["b"])
                if entry_bbox is not None
                else float("-inf")
            )
            if (
                clip_right <= clip_left
                or clip_high_y <= clip_low_y
                or clip_left < 0.0
                or clip_right > page_width
                or clip_low_y < 0.0
                or clip_high_y > page_height
            ):
                reasons.append("crop_clip_bounds_out_of_page_bounds")
            elif (
                entry_bbox is None
                or clip_left > entry_bbox["l"]
                or clip_right < entry_bbox["r"]
                or clip_low_y > node_low_y
                or clip_high_y < node_high_y
            ):
                reasons.append("crop_clip_bounds_excludes_node")
            else:
                clip_valid = True
    render_scale: float | None = None
    if entry.get("render_scale") is not None:
        try:
            render_scale = float(entry.get("render_scale"))
        except (TypeError, ValueError):
            render_scale = None
            reasons.append("invalid_render_scale")
        else:
            if render_scale <= 0.0:
                render_scale = None
                reasons.append("invalid_render_scale")
    if (
        crop_bbox is None
        or coordinate_page_size is None
        or image_width <= 0
        or image_height <= 0
        or padding < 0
        or not isinstance(declared_pixel_box, list)
        or len(declared_pixel_box) != 4
    ):
        reasons.append("missing_crop_geometry")
    else:
        recomputed = _bbox_pixel_crop_box(
            crop_bbox,
            page_width=coordinate_page_size["width"],
            page_height=coordinate_page_size["height"],
            image_width=image_width,
            image_height=image_height,
            padding=padding,
            render_scale=render_scale,
        )
        if recomputed is not None and crop_clip_bounds is not None and clip_valid:
            clip_box = _bbox_pixel_crop_box(
                crop_clip_bounds,
                page_width=coordinate_page_size["width"],
                page_height=coordinate_page_size["height"],
                image_width=image_width,
                image_height=image_height,
                padding=0,
                render_scale=render_scale,
            )
            if clip_box is None:
                recomputed = None
            else:
                recomputed = (
                    max(recomputed[0], clip_box[0]),
                    max(recomputed[1], clip_box[1]),
                    min(recomputed[2], clip_box[2]),
                    min(recomputed[3], clip_box[3]),
                )
                if recomputed[2] <= recomputed[0] or recomputed[3] <= recomputed[1]:
                    recomputed = None
        if recomputed is None or list(recomputed) != declared_pixel_box:
            reasons.append("pixel_box_mismatch")
    return not reasons, sorted(set(reasons))


def _structural_manifest_entry_for_ref(
    manifest: Any,
    *,
    kind: str,
    source_ref: str,
    index: int | None = None,
) -> tuple[dict[str, Any] | None, list[str]]:
    if not isinstance(manifest, dict):
        return None, ["missing_structural_visual_provenance_manifest"]
    entries = manifest.get(str(kind))
    if not isinstance(entries, list):
        return None, [f"missing_{kind}_provenance_inventory"]
    matches = [
        item
        for item in entries
        if isinstance(item, dict)
        and str(item.get("source_ref") or "") == str(source_ref)
        and (index is None or item.get("index") == index)
    ]
    if len(matches) != 1:
        return None, [
            f"{kind}_provenance_entry_"
            + ("missing" if not matches else "ambiguous")
        ]
    return matches[0], []


def _structural_expected_visual_pdf_sha256(metadata: Any) -> str | None:
    if not isinstance(metadata, dict):
        return None
    value = str(metadata.get("visual_evidence_input_sha256") or "").strip().lower()
    return value if re.fullmatch(r"[0-9a-f]{64}", value) else None


def _structural_expected_semantic_pdf_sha256(metadata: Any) -> str | None:
    if not isinstance(metadata, dict):
        return None
    value = str(
        metadata.get("conversion_input_sha256")
        or metadata.get("input_sha256")
        or ""
    ).strip().lower()
    return value if re.fullmatch(r"[0-9a-f]{64}", value) else None


def _replace_structural_manifest_entry(
    manifest: dict[str, Any] | None,
    *,
    inventory: str,
    entry: dict[str, Any],
) -> None:
    if not isinstance(manifest, dict):
        return
    values = manifest.setdefault(inventory, [])
    if not isinstance(values, list):
        values = []
        manifest[inventory] = values
    values[:] = [
        value
        for value in values
        if not (
            isinstance(value, dict)
            and value.get("index") == entry.get("index")
            and str(value.get("source_ref") or "")
            == str(entry.get("source_ref") or "")
        )
    ]
    values.append(entry)


def _structural_page_manifest_verify(
    output_dir: Path,
    manifest: Any,
    *,
    page_no: int,
    expected_visual_pdf_sha256: str | None,
    current_semantic_page_size: Any,
) -> tuple[bool, list[str], dict[str, Any] | None]:
    reasons: list[str] = []
    if not isinstance(manifest, dict):
        return False, ["missing_structural_visual_provenance_manifest"], None
    pages = manifest.get("pages")
    entry = pages.get(str(page_no)) if isinstance(pages, dict) else None
    if not isinstance(entry, dict):
        return False, ["missing_page_provenance_entry"], None
    if _positive_page_number(entry.get("page_no")) != page_no:
        reasons.append("page_manifest_page_no_mismatch")
    expected_path = f"pages/page_{page_no}.png"
    if str(entry.get("path") or "") != expected_path:
        reasons.append("page_manifest_path_mismatch")
    expected_visual = str(expected_visual_pdf_sha256 or "").lower()
    declared_visual = str(entry.get("visual_pdf_sha256") or "").lower()
    manifest_visual = str(manifest.get("visual_pdf_sha256") or "").lower()
    if not re.fullmatch(r"[0-9a-f]{64}", expected_visual):
        reasons.append("missing_expected_visual_pdf_sha256")
    if declared_visual != expected_visual or manifest_visual != expected_visual:
        reasons.append("page_manifest_visual_pdf_sha256_mismatch")
    semantic_size = _structural_page_size_snapshot(current_semantic_page_size)
    recorded_semantic_size = _structural_page_size_snapshot(
        entry.get("semantic_page_size")
    )
    visual_size = _structural_page_size_snapshot(entry.get("page_size"))
    if semantic_size is None or recorded_semantic_size is None or visual_size is None:
        reasons.append("page_manifest_missing_page_size")
    else:
        if semantic_size != recorded_semantic_size:
            reasons.append("page_manifest_semantic_page_size_mismatch")
        if not _structural_geometry_compatibility(
            recorded_semantic_size,
            visual_size,
        ).get("compatible"):
            reasons.append("page_manifest_geometry_incompatible")
    page_path = _strict_output_asset_path(output_dir, expected_path)
    declared_hash = str(entry.get("page_image_sha256") or "").lower()
    if page_path is None:
        reasons.append("page_manifest_image_missing_or_unsafe")
    elif not re.fullmatch(r"[0-9a-f]{64}", declared_hash):
        reasons.append("page_manifest_missing_image_sha256")
    else:
        try:
            if file_sha256(page_path) != declared_hash:
                reasons.append("page_manifest_image_sha256_mismatch")
        except OSError:
            reasons.append("page_manifest_image_hash_failed")
    return not reasons, sorted(set(reasons)), entry


def _structural_entry_page_manifest_reasons(
    entry: Any,
    page_entry: Any,
) -> list[str]:
    if not isinstance(entry, dict) or not isinstance(page_entry, dict):
        return ["missing_entry_or_page_manifest_binding"]
    reasons: list[str] = []
    for entry_key, page_key in (
        ("page_no", "page_no"),
        ("page_image_path", "path"),
        ("page_image_sha256", "page_image_sha256"),
        ("visual_pdf_sha256", "visual_pdf_sha256"),
        ("page_size", "page_size"),
        ("semantic_page_size", "semantic_page_size"),
        ("page_image_size", "page_image_size"),
    ):
        if entry.get(entry_key) != page_entry.get(page_key):
            reasons.append(f"entry_page_manifest_{entry_key}_mismatch")
    return reasons


def _html_source_ref(attrs: str) -> str | None:
    match = re.search(
        r"\bdata-source-ref\s*=\s*([\"'])(?P<value>.*?)\1",
        attrs,
        flags=re.I | re.S,
    )
    return html.unescape(match.group("value")) if match else None


def _html_table_grid_for_source_ref(
    document_html: str,
    source_ref: str,
) -> list[list[str]] | None:
    matches = [
        match
        for match in re.finditer(
            r"<table\b(?P<attrs>[^>]*)>(?P<body>.*?)</table>",
            document_html,
            flags=re.I | re.S,
        )
        if _html_source_ref(match.group("attrs")) == source_ref
    ]
    if len(matches) != 1:
        return None
    row_matches = list(
        re.finditer(
            r"<tr\b[^>]*>(?P<body>.*?)</tr>",
            matches[0].group("body"),
            flags=re.I | re.S,
        )
    )
    if not row_matches:
        return None
    values: dict[tuple[int, int], str] = {}
    covered: set[tuple[int, int]] = set()
    maximum_row = len(row_matches)
    maximum_column = 0
    for row_index, row_match in enumerate(row_matches):
        column = 0
        cells = list(
            re.finditer(
                r"<(?:td|th)\b(?P<attrs>[^>]*)>(?P<body>.*?)</(?:td|th)>",
                row_match.group("body"),
                flags=re.I | re.S,
            )
        )
        for cell in cells:
            while (row_index, column) in covered:
                column += 1
            attrs = cell.group("attrs")
            rowspan_match = re.search(r"\browspan\s*=\s*[\"']?(\d+)", attrs, re.I)
            colspan_match = re.search(r"\bcolspan\s*=\s*[\"']?(\d+)", attrs, re.I)
            rowspan = max(1, int(rowspan_match.group(1)) if rowspan_match else 1)
            colspan = max(1, int(colspan_match.group(1)) if colspan_match else 1)
            values[(row_index, column)] = _structural_visible_body_text(
                cell.group("body"),
                html_markup=True,
            )
            for covered_row in range(row_index, row_index + rowspan):
                for covered_column in range(column, column + colspan):
                    if covered_row != row_index or covered_column != column:
                        covered.add((covered_row, covered_column))
                        values.setdefault((covered_row, covered_column), "")
            maximum_row = max(maximum_row, row_index + rowspan)
            maximum_column = max(maximum_column, column + colspan)
            column += colspan
        maximum_column = max(maximum_column, column)
    if maximum_column <= 0:
        return None
    return [
        [values.get((row, column), "") for column in range(maximum_column)]
        for row in range(maximum_row)
    ]


def _markdown_marker_range(
    document_markdown: str,
    *,
    kind: str,
    source_ref: str,
) -> tuple[int, int] | None:
    marker = f"<!-- source-{kind}-ref:{source_ref} -->"
    masked_markdown = _markdown_mask_code(document_markdown)
    marker_matches = list(re.finditer(re.escape(marker), masked_markdown))
    if len(marker_matches) != 1:
        return None
    start = marker_matches[0].end()
    next_marker = re.search(
        r"<!--\s*source-(?:table|code|algorithm)-ref:",
        masked_markdown[start:],
        flags=re.I,
    )
    end = start + next_marker.start() if next_marker else len(document_markdown)
    appendix = re.search(
        r"(?m)^## Original (?:table|code|algorithm) renderings\s*$",
        masked_markdown[start:end],
        flags=re.I,
    )
    if appendix:
        end = start + appendix.start()
    return start, end


def _markdown_marker_window(
    document_markdown: str,
    *,
    kind: str,
    source_ref: str,
) -> str | None:
    marker_range = _markdown_marker_range(
        document_markdown,
        kind=kind,
        source_ref=source_ref,
    )
    if marker_range is None:
        return None
    return document_markdown[marker_range[0] : marker_range[1]]


def _split_markdown_table_row(line: str) -> list[str]:
    row = line.strip()
    if row.startswith("|"):
        row = row[1:]
    if row.endswith("|") and not row.endswith(r"\|"):
        row = row[:-1]
    cells = re.split(r"(?<!\\)\|", row)
    visible_cells: list[str] = []
    for cell in cells:
        visible = cell.replace(r"\|", "|")
        visible = re.sub(r"<br\s*/?>", " ", visible, flags=re.I)
        visible = _markdown_link_labels(visible)
        visible = re.sub(r"`([^`]*)`", r"\1", visible)
        visible = re.sub(r"\*\*(?=\S)(.*?\S)\*\*", r"\1", visible)
        visible = re.sub(r"__(?=\S)(.*?\S)__", r"\1", visible)
        visible = re.sub(r"\[\^([^\]]+)\]", "", visible)
        visible = re.sub(r"\\([\\`*_{}\[\]()#+.!|>\-])", r"\1", visible)
        visible_cells.append(visible.strip())
    return visible_cells


def _markdown_link_labels(value: str) -> str:
    """Remove Markdown link destinations while preserving nested labels.

    Author-year table citations commonly render as
    ``[Author [2026]](#ref-7)``.  A flat regular expression stops at the inner
    bracket and leaves the destination in the structural identity.  This
    bounded scanner understands balanced brackets/parentheses and changes no
    bracketed text that is not actually followed by a link target.
    """

    output: list[str] = []
    index = 0
    while index < len(value):
        image = value[index] == "!" and index + 1 < len(value) and value[index + 1] == "["
        bracket = index + 1 if image else index
        if value[bracket : bracket + 1] != "[":
            output.append(value[index])
            index += 1
            continue
        depth = 1
        cursor = bracket + 1
        while cursor < len(value) and depth:
            if value[cursor] == "\\":
                cursor += 2
                continue
            if value[cursor] == "[":
                depth += 1
            elif value[cursor] == "]":
                depth -= 1
            cursor += 1
        if depth or cursor >= len(value) or value[cursor] != "(":
            output.append(value[index])
            index += 1
            continue
        target_depth = 1
        target_end = cursor + 1
        while target_end < len(value) and target_depth:
            if value[target_end] == "\\":
                target_end += 2
                continue
            if value[target_end] == "(":
                target_depth += 1
            elif value[target_end] == ")":
                target_depth -= 1
            target_end += 1
        if target_depth:
            output.append(value[index])
            index += 1
            continue
        label = value[bracket + 1 : cursor - 1]
        output.append(_markdown_link_labels(label))
        index = target_end
    return "".join(output)


def _markdown_table_grid_for_source_ref(
    document_markdown: str,
    source_ref: str,
) -> list[list[str]] | None:
    window = _markdown_marker_window(
        document_markdown,
        kind="table",
        source_ref=source_ref,
    )
    if window is None:
        return None
    lines = window.splitlines()
    for separator_index, line in enumerate(lines):
        if "|" not in line or separator_index == 0:
            continue
        separator_cells = _split_markdown_table_row(line)
        if not separator_cells or not all(
            re.fullmatch(r":?-{1,}:?", cell.strip())
            for cell in separator_cells
        ):
            continue
        header = _split_markdown_table_row(lines[separator_index - 1])
        if "|" not in lines[separator_index - 1]:
            continue
        rows = [header]
        for body_line in lines[separator_index + 1 :]:
            if "|" not in body_line:
                break
            rows.append(_split_markdown_table_row(body_line))
        width = max((len(row) for row in rows), default=0)
        if width <= 0:
            return None
        return [row + [""] * (width - len(row)) for row in rows]
    return None


def _html_section_pre_body_for_source_ref(
    document_html: str,
    *,
    css_class: str,
    source_ref: str,
) -> str | None:
    bodies: list[str] = []
    for section in re.finditer(
        r"<section\b(?P<attrs>[^>]*)>(?P<body>.*?)</section>",
        document_html,
        flags=re.I | re.S,
    ):
        class_match = re.search(
            r"\bclass\s*=\s*([\"'])(?P<value>.*?)\1",
            section.group("attrs"),
            flags=re.I | re.S,
        )
        classes = set((class_match.group("value") if class_match else "").split())
        if css_class not in classes:
            continue
        for pre in re.finditer(
            r"<pre\b(?P<attrs>[^>]*)>\s*(?:<code\b[^>]*>)?"
            r"(?P<body>.*?)(?:</code>\s*)?</pre>",
            section.group("body"),
            flags=re.I | re.S,
        ):
            if _html_source_ref(pre.group("attrs")) == source_ref:
                bodies.append(pre.group("body"))
    return bodies[0] if len(bodies) == 1 else None


def _html_section_range_for_source_ref(
    document_html: str,
    *,
    css_class: str,
    source_ref: str,
) -> tuple[int, int] | None:
    ranges: list[tuple[int, int]] = []
    for section in re.finditer(
        r"<section\b(?P<attrs>[^>]*)>(?P<body>.*?)</section>",
        document_html,
        flags=re.I | re.S,
    ):
        class_match = re.search(
            r"\bclass\s*=\s*([\"'])(?P<value>.*?)\1",
            section.group("attrs"),
            flags=re.I | re.S,
        )
        classes = set((class_match.group("value") if class_match else "").split())
        if css_class not in classes:
            continue
        if any(
            _html_source_ref(pre.group("attrs")) == source_ref
            for pre in re.finditer(
                r"<pre\b(?P<attrs>[^>]*)>",
                section.group("body"),
                flags=re.I | re.S,
            )
        ):
            ranges.append((section.start(), section.end()))
    return ranges[0] if len(ranges) == 1 else None


def _markdown_fenced_body_for_source_ref(
    document_markdown: str,
    *,
    kind: str,
    source_ref: str,
) -> str | None:
    window = _markdown_marker_window(
        document_markdown,
        kind=kind,
        source_ref=source_ref,
    )
    if window is None:
        return None
    fences = _markdown_fenced_ranges(window)
    if len(fences) != 1:
        return None
    start, end = fences[0]
    block = window[start:end]
    lines = block.splitlines(keepends=True)
    if len(lines) < 2:
        return None
    opening = lines[0]
    fence_marker = re.search(r"`{3,}|~{3,}", opening)
    if fence_marker is None:
        return None
    closing = _markdown_strip_container_prefix(lines[-1])
    if not re.fullmatch(
        rf"[ \t]{{0,3}}{re.escape(fence_marker.group(0)[0])}"
        rf"{{{len(fence_marker.group(0))},}}[ \t]*",
        closing,
    ):
        return None
    container_prefix = opening[: fence_marker.start()] if fence_marker else ""
    body_lines = lines[1:-1]
    if container_prefix:
        body_lines = [
            line[len(container_prefix) :]
            if line.startswith(container_prefix)
            else line
            for line in body_lines
        ]
    return "".join(body_lines)


def append_structured_table_source_renderings(
    output_dir: Path,
    document_json: Any,
    tables: list[dict[str, Any]],
    *,
    provenance_manifest: dict[str, Any] | None = None,
    expected_visual_pdf_sha256: str | None = None,
    expected_semantic_pdf_sha256: str | None = None,
) -> dict[str, Any]:
    """Append exact PDF crops for non-empty tables without replacing structure."""
    nodes_by_ref = _structural_nodes_by_part_ref(document_json)
    page_inventory = _document_page_size_inventory(document_json)
    candidates: list[dict[str, Any]] = []
    expected_body_identity_by_ref: dict[str, str] = {}
    provenance_verified_refs: list[str] = []
    provenance_mismatch_refs: list[str] = []
    provenance_diagnostics: dict[str, list[str]] = {}
    for index, table in enumerate(tables, start=1):
        table_part_index = _structural_node_part_index(table)
        source_grid = table_grid(table)
        # Raw 0x0 tables are certified by the explicit visual-fallback gate,
        # not by pretending that an absent semantic table body has identity.
        if not source_grid:
            continue
        image_path = output_dir / "tables" / f"table_{index}.png"
        if not image_path.exists():
            continue
        caption_texts: list[str] = []
        for caption in table.get("captions") or []:
            reference = str(caption.get("$ref") or "")
            text = str(
                (nodes_by_ref.get((table_part_index, reference)) or {}).get("text")
                or ""
            ).strip()
            if text:
                caption_texts.append(text)
        caption = " ".join(caption_texts) or f"Table {index}"
        if re.match(r"(?i)^Figure\b", caption):
            caption = f"Table {index}"
        source_ref = _structural_node_source_ref(
            table,
            kind="table",
            fallback_index=index - 1,
            part_index=table_part_index,
        )
        expected_identity = _table_grid_body_identity(source_grid)
        expected_body_identity_by_ref[source_ref] = expected_identity
        page_no = _positive_page_number((first_prov(table) or {}).get("page_no"))
        page_size = (
            (
                (page_inventory.get("page_records") or {}).get(page_no)
                or {}
            ).get("size")
            or None
        )
        manifest_entry, lookup_reasons = _structural_manifest_entry_for_ref(
            provenance_manifest,
            kind="tables",
            source_ref=source_ref,
            index=index,
        )
        verified, verify_reasons = _structural_provenance_verify(
            output_dir,
            manifest_entry,
            current_source_ref=source_ref,
            current_page_no=page_no,
            current_bbox=(first_prov(table) or {}).get("bbox"),
            current_body_identity=expected_identity,
            current_self_ref=str(table.get("self_ref") or ""),
            current_part_index=table_part_index,
            current_semantic_page_size=page_size,
            expected_visual_pdf_sha256=expected_visual_pdf_sha256,
            expected_semantic_pdf_sha256=expected_semantic_pdf_sha256,
            expected_asset_path=f"tables/table_{index}.png",
            expected_kind="table",
        )
        reasons = sorted(set(lookup_reasons + verify_reasons))
        if verified and not lookup_reasons:
            provenance_verified_refs.append(source_ref)
        else:
            provenance_mismatch_refs.append(source_ref)
            provenance_diagnostics[source_ref] = reasons
        candidates.append(
            {
                "table_index": index,
                "image": f"tables/table_{index}.png",
                "caption": caption,
                "page_no": page_no,
                "source_ref": source_ref,
                "provenance_verified": verified and not lookup_reasons,
                "provenance_reasons": reasons,
            }
        )

    html_applied = 0
    html_path = output_dir / "document.html"
    if candidates and html_path.exists():
        document_html = html_path.read_text(encoding="utf-8")
        document_html = _strip_source_disclosure_blocks(
            document_html,
            extra_class="docling-table-source-disclosure",
        )
        document_html = re.sub(
            r'<section\b[^>]*class="[^"]*\bdocling-table-source-evidence-appendix\b[^"]*"[^>]*>.*?</section>',
            "",
            document_html,
            flags=re.I | re.S,
        )
        def evidence_figure(candidate: dict[str, Any]) -> str:
            figure = (
                '<figure class="docling-table-source-evidence">'
                f'<span hidden data-source-ref="{html.escape(str(candidate["source_ref"]), quote=True)}"></span>'
                f'<img src="{candidate["image"]}" '
                f'alt="{html.escape(candidate["caption"], quote=True)} source rendering">'
                f'<figcaption>{html.escape(candidate["caption"])} — '
                "exact source rendering from the original PDF</figcaption>"
                "</figure>"
            )
            return _source_disclosure_html(
                figure,
                summary="查看表格原始裁剪",
                extra_class="docling-table-source-disclosure",
                attrs=(
                    f' data-source-ref="{html.escape(str(candidate["source_ref"]), quote=True)}"'
                ),
            )
        html_bound_refs: list[str] = []
        unmatched_candidates: list[dict[str, Any]] = []
        for candidate in candidates:
            source_ref = str(candidate["source_ref"])
            escaped_ref = re.escape(html.escape(source_ref, quote=True))
            block_re = re.compile(
                r'(?P<block><figure\b[^>]*class="[^"]*\bsemantic-table\b[^"]*"[^>]*>'
                r".*?<table\b[^>]*data-source-ref=[\"']"
                + escaped_ref
                + r"[\"'][^>]*>.*?</figure>)",
                flags=re.I | re.S,
            )
            document_html, applied = block_re.subn(
                lambda match, candidate=candidate: (
                    match.group("block") + evidence_figure(candidate)
                ),
                document_html,
                count=1,
            )
            if applied:
                html_bound_refs.append(source_ref)
            else:
                unmatched_candidates.append(candidate)
        figures = "\n".join(
            evidence_figure(candidate) for candidate in unmatched_candidates
        )
        appendix = (
            '<section class="docling-table-source-evidence-appendix">'
            "<h2>Original table renderings</h2>"
            f"{figures}</section>"
        )
        if unmatched_candidates and "</body>" in document_html.lower():
            match = re.search(r"</body>", document_html, flags=re.I)
            assert match is not None
            document_html = (
                document_html[: match.start()] + appendix + document_html[match.start() :]
            )
        html_path.write_text(document_html, encoding="utf-8")
        html_applied = len(html_bound_refs) + (
            len(unmatched_candidates) if "</body>" in document_html.lower() else 0
        )
    else:
        html_bound_refs = []
        unmatched_candidates = []

    markdown_applied = 0
    md_path = output_dir / "document.md"
    if candidates and md_path.exists():
        document_markdown = md_path.read_text(encoding="utf-8").rstrip()
        document_markdown = re.sub(
            r'<details\b[^>]*class="[^"]*\bdocling-table-source-disclosure\b[^"]*"[^>]*>.*?</details>',
            "",
            document_markdown,
            flags=re.I | re.S,
        )
        markdown_bound_refs: list[str] = []
        unmatched_markdown_candidates: list[dict[str, Any]] = []
        for candidate in candidates:
            source_ref = str(candidate["source_ref"])
            marker = f"<!-- source-table-ref:{source_ref} -->"
            evidence = (
                marker
                + "\n\n"
                + _source_disclosure_markdown(
                    _markdown_image(
                        f'{candidate["caption"]} — source rendering',
                        candidate["image"],
                    ),
                    summary="查看表格原始裁剪",
                    extra_class="docling-table-source-disclosure",
                )
            )
            if document_markdown.count(marker) == 1:
                document_markdown = document_markdown.replace(marker, evidence, 1)
                markdown_bound_refs.append(source_ref)
            else:
                unmatched_markdown_candidates.append(candidate)
        if unmatched_markdown_candidates:
            parts = [
                "",
                "## Original table renderings",
                "",
                (
                    "The following images preserve tables that could not be bound "
                    "to a unique semantic occurrence."
                ),
            ]
            for candidate in unmatched_markdown_candidates:
                parts.extend(
                    [
                        "",
                        _source_disclosure_markdown(
                            _markdown_image(
                                f'{candidate["caption"]} — source rendering',
                                candidate["image"],
                            ),
                            summary="查看表格原始裁剪",
                            extra_class="docling-table-source-disclosure",
                        ),
                    ]
                )
            document_markdown = document_markdown + "\n".join(parts)
        md_path.write_text(document_markdown.rstrip() + "\n", encoding="utf-8")
        markdown_applied = len(markdown_bound_refs) + len(unmatched_markdown_candidates)
    else:
        markdown_bound_refs = []
        unmatched_markdown_candidates = []

    final_html = html_path.read_text(encoding="utf-8") if html_path.exists() else ""
    final_markdown = md_path.read_text(encoding="utf-8") if md_path.exists() else ""
    html_body_identity_verified_refs: list[str] = []
    markdown_body_identity_verified_refs: list[str] = []
    html_body_identity_mismatch_refs: list[str] = []
    markdown_body_identity_mismatch_refs: list[str] = []
    body_identity_diagnostics: dict[str, dict[str, str]] = {}
    for candidate in candidates:
        source_ref = str(candidate["source_ref"])
        expected_identity = expected_body_identity_by_ref.get(source_ref, "")
        html_grid = _html_table_grid_for_source_ref(final_html, source_ref)
        markdown_grid = _markdown_table_grid_for_source_ref(
            final_markdown,
            source_ref,
        )
        html_identity = (
            _table_grid_body_identity(html_grid) if html_grid is not None else ""
        )
        markdown_identity = (
            _table_grid_body_identity(markdown_grid)
            if markdown_grid is not None
            else ""
        )
        if expected_identity and html_identity == expected_identity:
            html_body_identity_verified_refs.append(source_ref)
        else:
            html_body_identity_mismatch_refs.append(source_ref)
        if expected_identity and markdown_identity == expected_identity:
            markdown_body_identity_verified_refs.append(source_ref)
        else:
            markdown_body_identity_mismatch_refs.append(source_ref)
        body_identity_diagnostics[source_ref] = {
            "html": "verified" if html_identity == expected_identity and expected_identity else "mismatch",
            "markdown": (
                "verified"
                if markdown_identity == expected_identity and expected_identity
                else "mismatch"
            ),
        }

    return {
        "candidate_count": len(candidates),
        "html_applied_count": html_applied,
        "markdown_applied_count": markdown_applied,
        "candidate_source_refs": [str(item["source_ref"]) for item in candidates],
        "html_bound_source_refs": html_bound_refs,
        "markdown_bound_source_refs": markdown_bound_refs,
        "html_unbound_source_refs": [
            str(item["source_ref"]) for item in unmatched_candidates
        ],
        "markdown_unbound_source_refs": [
            str(item["source_ref"]) for item in unmatched_markdown_candidates
        ],
        "html_body_identity_verified_refs": sorted(
            set(html_body_identity_verified_refs)
        ),
        "markdown_body_identity_verified_refs": sorted(
            set(markdown_body_identity_verified_refs)
        ),
        "html_body_identity_mismatch_refs": sorted(
            set(html_body_identity_mismatch_refs)
        ),
        "markdown_body_identity_mismatch_refs": sorted(
            set(markdown_body_identity_mismatch_refs)
        ),
        "body_identity_diagnostics": body_identity_diagnostics,
        "provenance_verified_refs": sorted(set(provenance_verified_refs)),
        "provenance_mismatch_refs": sorted(set(provenance_mismatch_refs)),
        "provenance_diagnostics": provenance_diagnostics,
        "candidates": candidates,
    }


def _parse_formula_source_crop_diagnostics(
    formula_crop_diagnostics: list[dict[str, Any]] | None,
    suspicious_formula_diagnostics: list[dict[str, Any]] | None = None,
) -> dict[int, dict[str, Any]]:
    parsed = {
        int(item["index"]): item
        for item in formula_crop_diagnostics or []
        if isinstance(item.get("index"), int)
    }
    for suspicious in suspicious_formula_diagnostics or []:
        index = suspicious.get("index")
        if not isinstance(index, int):
            continue
        merged = dict(parsed.get(index) or {})
        merged["index"] = index
        merged["reasons"] = sorted(
            {
                *[str(reason) for reason in (merged.get("reasons") or [])],
                *[str(reason) for reason in (suspicious.get("reasons") or [])],
            }
        )
        for key in ("source_crop", "context_crop", "evidence", "full_page_evidence"):
            if suspicious.get(key) is not None:
                merged[key] = suspicious[key]
        parsed[index] = merged
    return parsed


def _formula_image_size(path: Path) -> tuple[int, int] | None:
    try:
        from PIL import Image

        with Image.open(path) as image:
            return int(image.width), int(image.height)
    except Exception:
        return None


def _image_has_visible_content(path: Path) -> bool:
    """Reject blank/solid crops that cannot provide visual source evidence."""
    try:
        from PIL import Image

        with Image.open(path) as image:
            rgba = image.convert("RGBA")
            background = Image.new("RGBA", rgba.size, (255, 255, 255, 255))
            background.alpha_composite(rgba)
            grayscale = background.convert("L")
            low, high = grayscale.getextrema()
            if high - low < 8:
                return False
            histogram = grayscale.histogram()
            total = max(1, grayscale.width * grayscale.height)
            non_dominant = total - max(histogram)
            return non_dominant >= max(4, int(total * 0.0002))
    except Exception:
        return False


def _formula_crop_has_glyph_geometry(path: Path) -> bool:
    """Distinguish a formula line from an isolated rule/separator.

    A thin occurrence bbox is common in two-column papers, so the bbox aspect
    ratio alone is not evidence that the crop is a separator.  Conversely a
    solid bar or rectangle must never authorize a much larger context crop.
    Require ink on several vertical rows and reject crops whose ink is almost
    entirely one or more page-wide horizontal strokes.
    """

    try:
        from PIL import Image

        with Image.open(path) as image:
            grayscale = image.convert("RGBA")
            background = Image.new("RGBA", grayscale.size, (255, 255, 255, 255))
            background.alpha_composite(grayscale)
            luminance = background.convert("L")
            width, height = luminance.size
            if width <= 0 or height <= 0:
                return False
            ink_by_row = [
                sum(
                    1
                    for column in range(width)
                    if luminance.getpixel((column, row)) < 180
                )
                for row in range(height)
            ]
    except Exception:
        return False
    ink_rows = [value for value in ink_by_row if value > 0]
    if len(ink_rows) < max(5, min(10, int(height * 0.3))):
        return False
    total_ink = sum(ink_rows)
    dense_ink = sum(value for value in ink_rows if value >= width * 0.55)
    if total_ink <= 0 or dense_ink / total_ink >= 0.78:
        return False
    return True


def _formula_source_crop_reasons_for_index(
    formula_crop_diagnostics: dict[int, dict[str, Any]],
    formula_index: int,
) -> list[str]:
    item = formula_crop_diagnostics.get(formula_index)
    if not item:
        return []
    return [str(reason) for reason in (item.get("reasons") or [])]


def _formula_crop_provenance_is_verified(
    path: Path,
    formula_crop_diagnostics: dict[int, dict[str, Any]],
    formula_index: int,
    *,
    formula: dict[str, Any] | None,
    for_context: bool,
    expected_visual_pdf_sha256: str | None = None,
    allow_raw_identity: bool = False,
) -> bool:
    item = formula_crop_diagnostics.get(formula_index)
    if not isinstance(item, dict):
        return False
    metric = item.get("context" if for_context else "source")
    if not isinstance(metric, dict):
        return False
    expected_path = (
        f"formulas/formula_{formula_index}_context.png"
        if for_context
        else f"formulas/formula_{formula_index}.png"
    )
    if str(metric.get("path") or "") != expected_path:
        return False
    page_no = _positive_page_number(item.get("page_no"))
    if page_no is None or _positive_page_number(metric.get("page_no")) != page_no:
        return False
    if not isinstance(formula, dict):
        return False
    formula_prov = first_prov(formula)
    if not isinstance(formula_prov, dict):
        return False
    if _positive_page_number(formula_prov.get("page_no")) != page_no:
        return False
    item_bbox = item.get("bbox")
    metric_bbox = metric.get("bbox")
    if not isinstance(item_bbox, dict) or not isinstance(metric_bbox, dict):
        return False
    formula_bbox = formula_prov.get("bbox")
    if not isinstance(formula_bbox, dict):
        return False
    item_origin = _bbox_explicit_coord_origin(item_bbox)
    metric_origin = _bbox_explicit_coord_origin(metric_bbox)
    formula_origin = _bbox_explicit_coord_origin(formula_bbox)
    if (
        item_origin is None
        or metric_origin is None
        or formula_origin is None
        or len({item_origin, metric_origin, formula_origin}) != 1
    ):
        return False
    item_geometry = bbox_geometry({"bbox": item_bbox})
    metric_geometry = bbox_geometry({"bbox": metric_bbox})
    formula_geometry = bbox_geometry(formula_prov)
    if (
        item_geometry is None
        or metric_geometry is None
        or formula_geometry is None
    ):
        return False
    for key in ("l", "r", "t", "b"):
        if abs(float(item_geometry[key]) - float(metric_geometry[key])) > 1e-6:
            return False
        if abs(float(formula_geometry[key]) - float(metric_geometry[key])) > 1e-6:
            return False
    if item_geometry.get("coord_origin") != metric_geometry.get("coord_origin"):
        return False
    if formula_geometry.get("coord_origin") != metric_geometry.get("coord_origin"):
        return False
    identity_field = (
        "formula_raw_content_sha256"
        if allow_raw_identity
        else "formula_content_identity_sha256"
    )
    current_identity_sha256 = (
        _formula_raw_content_sha256(str(formula.get("text") or ""))
        if allow_raw_identity
        else _formula_content_identity_sha256(str(formula.get("text") or ""))
    )
    metric_identity_sha256 = str(metric.get(identity_field) or "").lower()
    item_identity_sha256 = str(item.get(identity_field) or "").lower()
    if (
        not current_identity_sha256
        or not re.fullmatch(r"[0-9a-f]{64}", metric_identity_sha256)
        or not re.fullmatch(r"[0-9a-f]{64}", item_identity_sha256)
        or metric_identity_sha256 != current_identity_sha256
        or item_identity_sha256 != current_identity_sha256
    ):
        return False
    page_size = metric.get("page_size") or {}
    try:
        page_width = float(page_size.get("width") or 0.0)
        page_height = float(page_size.get("height") or 0.0)
    except (TypeError, ValueError):
        return False
    if (
        page_width <= 0.0
        or page_height <= 0.0
        or float(metric_geometry["l"]) < 0.0
        or float(metric_geometry["r"]) > page_width
        or min(float(metric_geometry["t"]), float(metric_geometry["b"])) < 0.0
        or max(float(metric_geometry["t"]), float(metric_geometry["b"]))
        > page_height
    ):
        return False
    # New crop metrics carry the exact raster box.  Legacy hand-built
    # diagnostics may omit it, so keep those compatible while fail-closing any
    # entry that claims a clamp or declares a pixel box.
    declared_pixel_box = metric.get("pixel_box")
    if (
        declared_pixel_box is not None
        or metric.get("crop_clamp_applied")
        or metric.get("crop_clip_bounds") is not None
    ):
        try:
            image_size = metric.get("page_image_size") or {}
            image_width = int(image_size.get("width") or 0)
            image_height = int(image_size.get("height") or 0)
            padding = int(metric.get("padding_px"))
            render_scale = (
                float(metric.get("render_scale"))
                if metric.get("render_scale") is not None
                else None
            )
        except (AttributeError, TypeError, ValueError):
            return False
        if (
            image_width <= 0
            or image_height <= 0
            or padding < 0
            or not isinstance(declared_pixel_box, (list, tuple))
            or len(declared_pixel_box) != 4
            or (render_scale is not None and render_scale <= 0.0)
        ):
            return False
        clip_bounds = metric.get("crop_clip_bounds")
        clip_valid = clip_bounds is None
        if metric.get("crop_clamp_applied") and not isinstance(clip_bounds, dict):
            return False
        if isinstance(clip_bounds, dict):
            clip_snapshot = _structural_bbox_snapshot(clip_bounds)
            if clip_snapshot is None:
                return False
            clip_values = [clip_snapshot[key] for key in ("l", "r", "t", "b")]
            if (
                any(not math.isfinite(float(value)) for value in clip_values)
                or clip_snapshot.get("coord_origin") != metric_origin
                or clip_snapshot["r"] <= clip_snapshot["l"]
                or max(clip_snapshot["t"], clip_snapshot["b"]) > page_height
                or min(clip_snapshot["t"], clip_snapshot["b"]) < 0.0
                or clip_snapshot["l"] < 0.0
                or clip_snapshot["r"] > page_width
                or clip_snapshot["l"] > metric_geometry["l"]
                or clip_snapshot["r"] < metric_geometry["r"]
                or min(clip_snapshot["t"], clip_snapshot["b"])
                > min(metric_geometry["t"], metric_geometry["b"])
                or max(clip_snapshot["t"], clip_snapshot["b"])
                < max(metric_geometry["t"], metric_geometry["b"])
            ):
                return False
            clip_valid = True
        recomputed = _bbox_pixel_crop_box(
            metric_bbox,
            page_width=page_width,
            page_height=page_height,
            image_width=image_width,
            image_height=image_height,
            padding=padding,
            render_scale=render_scale,
        )
        if recomputed is not None and isinstance(clip_bounds, dict) and clip_valid:
            clip_box = _bbox_pixel_crop_box(
                clip_bounds,
                page_width=page_width,
                page_height=page_height,
                image_width=image_width,
                image_height=image_height,
                padding=0,
                render_scale=render_scale,
            )
            if clip_box is None:
                return False
            recomputed = (
                max(recomputed[0], clip_box[0]),
                max(recomputed[1], clip_box[1]),
                min(recomputed[2], clip_box[2]),
                min(recomputed[3], clip_box[3]),
            )
            if recomputed[2] <= recomputed[0] or recomputed[3] <= recomputed[1]:
                return False
        if recomputed is None or list(recomputed) != list(declared_pixel_box):
            return False
    declared_asset_sha256 = str(metric.get("asset_sha256") or "").lower()
    if not re.fullmatch(r"[0-9a-f]{64}", declared_asset_sha256):
        return False
    if path.is_symlink() or not path.is_file():
        return False
    try:
        if file_sha256(path) != declared_asset_sha256:
            return False
    except OSError:
        return False
    metric_pdf_sha256 = str(metric.get("source_pdf_sha256") or "").lower()
    item_pdf_sha256 = str(item.get("source_pdf_sha256") or "").lower()
    if (
        not re.fullmatch(r"[0-9a-f]{64}", metric_pdf_sha256)
        or not re.fullmatch(r"[0-9a-f]{64}", item_pdf_sha256)
        or metric_pdf_sha256 != item_pdf_sha256
    ):
        return False
    if (
        expected_visual_pdf_sha256
        and metric_pdf_sha256 != str(expected_visual_pdf_sha256).strip().lower()
    ):
        return False
    return True


def _formula_crop_is_usable(
    path: Path,
    formula_crop_diagnostics: dict[int, dict[str, Any]],
    formula_index: int,
    for_context: bool = False,
) -> bool:
    if not path.exists():
        return False

    reason_flags = _formula_source_crop_reasons_for_index(formula_crop_diagnostics, formula_index)
    if not for_context:
        if any(
            flag in {
                "bbox_likely_line_or_separator",
                "source_crop_likely_too_thin",
                "source_crop_likely_useless_for_review",
                "formula_source_crop_too_tiny",
                "standalone_equation_number",
            }
            for flag in reason_flags
        ):
            return False
    # Diagnostics describe the crop that was intended to be written; they do
    # not prove the current file is a decodable image.  Always inspect the
    # bytes on disk so a stale metric cannot make a truncated/corrupt PNG pass
    # the final exact-source gate.
    size = _formula_image_size(path)
    if size is None or not _image_has_visible_content(path):
        return False
    width, height = size

    min_width = FORMULA_SOURCE_CONTEXT_MIN_WIDTH_PX if for_context else FORMULA_SOURCE_MIN_WIDTH_PX
    min_height = (
        FORMULA_SOURCE_CONTEXT_MIN_HEIGHT_PX
        if for_context
        else FORMULA_SOURCE_MIN_HEIGHT_PX
    )
    if width < min_width or height < min_height:
        return False

    aspect = width / max(height, 1)
    if aspect > FORMULA_SOURCE_MAX_ASPECT_RATIO and height < 40:
        return False
    if aspect < FORMULA_SOURCE_MIN_ASPECT_RATIO:
        return False

    return True


def _extract_formula_anchor_indexes(document_html: str, document_markdown: str) -> set[int]:
    anchor_re = re.compile(r"<!--\s*source-formula-anchor:(?P<index>\d+)\s*-->")
    indexes: set[int] = set()
    for match in anchor_re.finditer(document_html):
        indexes.add(int(match.group("index")))
    indexes.update(
        index
        for _start, _end, index in _markdown_source_formula_anchor_spans(
            document_markdown
        )
    )
    return indexes


def _is_standalone_equation_number(value: str) -> bool:
    """Recognize OCR-spaced equation labels while preserving real formula bodies."""

    return bool(
        re.fullmatch(
            r"\s*[\(（]\s*(?:[A-Za-z]\s*\.\s*)?"
            r"\d(?:[\s.]*\d)*\s*[\)）]\s*",
            html.unescape(value),
        )
    )


def _is_formula_number_only(value: str) -> bool:
    raw = html.unescape(str(value or ""))
    return _is_standalone_equation_number(raw) or bool(
        re.fullmatch(r"\s*[+\-−]?\d(?:[\s.]*\d)*\s*", raw)
    )


_FORMULA_CONTEXT_FALLBACK_REASONS = {
    "source_crop_below_minimum_dimensions",
    "formula_source_crop_below_minimum_dimensions",
    "source_crop_too_small",
    "formula_source_crop_too_tiny",
    "bbox_too_thin_for_complex_formula",
    "bbox_crosses_expected_column_boundary",
    "near_page_bottom_context_needed",
    "source_crop_likely_too_thin",
    "source_crop_likely_useless_for_review",
    "formula_text_too_long",
    "repeated_fraction_pattern",
}


def _formula_semantic_body_is_valid(value: str) -> bool:
    raw = html.unescape(str(value or "")).strip()
    if not raw or _is_formula_number_only(raw) or CN_CHAR_RE.search(raw):
        return False
    if re.fullmatch(
        r"(?is)(?:<formula\s*/?>|formula(?:[-_ ]not[-_ ]decoded)?|"
        r"unknown|unavailable|n/?a|none|null|[?_.\-]+)",
        raw,
    ):
        return False
    if re.fullmatch(r"(?is)(?:<loc_\d+>\s*)+", raw):
        return False
    return bool(_formula_content_identity(raw))


def _formula_indexed_candidates(
    output_dir: Path,
    formulas: list[dict[str, Any]],
    formula_crop_diagnostics: list[dict[str, Any]] | None = None,
    suspicious_formula_diagnostics: list[dict[str, Any]] | None = None,
    strict_indexes: set[int] | None = None,
    expected_visual_pdf_sha256: str | None = None,
    formula_by_index: dict[int, dict[str, Any]] | None = None,
    diagnostic_only_indexes: set[int] | None = None,
) -> list[dict[str, Any]]:
    diagnostic_only_indexes = set(diagnostic_only_indexes or set())
    if strict_indexes is not None:
        target_indexes = sorted(strict_indexes)
    elif formulas:
        target_indexes = list(range(1, len(formulas) + 1))
    else:
        target_indexes = []

    crop_diagnostics = _parse_formula_source_crop_diagnostics(
        formula_crop_diagnostics,
        suspicious_formula_diagnostics,
    )
    source_available = [
        int(match.group(1))
        for match in re.finditer(r"formulas/formula_(\d+)\.png", " ".join(
            [path.as_posix() for path in sorted((output_dir / "formulas").glob("formula_*.png"))]
        ))
    ]
    candidates: list[dict[str, Any]] = []
    for index in target_indexes:
        formula = (
            formula_by_index.get(index)
            if formula_by_index is not None
            else (formulas[index - 1] if 1 <= index <= len(formulas) else None)
        )
        source_path = Path(f"formulas/formula_{index}.png")
        context_path = Path(f"formulas/formula_{index}_context.png")
        source_reasons = _formula_source_crop_reasons_for_index(crop_diagnostics, index)
        formula_text = str((formula or {}).get("text") or "")
        standalone_equation_number = _is_standalone_equation_number(formula_text)
        formula_number_only = _is_formula_number_only(formula_text)
        if formula_number_only:
            number_reason = (
                "standalone_equation_number"
                if standalone_equation_number
                else "formula_number_only"
            )
            source_reasons = sorted({*source_reasons, number_reason})
            crop_diagnostics.setdefault(index, {"index": index})["reasons"] = source_reasons
        source_path_abs = output_dir / source_path
        context_path_abs = output_dir / context_path
        selected = None
        selected_path = None
        diagnostic_path = None
        reason = ""
        source_has_visible_ink = bool(
            source_path_abs.exists()
            and _formula_image_size(source_path_abs) is not None
            and _image_has_visible_content(source_path_abs)
        )
        source_has_glyph_geometry = bool(
            source_has_visible_ink
            and _formula_crop_has_glyph_geometry(source_path_abs)
        )
        source_provenance_verified = _formula_crop_provenance_is_verified(
            source_path_abs,
            crop_diagnostics,
            index,
            formula=formula,
            for_context=False,
            expected_visual_pdf_sha256=expected_visual_pdf_sha256,
            allow_raw_identity=index in diagnostic_only_indexes,
        )
        context_provenance_verified = _formula_crop_provenance_is_verified(
            context_path_abs,
            crop_diagnostics,
            index,
            formula=formula,
            for_context=True,
            expected_visual_pdf_sha256=expected_visual_pdf_sha256,
            allow_raw_identity=index in diagnostic_only_indexes,
        )
        context_usable = bool(
            context_provenance_verified
            and
            _formula_crop_is_usable(
                context_path_abs,
                crop_diagnostics,
                index,
                for_context=True,
            )
            and context_path_abs.exists()
        )
        blocking_context_reasons = sorted(
            reason_value
            for reason_value in source_reasons
            if (
                reason_value not in _FORMULA_CONTEXT_FALLBACK_REASONS
                and not (
                    reason_value == "bbox_likely_line_or_separator"
                    and source_has_glyph_geometry
                )
            )
        )
        context_fallback_allowed = bool(
            source_has_visible_ink
            and source_provenance_verified
            and _formula_semantic_body_is_valid(formula_text)
            and not blocking_context_reasons
        )
        if index in diagnostic_only_indexes:
            if context_usable:
                diagnostic_path = context_path
                reason = "verified_dropped_formula_context_appendix"
            elif (
                source_provenance_verified
                and source_path_abs.exists()
                and _formula_image_size(source_path_abs) is not None
                and _image_has_visible_content(source_path_abs)
            ):
                diagnostic_path = source_path
                reason = "verified_dropped_formula_source_appendix"
            else:
                reason = "dropped_formula_provenance_missing_or_unusable"
        elif formula_number_only:
            reason = (
                "standalone_equation_number_has_no_formula_body"
                if standalone_equation_number
                else "formula_number_only_has_no_formula_body"
            )
        elif source_provenance_verified and _formula_crop_is_usable(
            source_path_abs, crop_diagnostics, index, for_context=False
        ) and source_path_abs.exists():
            selected = "source"
            selected_path = source_path
            reason = "source_crop_usable"
        elif context_usable and context_fallback_allowed:
            selected = "context"
            selected_path = context_path
            reason = "visible_direct_source_too_small_using_verified_context"
        elif context_usable:
            diagnostic_path = context_path
            if not source_has_visible_ink:
                reason = "context_diagnostic_only_direct_source_missing_or_blank"
            elif not _formula_semantic_body_is_valid(formula_text):
                reason = "context_diagnostic_only_formula_body_invalid"
            else:
                reason = (
                    "context_diagnostic_only_suspicious_source:"
                    + ",".join(blocking_context_reasons)
                )

        candidates.append(
            {
                "formula_index": index,
                "source_image": source_path.as_posix(),
                "context_image": context_path.as_posix(),
                "selected": selected,
                "selected_image": selected_path.as_posix() if selected_path is not None else None,
                "diagnostic_image": (
                    diagnostic_path.as_posix()
                    if diagnostic_path is not None
                    else None
                ),
                "selection_reason": reason,
                "source_exists": source_path_abs.exists(),
                "context_exists": context_path_abs.exists(),
                "source_provenance_verified": source_provenance_verified,
                "context_provenance_verified": context_provenance_verified,
                "source_reasons": source_reasons,
                "page_no": (
                    (first_prov(formula) or {}).get("page_no")
                    if isinstance(formula, dict)
                    else None
                ),
                "appendix": index in diagnostic_only_indexes,
            }
        )

    candidate_index_set = {int(item["formula_index"]) for item in candidates}
    for index in ([] if strict_indexes is not None else sorted(source_available)):
        if index in candidate_index_set:
            continue
        source_path = Path(f"formulas/formula_{index}.png")
        context_path = Path(f"formulas/formula_{index}_context.png")
        source_reasons = _formula_source_crop_reasons_for_index(crop_diagnostics, index)
        source_path_abs = output_dir / source_path
        context_path_abs = output_dir / context_path
        selected = None
        selected_path = None
        diagnostic_path = None
        reason = ""
        source_provenance_verified = _formula_crop_provenance_is_verified(
            source_path_abs,
            crop_diagnostics,
            index,
            formula=None,
            for_context=False,
            expected_visual_pdf_sha256=expected_visual_pdf_sha256,
        )
        context_provenance_verified = _formula_crop_provenance_is_verified(
            context_path_abs,
            crop_diagnostics,
            index,
            formula=None,
            for_context=True,
            expected_visual_pdf_sha256=expected_visual_pdf_sha256,
        )
        if (
            source_provenance_verified
            and
            _formula_crop_is_usable(
                source_path_abs,
                crop_diagnostics,
                index,
                for_context=False,
            )
            and source_path_abs.exists()
        ):
            selected = "source"
            selected_path = source_path
            reason = "source_crop_usable"
        elif (
            context_provenance_verified
            and
            _formula_crop_is_usable(
                context_path_abs,
                crop_diagnostics,
                index,
                for_context=True,
            )
            and context_path_abs.exists()
        ):
            # No semantic formula record exists for this orphan artifact, so
            # expanded context may be retained only as appendix diagnostics.
            diagnostic_path = context_path
            reason = "context_diagnostic_only_formula_body_missing"

        candidates.append(
            {
                "formula_index": index,
                "source_image": source_path.as_posix(),
                "context_image": context_path.as_posix(),
                "selected": selected,
                "selected_image": selected_path.as_posix() if selected_path is not None else None,
                "diagnostic_image": (
                    diagnostic_path.as_posix()
                    if diagnostic_path is not None
                    else None
                ),
                "selection_reason": reason,
                "source_exists": source_path_abs.exists(),
                "context_exists": context_path_abs.exists(),
                "source_provenance_verified": source_provenance_verified,
                "context_provenance_verified": context_provenance_verified,
                "source_reasons": source_reasons,
                "page_no": None,
                "appendix": True,
            }
        )

    return candidates


def _formula_content_identity(value: str) -> str:
    """Return a strict, presentation-insensitive formula occurrence identity."""

    value = _formula_source_text(html.unescape(value))
    value = re.sub(r"^\s*\$\$|\$\$\s*$", "", value, flags=re.S)
    equation_label = (
        r"(?:[A-Za-z]\s*\.\s*)?(?:\d\s*)+"
        r"(?:\.\s*(?:\d\s*)+)*"
    )
    value = re.sub(
        rf"\\tag\*?\s*\{{\s*\(?\s*{equation_label}\s*\)?\s*\}}\s*$",
        "",
        value,
    )
    value = re.sub(
        r"(?:(?:\\quad|\\qquad|\\,|\\;|\\!)\s*)*"
        rf"\(\s*{equation_label}\s*\)\s*$",
        "",
        value,
    )
    # Array/alignment wrappers and spacing commands are presentation only.  A
    # semantic reflow may flatten the same rows when MathML cannot represent a
    # malformed environment; compare the row contents, not that layout choice.
    value = re.sub(
        r"\\begin\s*\{\s*(?:array|aligned|align|cases|matrix|pmatrix|bmatrix)\s*\}"
        r"(?:\s*\{[^{}]*\})?",
        "",
        value,
    )
    value = re.sub(
        r"\\end\s*\{\s*(?:array|aligned|align|cases|matrix|pmatrix|bmatrix)\s*\}?",
        "",
        value,
    )
    # A malformed array can place the equation label before a duplicate closing
    # environment.  Once layout wrappers are gone, remove that same label at
    # the true semantic tail as well.
    value = re.sub(
        r"(?:(?:\\quad|\\qquad|\\,|\\;|\\!)\s*)*"
        rf"\(\s*{equation_label}\s*\)\s*$",
        "",
        value,
    )
    value = value.replace("&", "")
    value = re.sub(
        r"\\\\|\\(?:quad|qquad|,|;|!|left|right)",
        "",
        value,
    )
    value = re.sub(r"\s+", "", value)
    if value.startswith("{"):
        value = value[1:]
        if value.endswith("}"):
            value = value[:-1]
    return value.translate(
        str.maketrans({"−": "-", "–": "-", "—": "-", "（": "(", "）": ")"})
    )


def _formula_content_identity_sha256(value: str) -> str:
    identity = _formula_content_identity(value)
    if not identity:
        return ""
    return hashlib.sha256(identity.encode("utf-8")).hexdigest()


def _formula_raw_content_sha256(value: str) -> str:
    raw = html.unescape(str(value or ""))
    raw = raw.translate(
        str.maketrans({"−": "-", "–": "-", "—": "-", "（": "(", "）": ")"})
    )
    raw = re.sub(r"\s+", "", raw)
    return hashlib.sha256(raw.encode("utf-8")).hexdigest() if raw else ""


def _html_formula_occurrence_identities(document_html: str) -> dict[int, list[str]]:
    identities: dict[int, list[str]] = {}

    def identity_from_block(block: str) -> str:
        latex = re.search(
            r"<details\b[^>]*>\s*<summary>\s*LaTeX\s*</summary>\s*"
            r"<code>(?P<tex>.*?)</code>\s*</details>",
            block,
            flags=re.S | re.I,
        )
        if latex:
            return _formula_content_identity(latex.group("tex"))
        plain = re.sub(r"<[^>]+>", "", block)
        return _formula_content_identity(plain)

    def add_identity(index: int, identity: str) -> None:
        identities.setdefault(index, []).append(
            identity or "__invalid_formula_occurrence__"
        )

    # Both the normal `data-formula-index` surface and the CJK semantic
    # surface's `data-equation` attribute identify an occurrence.  Keep the
    # block body as the identity source so a matching number alone can never
    # bind the wrong crop.
    for match in re.finditer(
        r"(?P<block><div\b[^>]*\b(?:data-formula-index|data-equation)="
        r"[\"'](?P<index>\d+)[\"']"
        r"[^>]*>.*?</div>)",
        document_html,
        flags=re.S | re.I,
    ):
        add_identity(
            int(match.group("index")),
            identity_from_block(match.group("block")),
        )
    for match in re.finditer(
        r"(?P<block><div\b[^>]*class=[\"'][^\"']*\bformula\b[^\"']*[\"']"
        r"[^>]*>.*?</div>)\s*"
        r"<!--\s*source-formula-anchor:(?P<index>\d+)\s*-->",
        document_html,
        flags=re.S | re.I,
    ):
        index = int(match.group("index"))
        identity = identity_from_block(match.group("block"))
        if identity not in identities.setdefault(index, []):
            identities[index].append(identity or "__invalid_formula_occurrence__")
    return identities


def _markdown_formula_occurrence_identities(document_markdown: str) -> dict[int, list[str]]:
    identities: dict[int, list[str]] = {}
    tagged_spans, _tag_marker_seen = _markdown_tagged_formula_spans(document_markdown)
    tagged_by_span = {(start, end): (index, valid) for start, end, index, valid in tagged_spans}
    for start, end in _markdown_display_math_spans(document_markdown):
        anchor = re.match(
            r"\s*<!--\s*source-formula-anchor:(?P<index>\d+)\s*-->",
            document_markdown[end:],
            flags=re.S,
        )
        if anchor:
            index = int(anchor.group("index"))
            identities.setdefault(index, []).append(
                _formula_content_identity(document_markdown[start:end])
            )
            continue
        tagged = tagged_by_span.get((start, end))
        if tagged is None or tagged[0] is None:
            continue
        index, valid = tagged
        identities.setdefault(index, []).append(
            _formula_content_identity(document_markdown[start:end])
            if valid
            else "__invalid_formula_tag__"
        )
    return identities


def append_formula_source_renderings(
    output_dir: Path,
    formulas: list[dict[str, Any]],
    *,
    formula_crop_diagnostics: list[dict[str, Any]] | None = None,
    suspicious_formula_diagnostics: list[dict[str, Any]] | None = None,
    expected_indexes: set[int] | None = None,
    metadata: dict[str, Any] | None = None,
    status: dict[str, Any] | None = None,
    primary: dict[str, Any] | None = None,
    formula_by_index: dict[int, dict[str, Any]] | None = None,
    diagnostic_only_indexes: set[int] | None = None,
) -> dict[str, Any]:
    """Bind each accepted formula index to a usable crop at its occurrence.

    Appendix-only evidence is diagnostic and deliberately does not satisfy the
    delivery gate.  Exact index sets prevent a wrong crop with the right count
    from being accepted.
    """

    del status  # accepted for call-site/test symmetry; this helper is pure output accounting.
    if metadata:
        formula_crop_diagnostics = (
            formula_crop_diagnostics or metadata.get("formula_crop_diagnostics")
        )
        suspicious_formula_diagnostics = (
            suspicious_formula_diagnostics
            or metadata.get("suspicious_formula_diagnostics")
        )

    html_path = output_dir / "document.html"
    md_path = output_dir / "document.md"
    document_html = html_path.read_text(encoding="utf-8") if html_path.exists() else ""
    document_markdown = md_path.read_text(encoding="utf-8") if md_path.exists() else ""

    document_html = re.sub(
        r"<!--\s*local-ai-lab-formula-evidence:start\s*-->.*?"
        r"<!--\s*local-ai-lab-formula-evidence:end\s*-->",
        "",
        document_html,
        flags=re.S,
    )
    document_html = re.sub(
        r'<details\b[^>]*class="[^"]*\bdocling-formula-source-disclosure\b[^"]*"[^>]*>.*?</details>',
        "",
        document_html,
        flags=re.S | re.I,
    )
    document_html = re.sub(
        r'<figure\b[^>]*class="[^"]*\bdocling-formula-inline-source\b[^"]*"[^>]*>.*?</figure>',
        "",
        document_html,
        flags=re.S | re.I,
    )
    document_html = re.sub(
        r'<section\b[^>]*class="[^"]*\bdocling-formula-source-evidence-appendix\b[^"]*"[^>]*>.*?</section>',
        "",
        document_html,
        flags=re.S | re.I,
    )
    document_markdown, _ = _markdown_sub_outside_code(
        document_markdown,
        r"<!--\s*local-ai-lab-formula-evidence:start\s*-->.*?"
        r"<!--\s*local-ai-lab-formula-evidence:end\s*-->",
        "",
        flags=re.S,
    )
    document_markdown, _ = _markdown_sub_outside_code(
        document_markdown,
        r"\n?<!--\s*source-formula-visual:\d+\s*-->\s*\n"
        r"<details\b[^>]*class=[\"'][^\"']*\bdocling-formula-source-disclosure\b[^\"']*[\"'][^>]*>.*?</details>\s*",
        "\n",
        flags=re.I | re.S,
    )
    document_markdown, _ = _markdown_sub_outside_code(
        document_markdown,
        r"\n?<!--\s*source-formula-visual:\d+\s*-->\s*\n"
        r"!?\[[^\n]*Formula[^\n]*\]\(formulas/formula_\d+(?:_context)?\.png\)\s*",
        "\n",
        flags=re.I,
    )

    html_anchor_occurrences = [
        int(value)
        for value in re.findall(r"source-formula-anchor:(\d+)", document_html)
    ]
    html_data_index_occurrences = [
        int(value)
        for value in re.findall(
            r"<div\b[^>]*\bdata-formula-index=[\"'](\d+)[\"']",
            document_html,
            flags=re.I,
        )
    ]
    html_data_equation_occurrences = [
        int(value)
        for value in re.findall(
            r"<div\b[^>]*\bdata-equation=[\"'](\d+)[\"']",
            document_html,
            flags=re.I,
        )
    ]
    markdown_anchor_spans = _markdown_source_formula_anchor_spans(
        document_markdown
    )
    markdown_tagged_spans, markdown_tag_marker_seen = _markdown_tagged_formula_spans(
        document_markdown
    )
    markdown_anchor_occurrences = [index for _start, _end, index in markdown_anchor_spans]
    html_anchor_indexes = set(html_anchor_occurrences)
    markdown_anchor_indexes = set(markdown_anchor_occurrences)
    html_occurrence_counts = {
        index: max(
            html_data_index_occurrences.count(index),
            html_data_equation_occurrences.count(index),
            html_anchor_occurrences.count(index),
        )
        for index in (
            set(html_data_index_occurrences)
            | set(html_data_equation_occurrences)
            | html_anchor_indexes
        )
    }
    if expected_indexes is None:
        anchored = (
            html_anchor_indexes
            | set(html_data_index_occurrences)
            | set(html_data_equation_occurrences)
            | markdown_anchor_indexes
            | {
                int(index)
                for _start, _end, index, valid in markdown_tagged_spans
                if valid and index is not None
            }
        )
        expected_indexes = anchored or set(range(1, len(formulas) + 1))
    expected_indexes = {int(index) for index in expected_indexes if int(index) > 0}
    candidates = _formula_indexed_candidates(
        output_dir,
        formulas,
        formula_crop_diagnostics=formula_crop_diagnostics,
        suspicious_formula_diagnostics=suspicious_formula_diagnostics,
        strict_indexes=expected_indexes,
        expected_visual_pdf_sha256=(
            str(metadata.get("visual_evidence_input_sha256") or "") or None
            if metadata is not None
            else None
        ),
        formula_by_index=formula_by_index,
        diagnostic_only_indexes=diagnostic_only_indexes,
    )
    candidate_by_index = {
        int(candidate["formula_index"]): candidate for candidate in candidates
    }
    identity_formula_by_index = (
        formula_by_index
        if formula_by_index is not None
        else {index: formula for index, formula in enumerate(formulas, start=1)}
    )
    raw_semantic_tex_by_index = (
        primary.get("semantic_formula_tex_by_index")
        if isinstance(primary, dict)
        else None
    )
    semantic_tex_by_index: dict[int, str] = {}
    if isinstance(raw_semantic_tex_by_index, dict):
        for raw_index, raw_tex in raw_semantic_tex_by_index.items():
            try:
                normalized_index = int(raw_index)
            except (TypeError, ValueError):
                continue
            if normalized_index > 0 and isinstance(raw_tex, str) and raw_tex.strip():
                semantic_tex_by_index[normalized_index] = raw_tex
    expected_identity_by_index = {
        index: _formula_content_identity(
            semantic_tex_by_index.get(index)
            or str(formula.get("text") or "")
        )
        for index, formula in identity_formula_by_index.items()
        if index not in set(diagnostic_only_indexes or set())
    }
    html_identity_by_index = _html_formula_occurrence_identities(document_html)
    markdown_identity_by_index = _markdown_formula_occurrence_identities(
        document_markdown
    )
    # Prefer identity-derived counts so a block carrying both attributes (or
    # an anchor comment) is not double-counted, while duplicate blocks remain
    # visible and fail the exact-one occurrence check.
    html_occurrence_counts = {
        index: max(
            len(html_identity_by_index.get(index, [])),
            html_anchor_occurrences.count(index),
        )
        for index in (
            set(html_data_index_occurrences)
            | set(html_data_equation_occurrences)
            | html_anchor_indexes
        )
    }
    html_identity_mismatch_indexes: set[int] = set()
    markdown_identity_mismatch_indexes: set[int] = set()

    def occurrence_identity_matches(
        formula_index: int,
        actual_by_index: dict[int, list[str]],
    ) -> bool:
        expected = expected_identity_by_index.get(formula_index)
        actual = [value for value in actual_by_index.get(formula_index, []) if value]
        # Diagnostic-only raw drop indexes have no primary formula identity and
        # are never permitted to satisfy occurrence coverage.
        return bool(expected and len(actual) == 1 and actual[0] == expected)

    def html_figure(candidate: dict[str, Any], *, occurrence: bool) -> str:
        index = int(candidate["formula_index"])
        image_path = html.escape(
            str(
                candidate.get("selected_image")
                or candidate.get("diagnostic_image")
                or ""
            ),
            quote=True,
        )
        label = (
            "exact PDF formula at this occurrence"
            if occurrence
            else "formula review evidence"
        )
        figure = (
            '<figure class="docling-formula-inline-source" '
            f'data-formula-index="{index}" data-formula-evidence="'
            f'{html.escape(str(candidate.get("selected") or "diagnostic-only"), quote=True)}" '
            'style="margin:.35rem auto 1rem;text-align:center">'
            f'<img src="{image_path}" '
            'style="max-width:100%;height:auto" '
            f'alt="Formula {index} {label}">'
            f'<figcaption>Formula {index} — exact rendering from the original PDF'
            + (
                " (expanded context crop)"
                if candidate.get("selected") == "context"
                else ""
            )
            + "</figcaption></figure>"
        )
        return _source_disclosure_html(
            figure,
            summary="查看公式原始裁剪",
            extra_class="docling-formula-source-disclosure",
            attrs=f' data-formula-index="{index}"',
        )

    html_covered_indexes: set[int] = set()
    html_appendix_indexes: set[int] = set()
    if candidates and html_path.exists():
        def replace_html_anchor(match: re.Match[str]) -> str:
            formula_index = int(match.group("index"))
            candidate = candidate_by_index.get(formula_index)
            if candidate is None or not candidate.get("selected_image"):
                return match.group(0)
            if not occurrence_identity_matches(
                formula_index, html_identity_by_index
            ):
                html_identity_mismatch_indexes.add(formula_index)
                return match.group(0)
            html_covered_indexes.add(formula_index)
            return match.group(0) + "\n" + html_figure(candidate, occurrence=True)

        document_html = re.sub(
            r"<!--\s*source-formula-anchor:(?P<index>\d+)\s*-->",
            replace_html_anchor,
            document_html,
        )

        # CJK preserve mode has no semantic anchor comments, but the retained
        # blocks have stable data-formula-index attributes.
        for formula_index in sorted(expected_indexes - html_covered_indexes):
            candidate = candidate_by_index.get(formula_index)
            if candidate is None or not candidate.get("selected_image"):
                continue
            if not occurrence_identity_matches(
                formula_index, html_identity_by_index
            ):
                html_identity_mismatch_indexes.add(formula_index)
                continue
            block_re = re.compile(
                rf"(<div\b[^>]*\b(?:data-formula-index|data-equation)="
                rf"[\"']{formula_index}[\"'][^>]*>)",
                flags=re.I,
            )
            document_html, replacement_count = block_re.subn(
                lambda match, candidate=candidate: (
                    match.group(1) + "\n" + html_figure(candidate, occurrence=True)
                ),
                document_html,
                count=1,
            )
            if replacement_count:
                html_covered_indexes.add(formula_index)

        unmatched_candidates = [
            candidate
            for candidate in candidates
            if (
                candidate.get("selected_image")
                or candidate.get("diagnostic_image")
            )
            and int(candidate["formula_index"]) not in html_covered_indexes
        ]
        if unmatched_candidates:
            html_appendix_indexes = {
                int(candidate["formula_index"]) for candidate in unmatched_candidates
            }
            figures = "\n".join(
                html_figure(candidate, occurrence=False)
                for candidate in unmatched_candidates
            )
            appendix = (
                "<!-- local-ai-lab-formula-evidence:start -->"
                '<section class="docling-formula-source-evidence-appendix">'
                "<h2>Unmatched original formula renderings</h2>"
                "<p>These crops are retained for diagnosis, but unmatched appendix "
                "evidence does not satisfy the delivery gate.</p>"
                f"{figures}</section>"
                "<!-- local-ai-lab-formula-evidence:end -->"
            )
            body_end = re.search(r"</body>", document_html, flags=re.I)
            if body_end:
                document_html = (
                    document_html[: body_end.start()]
                    + appendix
                    + document_html[body_end.start() :]
                )
            else:
                document_html += appendix
        html_path.write_text(document_html, encoding="utf-8")

    markdown_covered_indexes: set[int] = set()
    markdown_appendix_indexes: set[int] = set()
    if candidates and md_path.exists():
        markdown_anchor_edits: list[tuple[int, int, str]] = []
        for start, end, formula_index in markdown_anchor_spans:
            candidate = candidate_by_index.get(formula_index)
            if candidate is None or not candidate.get("selected_image"):
                continue
            if not occurrence_identity_matches(
                formula_index, markdown_identity_by_index
            ):
                markdown_identity_mismatch_indexes.add(formula_index)
                continue
            markdown_covered_indexes.add(formula_index)
            markdown_anchor_edits.append(
                (
                    start,
                    end,
                    document_markdown[start:end]
                    + "\n\n"
                    + f"<!-- source-formula-visual:{formula_index} -->\n"
                    + _source_disclosure_markdown(
                        _markdown_image(
                            f"Formula {formula_index} — exact PDF rendering",
                            candidate["selected_image"],
                        ),
                        summary="查看公式原始裁剪",
                        extra_class="docling-formula-source-disclosure",
                    ),
                )
            )
        for start, end, replacement in reversed(markdown_anchor_edits):
            document_markdown = (
                document_markdown[:start]
                + replacement
                + document_markdown[end:]
            )

        # The CJK semantic surface may carry an explicit ``\tag{N}`` instead
        # of generated anchor comments.  Bind by that identity first; never
        # fall back to display order when a tag marker is malformed or
        # duplicated.
        if expected_indexes and not markdown_anchor_indexes and markdown_tag_marker_seen:
            tagged_edits: list[tuple[int, int, str]] = []
            for start, end, formula_index, valid in markdown_tagged_spans:
                if formula_index is None or formula_index not in expected_indexes:
                    continue
                candidate = candidate_by_index.get(formula_index)
                if candidate is None or not candidate.get("selected_image"):
                    continue
                if (
                    not valid
                    or not occurrence_identity_matches(
                        formula_index, markdown_identity_by_index
                    )
                ):
                    markdown_identity_mismatch_indexes.add(formula_index)
                    continue
                # A duplicate tag produces multiple entries in the inventory;
                # occurrence_identity_matches() above then fails closed.
                markdown_covered_indexes.add(formula_index)
                block = document_markdown[start:end]
                tagged_edits.append(
                    (
                        start,
                        end,
                        block
                        + f"\n<!-- source-formula-visual:{formula_index} -->\n\n"
                        + _source_disclosure_markdown(
                            _markdown_image(
                                f"Formula {formula_index} — exact PDF rendering",
                                candidate["selected_image"],
                            ),
                            summary="查看公式原始裁剪",
                            extra_class="docling-formula-source-disclosure",
                        ),
                    )
                )
            for start, end, replacement in reversed(tagged_edits):
                document_markdown = (
                    document_markdown[:start]
                    + replacement
                    + document_markdown[end:]
                )

        # Legacy CJK output without either anchors or explicit tags keeps its
        # stable positional fallback.  Presence of a malformed tag marker
        # intentionally bypasses this branch so it cannot silently bind wrong.
        elif expected_indexes and not markdown_anchor_indexes and not markdown_tag_marker_seen:
            display_spans = _markdown_display_math_spans(document_markdown)
            display_edits: list[tuple[int, int, str]] = []
            for formula_index, (start, end) in zip(
                sorted(expected_indexes - set(diagnostic_only_indexes or set())),
                display_spans,
            ):
                block = document_markdown[start:end]
                actual_identity = _formula_content_identity(block)
                candidate = candidate_by_index.get(formula_index)
                if candidate is None or not candidate.get("selected_image"):
                    continue
                if (
                    not expected_identity_by_index.get(formula_index)
                    or actual_identity != expected_identity_by_index[formula_index]
                ):
                    markdown_identity_mismatch_indexes.add(formula_index)
                    continue
                markdown_covered_indexes.add(formula_index)
                display_edits.append(
                    (
                        start,
                        end,
                        block
                        + f"\n<!-- source-formula-visual:{formula_index} -->\n\n"
                        + _source_disclosure_markdown(
                            _markdown_image(
                                f"Formula {formula_index} — exact PDF rendering",
                                candidate["selected_image"],
                            ),
                            summary="查看公式原始裁剪",
                            extra_class="docling-formula-source-disclosure",
                        ),
                    )
                )
            for start, end, replacement in reversed(display_edits):
                document_markdown = (
                    document_markdown[:start]
                    + replacement
                    + document_markdown[end:]
                )

        unmatched_candidates = [
            candidate
            for candidate in candidates
            if (
                candidate.get("selected_image")
                or candidate.get("diagnostic_image")
            )
            and int(candidate["formula_index"]) not in markdown_covered_indexes
        ]
        if unmatched_candidates:
            markdown_appendix_indexes = {
                int(candidate["formula_index"]) for candidate in unmatched_candidates
            }
            parts = [
                document_markdown.rstrip(),
                "",
                "<!-- local-ai-lab-formula-evidence:start -->",
                "## Unmatched original formula renderings",
                "",
                (
                    "These crops are retained for diagnosis, but unmatched appendix "
                    "evidence does not satisfy the delivery gate."
                ),
            ]
            for candidate in unmatched_candidates:
                parts.extend(
                    [
                        "",
                        f'<!-- source-formula-appendix:{candidate["formula_index"]} -->',
                        _source_disclosure_markdown(
                            _markdown_image(
                                f'Formula {candidate["formula_index"]} — source rendering',
                                candidate.get("selected_image")
                                or candidate.get("diagnostic_image"),
                            ),
                            summary="查看公式原始裁剪",
                            extra_class="docling-formula-source-disclosure",
                        ),
                    ]
                )
            parts.append("<!-- local-ai-lab-formula-evidence:end -->")
            document_markdown = "\n".join(parts) + "\n"
        md_path.write_text(document_markdown, encoding="utf-8")

    missing_candidate_indexes = {
        int(candidate["formula_index"])
        for candidate in candidates
        if not candidate.get("selected_image")
    }

    return {
        "candidate_count": len(candidates),
        "html_applied_count": len(html_covered_indexes) + len(html_appendix_indexes),
        "markdown_applied_count": len(markdown_covered_indexes) + len(markdown_appendix_indexes),
        "html_inline_count": len(html_covered_indexes),
        "markdown_inline_count": len(markdown_covered_indexes),
        "html_appendix_count": len(html_appendix_indexes),
        "markdown_appendix_count": len(markdown_appendix_indexes),
        "expected_indexes": sorted(expected_indexes),
        "html_covered_indexes": sorted(html_covered_indexes),
        "markdown_covered_indexes": sorted(markdown_covered_indexes),
        "html_appendix_indexes": sorted(html_appendix_indexes),
        "markdown_appendix_indexes": sorted(markdown_appendix_indexes),
        "missing_candidate_indexes": sorted(missing_candidate_indexes),
        "missing_html_indexes": sorted(expected_indexes - html_covered_indexes),
        "missing_markdown_indexes": sorted(
            expected_indexes - markdown_covered_indexes
        ),
        "html_identity_mismatch_indexes": sorted(html_identity_mismatch_indexes),
        "markdown_identity_mismatch_indexes": sorted(
            markdown_identity_mismatch_indexes
        ),
        "duplicate_html_anchor_indexes": sorted(
            {
                index
                for index in html_anchor_occurrences
                if html_anchor_occurrences.count(index) > 1
            }
        ),
        "duplicate_html_occurrence_indexes": sorted(
            index for index, count in html_occurrence_counts.items() if count > 1
        ),
        "duplicate_markdown_anchor_indexes": sorted(
            {
                index
                for index in markdown_anchor_occurrences
                if markdown_anchor_occurrences.count(index) > 1
            }
        ),
        "duplicate_markdown_tag_indexes": sorted(
            {
                int(index)
                for _start, _end, index, _valid in markdown_tagged_spans
                if index is not None
                and sum(
                    1
                    for _tag_start, _tag_end, tag_index, _tag_valid in markdown_tagged_spans
                    if tag_index == index
                )
                > 1
            }
        ),
        "html_formula_occurrence_counts": {
            str(index): count for index, count in sorted(html_occurrence_counts.items())
        },
        "markdown_display_formula_count": len(
            _markdown_display_math_spans(document_markdown)
        ),
        "candidates": candidates,
    }


def _positive_page_number(value: Any) -> int | None:
    if isinstance(value, bool):
        return None
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        return None
    return parsed if parsed > 0 and str(value).strip() == str(parsed) else None


def _document_page_size_inventory(document_json: Any) -> dict[str, Any]:
    """Merge top-level/chunk page sizes and retain local-to-global aliases."""

    page_records: dict[int, dict[str, Any]] = {}
    ambiguous_pages: set[int] = set()
    aliases: dict[tuple[int, int], int] = {}
    top_level_pages: set[int] = set()
    parts: list[dict[str, Any]] = []

    def normalized_pages(document: Any) -> dict[int, dict[str, Any]]:
        raw_pages = document.get("pages") if isinstance(document, dict) else None
        items: list[tuple[Any, Any]]
        if isinstance(raw_pages, dict):
            items = list(raw_pages.items())
        elif isinstance(raw_pages, list):
            items = list(enumerate(raw_pages, start=1))
        else:
            return {}
        normalized: dict[int, dict[str, Any]] = {}
        for raw_page_no, record in items:
            page_no = _positive_page_number(raw_page_no)
            if page_no is None or not isinstance(record, dict):
                continue
            size = record.get("size") or {}
            try:
                width = float(size.get("width") or 0.0)
                height = float(size.get("height") or 0.0)
            except (TypeError, ValueError):
                continue
            if width <= 0.0 or height <= 0.0:
                continue
            normalized[page_no] = record
        return normalized

    def add_page(global_page_no: int, record: dict[str, Any]) -> None:
        if global_page_no in ambiguous_pages:
            return
        existing = page_records.get(global_page_no)
        if existing is None:
            page_records[global_page_no] = record
            return
        existing_size = existing.get("size") or {}
        incoming_size = record.get("size") or {}
        if (
            float(existing_size.get("width") or 0.0)
            != float(incoming_size.get("width") or 0.0)
            or float(existing_size.get("height") or 0.0)
            != float(incoming_size.get("height") or 0.0)
        ):
            page_records.pop(global_page_no, None)
            ambiguous_pages.add(global_page_no)

    direct_pages = normalized_pages(document_json)
    for page_no, record in direct_pages.items():
        add_page(page_no, record)
        top_level_pages.add(page_no)

    raw_chunks = (
        document_json.get("chunks") if isinstance(document_json, dict) else None
    )
    if isinstance(raw_chunks, list) and raw_chunks:
        chunk_entries: list[tuple[tuple[int, int], int, dict[str, Any], Any]] = []
        for original_index, chunk in enumerate(raw_chunks):
            if not isinstance(chunk, dict) or not isinstance(chunk.get("document"), dict):
                continue
            page_range_value = chunk.get("page_range")
            start = (
                _positive_page_number(page_range_value[0])
                if isinstance(page_range_value, list) and page_range_value
                else None
            )
            end = (
                _positive_page_number(page_range_value[1])
                if isinstance(page_range_value, list) and len(page_range_value) > 1
                else start
            )
            sort_key = (
                start if start is not None else original_index + 1,
                end if end is not None else -1,
            )
            chunk_entries.append(
                (sort_key, original_index, chunk["document"], page_range_value)
            )
        for part_index, (_key, _original, part, page_range_value) in enumerate(
            sorted(chunk_entries, key=lambda item: (item[0], item[1]))
        ):
            part_pages = normalized_pages(part)
            start = (
                _positive_page_number(page_range_value[0])
                if isinstance(page_range_value, list) and page_range_value
                else None
            )
            end = (
                _positive_page_number(page_range_value[1])
                if isinstance(page_range_value, list) and len(page_range_value) > 1
                else start
            )
            length = (
                end - start + 1
                if start is not None and end is not None and end >= start
                else None
            )
            local_numbering = bool(
                start is not None
                and length is not None
                and part_pages
                and all(1 <= page_no <= length for page_no in part_pages)
                and (start == 1 or 1 in part_pages or any(page_no < start for page_no in part_pages))
            )
            for raw_page_no, record in part_pages.items():
                if local_numbering and start is not None:
                    global_page_no = start + raw_page_no - 1
                elif start is not None and end is not None and start <= raw_page_no <= end:
                    global_page_no = raw_page_no
                elif start is not None and length is not None and 1 <= raw_page_no <= length:
                    global_page_no = start + raw_page_no - 1
                else:
                    global_page_no = raw_page_no
                aliases[(part_index, raw_page_no)] = global_page_no
                add_page(global_page_no, record)
            parts.append(
                {
                    "part_index": part_index,
                    "document": part,
                    "page_range": page_range_value,
                }
            )
    else:
        parts.append(
            {"part_index": None, "document": document_json, "page_range": None}
        )

    return {
        "page_records": page_records,
        "aliases": aliases,
        "top_level_pages": top_level_pages,
        "parts": parts,
        "ambiguous_pages": sorted(ambiguous_pages),
    }


def _resolve_document_page_number(
    inventory: dict[str, Any],
    raw_page_no: Any,
    *,
    part_index: Any = None,
) -> int | None:
    page_no = _positive_page_number(raw_page_no)
    if page_no is None:
        return None
    normalized_part = (
        part_index
        if isinstance(part_index, int) and not isinstance(part_index, bool)
        else None
    )
    aliases = inventory.get("aliases") or {}
    if normalized_part is not None and (normalized_part, page_no) in aliases:
        return int(aliases[(normalized_part, page_no)])
    page_records = inventory.get("page_records") or {}
    if page_no in (inventory.get("top_level_pages") or set()):
        return page_no if page_no in page_records else None
    if normalized_part is not None:
        part = next(
            (
                item
                for item in (inventory.get("parts") or [])
                if item.get("part_index") == normalized_part
            ),
            None,
        )
        page_range_value = (part or {}).get("page_range")
        if (
            isinstance(page_range_value, list)
            and page_range_value
            and (start := _positive_page_number(page_range_value[0])) is not None
            and len(page_range_value) > 1
            and (end := _positive_page_number(page_range_value[1])) is not None
            and start <= page_no <= end
            and page_no in page_records
        ):
            return page_no
        return None
    matching_aliases = {
        int(global_page)
        for (alias_part, alias_page), global_page in aliases.items()
        if alias_part is not None and alias_page == page_no
    }
    if len(matching_aliases) == 1:
        resolved = next(iter(matching_aliases))
        return resolved if resolved in page_records else None
    return page_no if page_no in page_records and not aliases else None


def _document_with_resolved_page_provenance(document_json: Any) -> Any:
    """Copy a document and translate chunk-local provenance to global pages."""

    if not isinstance(document_json, dict):
        return document_json
    normalized = copy.deepcopy(document_json)
    inventory = _document_page_size_inventory(normalized)
    for part in inventory.get("parts") or []:
        part_index = part.get("part_index")
        for node in iter_nodes(part.get("document")):
            if not isinstance(node, dict):
                continue
            if part_index is not None and any(
                key in node for key in ("label", "self_ref", "prov")
            ):
                node["_local_ai_lab_chunk_part_index"] = part_index
            provs = node.get("prov")
            if not isinstance(provs, list):
                continue
            for prov in provs:
                if not isinstance(prov, dict) or "page_no" not in prov:
                    continue
                raw_page_no = prov.get("page_no")
                resolved_page_no = _resolve_document_page_number(
                    inventory,
                    raw_page_no,
                    part_index=part_index,
                )
                # Plain non-chunk documents historically crop directly from
                # global provenance even when their optional page-size map is
                # absent.  Preserve that compatibility; chunk provenance must
                # resolve through the declared range/page inventory or fail
                # closed instead of silently sampling the wrong physical page.
                if resolved_page_no is None and part_index is None:
                    resolved_page_no = _positive_page_number(raw_page_no)
                prov["page_no"] = resolved_page_no
    if (
        normalized.get("schema_name") == "local_ai_lab_docling_serve_chunked"
        and isinstance(normalized.get("chunks"), list)
    ):
        # Semantic reflow assigns raw formula/table offsets in page-range order.
        # Keep evidence extraction in that exact order so anchor indexes cannot
        # bind a late chunk's crop to an early chunk's formula body.
        indexed_chunks = list(enumerate(normalized["chunks"]))

        def chunk_sort_key(item: tuple[int, Any]) -> tuple[int, int, int]:
            original_index, chunk = item
            page_range = chunk.get("page_range") if isinstance(chunk, dict) else None
            start = (
                _positive_page_number(page_range[0])
                if isinstance(page_range, list) and page_range
                else None
            )
            end = (
                _positive_page_number(page_range[1])
                if isinstance(page_range, list) and len(page_range) > 1
                else start
            )
            return (
                start if start is not None else original_index + 1,
                end if end is not None else -1,
                original_index,
            )

        normalized["chunks"] = [
            chunk for _index, chunk in sorted(indexed_chunks, key=chunk_sort_key)
        ]
    return normalized


def _inline_source_clip_geometry(
    clip: Any,
    bbox: Any,
    *,
    page_width: float,
    page_height: float,
    image_width: int,
    image_height: int,
) -> tuple[dict[str, Any] | None, tuple[int, int, int, int] | None, str | None]:
    """Validate an inline paragraph clip before intersecting its raster crop."""

    if clip is None:
        return None, None, None
    if not isinstance(clip, dict) or not isinstance(bbox, dict):
        return None, None, "inline_crop_clip_invalid"
    origin = _bbox_explicit_coord_origin(bbox)
    clip_origin = _bbox_explicit_coord_origin(clip)
    if origin is None or clip_origin != origin:
        return None, None, "inline_crop_clip_origin_mismatch"
    try:
        values = {
            key: float(clip[key])
            for key in ("l", "r", "t", "b")
        }
        node_values = {
            key: float(bbox[key])
            for key in ("l", "r", "t", "b")
        }
    except (KeyError, TypeError, ValueError):
        return None, None, "inline_crop_clip_invalid"
    if any(not math.isfinite(value) for value in values.values()) or any(
        not math.isfinite(value) for value in node_values.values()
    ):
        return None, None, "inline_crop_clip_invalid"
    if (
        values["r"] <= values["l"]
        or max(values["t"], values["b"]) <= min(values["t"], values["b"])
        or values["l"] < 0.0
        or values["r"] > page_width
        or min(values["t"], values["b"]) < 0.0
        or max(values["t"], values["b"]) > page_height
    ):
        return None, None, "inline_crop_clip_out_of_page_bounds"
    if (
        values["l"] > node_values["l"]
        or values["r"] < node_values["r"]
        or min(values["t"], values["b"])
        > min(node_values["t"], node_values["b"])
        or max(values["t"], values["b"])
        < max(node_values["t"], node_values["b"])
    ):
        return None, None, "inline_crop_clip_excludes_bbox"
    normalized = {**values, "coord_origin": origin}
    clip_box = _bbox_pixel_crop_box(
        normalized,
        page_width=page_width,
        page_height=page_height,
        image_width=image_width,
        image_height=image_height,
        padding=0,
    )
    if clip_box is None:
        return None, None, "inline_crop_clip_invalid"
    return normalized, clip_box, None


def append_inline_math_source_renderings(
    output_dir: Path,
    document_json: dict[str, Any],
    regions: list[dict[str, Any]],
) -> dict[str, Any]:
    """Attach a source-PDF crop to every detected inline-math occurrence."""

    try:
        from PIL import Image
    except Exception as exc:
        return {
            "candidate_count": len(regions),
            "expected_anchors": sorted(
                str(region.get("anchor"))
                for region in regions
                if region.get("anchor")
            ),
            "html_covered_anchors": [],
            "markdown_covered_anchors": [],
            "missing_crop_anchors": sorted(
                str(region.get("anchor"))
                for region in regions
                if region.get("anchor")
            ),
            "source_images": [],
            "missing_crop_diagnostics": [],
            "error": f"Pillow unavailable: {exc}",
        }

    page_inventory = _document_page_size_inventory(document_json)
    page_records = page_inventory["page_records"]
    inline_dir = output_dir / "inline_math"
    candidates: list[dict[str, Any]] = []
    missing_crop_anchors: set[str] = set()
    missing_crop_diagnostics: list[dict[str, Any]] = []
    expected_anchors = {
        str(region.get("anchor")) for region in regions if region.get("anchor")
    }
    seen_anchors: set[str] = set()
    for ordinal, region in enumerate(regions, start=1):
        anchor = str(region.get("anchor") or "")
        if not anchor or anchor in seen_anchors:
            continue
        seen_anchors.add(anchor)
        raw_page_no = region.get("page_no")
        part_index = region.get("part_index")
        page_no = _resolve_document_page_number(
            page_inventory,
            raw_page_no,
            part_index=part_index,
        )
        bbox = region.get("bbox") or {}
        page_record = page_records.get(page_no) or {}
        page_size = page_record.get("size") or {}
        page_width = float(page_size.get("width") or 0.0)
        page_height = float(page_size.get("height") or 0.0)
        page_image = output_dir / "pages" / f"page_{page_no}.png"
        if (
            not page_no
            or not page_image.exists()
            or not page_width
            or not page_height
            or not all(key in bbox for key in ("l", "r", "t", "b"))
        ):
            missing_crop_anchors.add(anchor)
            continue
        safe_anchor = re.sub(r"[^A-Za-z0-9_.-]+", "-", anchor).strip("-")
        relative_path = Path("inline_math") / f"{ordinal:04d}-{safe_anchor}.png"
        try:
            with Image.open(page_image) as image:
                crop_box = _bbox_pixel_crop_box(
                    bbox,
                    page_width=page_width,
                    page_height=page_height,
                    image_width=image.width,
                    image_height=image.height,
                    padding=18,
                )
                if crop_box is None:
                    missing_crop_anchors.add(anchor)
                    continue
                clip_bounds, clip_box, clip_reason = _inline_source_clip_geometry(
                    region.get("crop_clip_bounds"),
                    bbox,
                    page_width=page_width,
                    page_height=page_height,
                    image_width=image.width,
                    image_height=image.height,
                )
                if clip_reason:
                    missing_crop_anchors.add(anchor)
                    missing_crop_diagnostics.append(
                        {"anchor": anchor, "reason": clip_reason}
                    )
                    continue
                if clip_box is not None:
                    crop_box = (
                        max(crop_box[0], clip_box[0]),
                        max(crop_box[1], clip_box[1]),
                        min(crop_box[2], clip_box[2]),
                        min(crop_box[3], clip_box[3]),
                    )
                    if crop_box[2] <= crop_box[0] or crop_box[3] <= crop_box[1]:
                        missing_crop_anchors.add(anchor)
                        missing_crop_diagnostics.append(
                            {
                                "anchor": anchor,
                                "reason": "inline_crop_clip_no_overlap",
                            }
                        )
                        continue
                inline_dir.mkdir(exist_ok=True)
                image.crop(crop_box).save(output_dir / relative_path)
        except Exception:
            missing_crop_anchors.add(anchor)
            continue
        crop_path = output_dir / relative_path
        if not _image_has_visible_content(crop_path):
            try:
                crop_path.unlink()
            except OSError:
                pass
            missing_crop_anchors.add(anchor)
            continue
        candidates.append(
            {
                "anchor": anchor,
                "image": relative_path.as_posix(),
                "page_no": page_no,
                "source_page_no": raw_page_no,
                "part_index": part_index,
                "bbox": bbox,
                "source_text": str(region.get("source_text") or "")[:1000],
                "unresolved": bool(region.get("unresolved")),
                "crop_clip_bounds": clip_bounds,
                "pixel_box": list(crop_box),
                "page_size": {"width": page_width, "height": page_height},
                "page_image_size": {
                    "width": image.width,
                    "height": image.height,
                },
                "page_image_sha256": file_sha256(page_image),
                "asset_sha256": file_sha256(crop_path),
            }
        )

    html_path = output_dir / "document.html"
    html_text = html_path.read_text(encoding="utf-8") if html_path.exists() else ""
    html_text = re.sub(
        r'<details\b[^>]*class="[^"]*\bdocling-inline-math-source\b[^"]*"[^>]*>.*?</details>',
        "",
        html_text,
        flags=re.S | re.I,
    )
    html_marker_occurrences = re.findall(
        r"source-inline-math-anchor:([^\s>]+)", html_text
    )
    html_covered: set[str] = set()
    for candidate in candidates:
        anchor = str(candidate["anchor"])
        image_path = html.escape(str(candidate["image"]), quote=True)
        marker_re = re.compile(
            rf"<!--\s*source-inline-math-anchor:{re.escape(anchor)}\s*-->"
        )
        unresolved = bool(candidate.get("unresolved"))
        # Source evidence is deliberately quiet by default, including when the
        # machine transcription is incomplete.  The warning remains inside the
        # disclosure so reviewers can expand it on demand.
        disclosure = ""
        warning = (
            '<p><strong>Machine transcription incomplete.</strong> '
            "Use this exact PDF notation as the authoritative reading.</p>"
            if unresolved
            else ""
        )
        figure = (
            f'<details{disclosure} class="docling-source-disclosure docling-inline-math-source" '
            f'data-inline-math-anchor="{html.escape(anchor, quote=True)}" '
            'style="margin:.25rem 0 .75rem">'
            "<summary>Compare inline notation with the original PDF</summary>"
            f"{warning}"
            f'<img src="{image_path}" '
            'style="max-width:100%;height:auto" '
            'alt="Exact inline mathematical notation from the original PDF">'
            "</details>"
        )
        html_text, count = marker_re.subn(
            lambda match, figure=figure: match.group(0) + "\n" + figure,
            html_text,
            count=1,
        )
        if count:
            html_covered.add(anchor)
    if html_path.exists():
        html_path.write_text(html_text, encoding="utf-8")

    md_path = output_dir / "document.md"
    markdown_text = md_path.read_text(encoding="utf-8") if md_path.exists() else ""
    markdown_text, _ = _markdown_sub_outside_code(
        markdown_text,
        r"\n?<!--\s*source-inline-math-visual:[^\s>]+\s*-->.*?</details>\s*",
        "\n",
        flags=re.S | re.I,
    )
    markdown_marker_occurrences = re.findall(
        r"source-inline-math-anchor:([^\s>]+)", markdown_text
    )
    markdown_covered: set[str] = set()
    for candidate in candidates:
        anchor = str(candidate["anchor"])
        marker_re = re.compile(
            rf"<!--\s*source-inline-math-anchor:{re.escape(anchor)}\s*-->"
        )
        unresolved = bool(candidate.get("unresolved"))
        disclosure = ""
        warning = (
            "\n\n**Machine transcription incomplete. Use the exact PDF notation below.**"
            if unresolved
            else ""
        )
        evidence = (
            f"<!-- source-inline-math-visual:{anchor} -->\n\n"
            f'<details{disclosure} class="docling-source-disclosure docling-inline-math-source"><summary>'
            f"Compare inline notation with the original PDF</summary>{warning}\n\n"
            + _markdown_image(
                "Inline notation — exact PDF rendering",
                candidate["image"],
            )
            + "\n\n"
            "</details>"
        )
        markdown_text, count = marker_re.subn(
            lambda match, evidence=evidence: match.group(0) + "\n\n" + evidence,
            markdown_text,
            count=1,
        )
        if count:
            markdown_covered.add(anchor)
    if md_path.exists():
        md_path.write_text(markdown_text, encoding="utf-8")

    return {
        "candidate_count": len(candidates),
        "expected_anchors": sorted(expected_anchors),
        "html_covered_anchors": sorted(html_covered),
        "markdown_covered_anchors": sorted(markdown_covered),
        "missing_crop_anchors": sorted(missing_crop_anchors),
        "missing_crop_diagnostics": missing_crop_diagnostics,
        "missing_html_anchors": sorted(expected_anchors - html_covered),
        "missing_markdown_anchors": sorted(expected_anchors - markdown_covered),
        "duplicate_html_anchor_ids": sorted(
            {
                anchor
                for anchor in html_marker_occurrences
                if html_marker_occurrences.count(anchor) > 1
            }
        ),
        "duplicate_markdown_anchor_ids": sorted(
            {
                anchor
                for anchor in markdown_marker_occurrences
                if markdown_marker_occurrences.count(anchor) > 1
            }
        ),
        "source_images": [str(candidate["image"]) for candidate in candidates],
        "unresolved_anchors": sorted(
            str(candidate["anchor"])
            for candidate in candidates
            if candidate.get("unresolved")
        ),
        "candidates": candidates,
    }


def append_code_source_renderings(
    output_dir: Path,
    document_json: Any,
    *,
    metadata: dict[str, Any] | None = None,
    semantic_pdf_path: Path | None = None,
    visual_pdf_path: Path | None = None,
) -> dict[str, Any]:
    """Append exact PDF-page crops for semantic code blocks."""

    try:
        from PIL import Image
    except Exception:
        return {
            "candidate_count": 0,
            "html_applied_count": 0,
            "markdown_applied_count": 0,
            "source_images": [],
            "error": "Pillow unavailable",
        }

    page_inventory = _document_page_size_inventory(document_json)
    page_records = page_inventory["page_records"]
    provenance_manifest = (
        metadata.get("structural_visual_provenance_manifest")
        if isinstance(metadata, dict)
        else None
    )
    expected_visual_pdf_sha256 = _structural_expected_visual_pdf_sha256(metadata)
    expected_semantic_pdf_sha256 = _structural_expected_semantic_pdf_sha256(
        metadata
    )
    if expected_visual_pdf_sha256 is None and visual_pdf_path is not None:
        try:
            expected_visual_pdf_sha256 = file_sha256(visual_pdf_path)
        except OSError:
            pass
    if expected_semantic_pdf_sha256 is None and semantic_pdf_path is not None:
        try:
            expected_semantic_pdf_sha256 = file_sha256(semantic_pdf_path)
        except OSError:
            pass
    code_nodes: list[tuple[dict[str, Any], int | None]] = []
    for part in page_inventory["parts"]:
        part_index = part.get("part_index")
        for node in iter_nodes(part.get("document")):
            if (
                isinstance(node, dict)
                and str(node.get("label") or "").casefold() == "code"
                and first_prov(node)
                # Keep this classification identical to
                # semantic_reflow._collect_items: a code-labelled node headed
                # ``Algorithm N`` belongs to the algorithm surface and must not
                # consume a code-block evidence index.
                and not re.search(
                    r"(?i)^Algorithm\s+\d+\b",
                    str(node.get("text") or ""),
                )
            ):
                code_nodes.append((node, part_index))
    candidates: list[dict[str, Any]] = []
    expected_body_identity_by_ref: dict[str, str] = {}
    provenance_verified_refs: list[str] = []
    provenance_mismatch_refs: list[str] = []
    provenance_diagnostics: dict[str, list[str]] = {}
    provenance_entries: list[dict[str, Any]] = []
    code_dir = output_dir / "code_blocks"
    for index, (node, part_index) in enumerate(code_nodes, start=1):
        prov = first_prov(node) or {}
        bbox = bbox_geometry(prov)
        raw_page_no = prov.get("page_no")
        page_no = _resolve_document_page_number(
            page_inventory,
            raw_page_no,
            part_index=part_index,
        )
        page_image = output_dir / "pages" / f"page_{page_no}.png"
        page_record = page_records.get(page_no) or {}
        page_size = page_record.get("size") or {}
        page_width = float(page_size.get("width") or 0.0)
        page_height = float(page_size.get("height") or 0.0)
        if not bbox or not page_no or not page_image.exists() or not page_width or not page_height:
            continue
        relative_path = f"code_blocks/code_block_{index}.png"
        page_manifest = (
            (provenance_manifest or {}).get("pages", {}).get(str(page_no))
            if isinstance(provenance_manifest, dict)
            else None
        )
        source_ref = _structural_node_source_ref(
            node,
            kind="code",
            fallback_index=index - 1,
            part_index=part_index,
        )
        source_code_text = str(node.get("text") or "")
        numbered_source_lines = _numbered_code_lines(source_code_text)
        expected_identity = _code_body_identity(
            "\n".join(content for _number, content in numbered_source_lines)
            if numbered_source_lines
            else source_code_text
        )
        expected_body_identity_by_ref[source_ref] = expected_identity
        page_verified, page_verify_reasons, page_manifest = (
            _structural_page_manifest_verify(
                output_dir,
                provenance_manifest,
                page_no=page_no,
                expected_visual_pdf_sha256=expected_visual_pdf_sha256,
                current_semantic_page_size=page_size,
            )
        )
        existing_entry, existing_lookup_reasons = (
            _structural_manifest_entry_for_ref(
                provenance_manifest,
                kind="code",
                source_ref=source_ref,
                index=index,
            )
        )
        crop_box: tuple[int, int, int, int] | None = None
        page_image_size: dict[str, int] | None = None
        try:
            with Image.open(page_image) as image:
                crop_box = _bbox_pixel_crop_box(
                    bbox,
                    page_width=page_width,
                    page_height=page_height,
                    image_width=image.width,
                    image_height=image.height,
                    padding=14,
                )
                if crop_box is None:
                    continue
                page_image_size = {"width": image.width, "height": image.height}
                code_dir.mkdir(exist_ok=True)
                image.crop(crop_box).save(output_dir / relative_path)
        except Exception:
            continue
        visual_page_size = (
            (page_manifest or {}).get("page_size")
            if isinstance(page_manifest, dict)
            else page_size
        )
        metric = {
            "path": relative_path,
            "page_no": page_no,
            "bbox": _structural_bbox_snapshot((prov.get("bbox") or bbox)),
            "asset_sha256": file_sha256(output_dir / relative_path),
            "source_pdf_sha256": (
                str((provenance_manifest or {}).get("visual_pdf_sha256") or "")
                if isinstance(provenance_manifest, dict)
                else str(expected_visual_pdf_sha256 or "")
            ),
            "page_image_path": f"pages/page_{page_no}.png",
            "page_image_sha256": (
                str((page_manifest or {}).get("page_image_sha256") or "")
                if isinstance(page_manifest, dict)
                else ""
            ),
            "padding_px": 14,
            "pixel_box": crop_box,
            "page_size": visual_page_size,
            "page_image_size": page_image_size,
        }
        provenance_entry = _structural_visual_provenance_entry(
            kind="code",
            index=index,
            source_ref=source_ref,
            node=node,
            body_identity=expected_identity,
            metric=metric,
            node_bbox=prov.get("bbox"),
            part_index=part_index,
            semantic_pdf_sha256=expected_semantic_pdf_sha256,
            conversion_pdf_sha256=expected_semantic_pdf_sha256,
            semantic_page_size=page_size,
            crop_coordinate_page_size=page_size,
        )
        active_entry = existing_entry
        if active_entry is None and page_verified:
            index_collisions = [
                entry
                for entry in ((provenance_manifest or {}).get("code") or [])
                if isinstance(entry, dict) and entry.get("index") == index
            ] if isinstance(provenance_manifest, dict) else []
            if index_collisions:
                existing_lookup_reasons.append("code_manifest_index_collision")
            else:
                _replace_structural_manifest_entry(
                    provenance_manifest,
                    inventory="code",
                    entry=provenance_entry,
                )
                active_entry = provenance_entry
                existing_lookup_reasons = []
        if isinstance(active_entry, dict):
            provenance_entries.append(active_entry)
        verified, verify_reasons = _structural_provenance_verify(
            output_dir,
            active_entry,
            current_source_ref=source_ref,
            current_page_no=page_no,
            current_bbox=prov.get("bbox"),
            current_body_identity=expected_identity,
            current_self_ref=str(node.get("self_ref") or ""),
            current_part_index=part_index,
            current_semantic_page_size=page_size,
            expected_visual_pdf_sha256=expected_visual_pdf_sha256,
            expected_semantic_pdf_sha256=expected_semantic_pdf_sha256,
            expected_asset_path=relative_path,
            expected_kind="code",
        )
        verify_reasons = sorted(
            set(
                verify_reasons
                + existing_lookup_reasons
                + ([] if page_verified else page_verify_reasons)
            )
        )
        verified = bool(verified and page_verified and not existing_lookup_reasons)
        if verified:
            provenance_verified_refs.append(source_ref)
        else:
            provenance_mismatch_refs.append(source_ref)
            provenance_diagnostics[source_ref] = verify_reasons
        candidates.append(
            {
                "code_index": index,
                "image": relative_path,
                "page_no": page_no,
                "source_page_no": raw_page_no,
                "part_index": part_index,
                "bbox": bbox,
                "source_ref": source_ref,
                "provenance_verified": verified,
                "provenance_reasons": verify_reasons,
            }
        )

    html_applied = 0
    html_bound_refs: list[str] = []
    unmatched_html_candidates: list[dict[str, Any]] = []
    html_path = output_dir / "document.html"
    if candidates and html_path.exists():
        document_html = html_path.read_text(encoding="utf-8")
        document_html = _strip_source_disclosure_blocks(
            document_html,
            extra_class="docling-code-source-disclosure",
        )
        document_html = re.sub(
            r'<section\b[^>]*class="[^"]*\bdocling-code-source-evidence-appendix\b[^"]*"[^>]*>.*?</section>',
            "",
            document_html,
            flags=re.I | re.S,
        )
        for candidate in candidates:
            source_ref = str(candidate["source_ref"])
            escaped_ref = re.escape(html.escape(source_ref, quote=True))
            block_re = re.compile(
                r'(?P<block><section\b[^>]*class="[^"]*\bcode-listing\b[^"]*"[^>]*>'
                r".*?<pre\b[^>]*data-source-ref=[\"']"
                + escaped_ref
                + r"[\"'][^>]*>.*?</section>)",
                flags=re.I | re.S,
            )
            figure = (
                '<figure class="docling-code-source-evidence">'
                f'<span hidden data-source-ref="{html.escape(source_ref, quote=True)}"></span>'
                f'<img src="{candidate["image"]}" '
                f'alt="Code block {candidate["code_index"]} source rendering">'
                f'<figcaption>Code block {candidate["code_index"]} — exact source '
                "rendering from the original PDF</figcaption></figure>"
            )
            figure = _source_disclosure_html(
                figure,
                summary="查看代码原始裁剪",
                extra_class="docling-code-source-disclosure",
                attrs=f' data-source-ref="{html.escape(source_ref, quote=True)}"',
            )
            document_html, applied = block_re.subn(
                lambda match, figure=figure: match.group("block") + figure,
                document_html,
                count=1,
            )
            if applied:
                html_bound_refs.append(source_ref)
            else:
                unmatched_html_candidates.append(candidate)
        if unmatched_html_candidates and "</body>" in document_html.lower():
            figures = "".join(
                _source_disclosure_html(
                    '<figure class="docling-code-source-evidence">'
                f'<span hidden data-source-ref="{html.escape(str(candidate["source_ref"]), quote=True)}"></span>'
                f'<img src="{candidate["image"]}" '
                f'alt="Code block {candidate["code_index"]} source rendering">'
                f'<figcaption>Code block {candidate["code_index"]} — exact source '
                "rendering from the original PDF</figcaption></figure>",
                    summary="查看代码原始裁剪",
                    extra_class="docling-code-source-disclosure",
                    attrs=f' data-source-ref="{html.escape(str(candidate["source_ref"]), quote=True)}"',
                )
                for candidate in unmatched_html_candidates
            )
            appendix = (
                '<section class="docling-code-source-evidence-appendix">'
                "<h2>Original code renderings</h2>"
                + figures
                + "</section>"
            )
            body_end = re.search(r"</body>", document_html, flags=re.I)
            if body_end:
                document_html = (
                    document_html[: body_end.start()]
                    + appendix
                    + document_html[body_end.start() :]
                )
        html_path.write_text(document_html, encoding="utf-8")
        html_applied = len(html_bound_refs) + (
            len(unmatched_html_candidates)
            if unmatched_html_candidates and "</body>" in document_html.lower()
            else 0
        )

    markdown_applied = 0
    markdown_bound_refs: list[str] = []
    unmatched_markdown_candidates: list[dict[str, Any]] = []
    md_path = output_dir / "document.md"
    if candidates and md_path.exists():
        document_markdown = md_path.read_text(encoding="utf-8").rstrip()
        document_markdown, _ = _markdown_sub_outside_code(
            document_markdown,
            r'<details\b[^>]*class="[^"]*\bdocling-code-source-disclosure\b[^"]*"[^>]*>.*?</details>',
            "",
            flags=re.I | re.S,
        )
        for candidate in candidates:
            source_ref = str(candidate["source_ref"])
            marker = f"<!-- source-code-ref:{source_ref} -->"
            evidence = (
                marker
                + "\n\n"
                + _source_disclosure_markdown(
                    _markdown_image(
                        f'Code block {candidate["code_index"]} — source rendering',
                        candidate["image"],
                    ),
                    summary="查看代码原始裁剪",
                    extra_class="docling-code-source-disclosure",
                )
            )
            if document_markdown.count(marker) == 1:
                document_markdown = document_markdown.replace(marker, evidence, 1)
                markdown_bound_refs.append(source_ref)
            else:
                unmatched_markdown_candidates.append(candidate)
        if unmatched_markdown_candidates:
            parts = [
                "",
                "## Original code renderings",
                "",
                (
                    "The following images preserve code blocks that could not be "
                    "bound to a unique semantic occurrence."
                ),
            ]
            for candidate in unmatched_markdown_candidates:
                parts.extend(
                    [
                        "",
                        _source_disclosure_markdown(
                            _markdown_image(
                                f'Code block {candidate["code_index"]} — source rendering',
                                candidate["image"],
                            ),
                            summary="查看代码原始裁剪",
                            extra_class="docling-code-source-disclosure",
                        ),
                    ]
                )
            document_markdown = document_markdown + "\n".join(parts)
        md_path.write_text(document_markdown.rstrip() + "\n", encoding="utf-8")
        markdown_applied = len(markdown_bound_refs) + len(
            unmatched_markdown_candidates
        )

    final_html = html_path.read_text(encoding="utf-8") if html_path.exists() else ""
    final_markdown = md_path.read_text(encoding="utf-8") if md_path.exists() else ""
    html_body_identity_verified_refs: list[str] = []
    markdown_body_identity_verified_refs: list[str] = []
    html_body_identity_mismatch_refs: list[str] = []
    markdown_body_identity_mismatch_refs: list[str] = []
    body_identity_diagnostics: dict[str, dict[str, str]] = {}
    for candidate in candidates:
        source_ref = str(candidate["source_ref"])
        expected_identity = expected_body_identity_by_ref.get(source_ref, "")
        html_body = _html_section_pre_body_for_source_ref(
            final_html,
            css_class="code-listing",
            source_ref=source_ref,
        )
        markdown_body = _markdown_fenced_body_for_source_ref(
            final_markdown,
            kind="code",
            source_ref=source_ref,
        )
        html_identity = _code_body_identity(
            html_body or "",
            html_markup=True,
        )
        markdown_identity = _code_body_identity(markdown_body or "")
        if expected_identity and html_identity == expected_identity:
            html_body_identity_verified_refs.append(source_ref)
        else:
            html_body_identity_mismatch_refs.append(source_ref)
        if expected_identity and markdown_identity == expected_identity:
            markdown_body_identity_verified_refs.append(source_ref)
        else:
            markdown_body_identity_mismatch_refs.append(source_ref)
        body_identity_diagnostics[source_ref] = {
            "html": "verified" if expected_identity and html_identity == expected_identity else "mismatch",
            "markdown": (
                "verified"
                if expected_identity and markdown_identity == expected_identity
                else "mismatch"
            ),
        }

    return {
        "candidate_count": len(candidates),
        "html_applied_count": html_applied,
        "markdown_applied_count": markdown_applied,
        "candidate_source_refs": [str(item["source_ref"]) for item in candidates],
        "html_bound_source_refs": html_bound_refs,
        "markdown_bound_source_refs": markdown_bound_refs,
        "html_unbound_source_refs": [
            str(item["source_ref"]) for item in unmatched_html_candidates
        ],
        "markdown_unbound_source_refs": [
            str(item["source_ref"]) for item in unmatched_markdown_candidates
        ],
        "html_body_identity_verified_refs": sorted(
            set(html_body_identity_verified_refs)
        ),
        "markdown_body_identity_verified_refs": sorted(
            set(markdown_body_identity_verified_refs)
        ),
        "html_body_identity_mismatch_refs": sorted(
            set(html_body_identity_mismatch_refs)
        ),
        "markdown_body_identity_mismatch_refs": sorted(
            set(markdown_body_identity_mismatch_refs)
        ),
        "body_identity_diagnostics": body_identity_diagnostics,
        "provenance_verified_refs": sorted(set(provenance_verified_refs)),
        "provenance_mismatch_refs": sorted(set(provenance_mismatch_refs)),
        "provenance_diagnostics": provenance_diagnostics,
        "provenance_entries": provenance_entries,
        "source_images": [candidate["image"] for candidate in candidates],
        "candidates": candidates,
    }


def collect_page_nodes(document_json: Any) -> list[dict[str, Any]]:
    nodes: list[dict[str, Any]] = []
    formula_index = 0
    for node in iter_nodes(document_json):
        if not isinstance(node, dict):
            continue
        prov = first_prov(node)
        geometry = bbox_geometry(prov)
        if not prov or not geometry:
            continue
        label = str(node.get("label") or "")
        if label.lower() == "formula":
            formula_index += 1
        nodes.append(
            {
                "formula_index": formula_index if label.lower() == "formula" else None,
                "label": label,
                "text": str(node.get("text") or "")[:220],
                "page_no": prov.get("page_no"),
                "bbox": geometry,
                "center_y": (geometry["t"] + geometry["b"]) / 2.0,
                "center_x": (geometry["l"] + geometry["r"]) / 2.0,
            }
        )
    return nodes


def nearby_nodes_for_formula(
    nodes: list[dict[str, Any]],
    formula_index: int,
    page_no: Any,
    geometry: dict[str, float] | None,
) -> list[dict[str, Any]]:
    if not page_no or not geometry:
        return []
    formula_center_y = (geometry["t"] + geometry["b"]) / 2.0
    nearby: list[dict[str, Any]] = []
    for node in nodes:
        if node.get("page_no") != page_no:
            continue
        if node.get("formula_index") == formula_index:
            continue
        node_bbox = node.get("bbox") or {}
        vertical_distance = abs(float(node.get("center_y") or 0.0) - formula_center_y)
        horizontal_overlap = min(geometry["r"], node_bbox.get("r", 0.0)) - max(
            geometry["l"], node_bbox.get("l", 0.0)
        )
        same_column_or_overlap = horizontal_overlap > 0 or (
            abs(float(node.get("center_x") or 0.0) - ((geometry["l"] + geometry["r"]) / 2.0))
            < 80
        )
        if vertical_distance <= 45 and same_column_or_overlap:
            nearby.append(
                {
                    "label": node.get("label"),
                    "text": node.get("text"),
                    "bbox": node_bbox,
                    "vertical_distance": round(vertical_distance, 2),
                    "horizontal_overlap": round(horizontal_overlap, 2),
                }
            )
    nearby.sort(key=lambda item: (item["vertical_distance"], item["label"]))
    return nearby[:6]


def formula_review_diagnostics(
    formulas: list[dict[str, Any]],
    output_dir: Path,
    document: dict[str, Any],
    input_file: Path,
    crop_metrics: list[dict[str, Any]],
) -> dict[str, Any]:
    suspicious: list[dict[str, Any]] = []
    missing: list[dict[str, Any]] = []
    formula_numbers: dict[str, dict[str, Any]] = {}
    metrics_by_index = {
        int(item["index"]): item
        for item in crop_metrics
        if isinstance(item.get("index"), int)
    }
    page_width_by_no = {}
    for item in crop_metrics:
        crop = item.get("source") or item.get("context") or {}
        page_size = crop.get("page_size") or {}
        if item.get("page_no") and page_size.get("width"):
            page_width_by_no[int(item["page_no"])] = float(page_size["width"])

    page_nodes = collect_page_nodes(document.get("json_content"))
    for index, formula in enumerate(formulas, start=1):
        text = str(formula.get("text") or "")
        prov = first_prov(formula) or {}
        page_no = prov.get("page_no")
        geometry = bbox_geometry(prov)
        crop_metric = metrics_by_index.get(index, {})
        source_metric = crop_metric.get("source") or {}
        context_metric = crop_metric.get("context") or {}
        match = FORMULA_NUMBER_RE.search(text)
        if match:
            formula_numbers[str(_formula_number_match_value(match))] = {
                "index": index,
                "text": text,
                "prov": prov,
            }
        reasons: list[str] = []
        if CN_CHAR_RE.search(text):
            reasons.append("contains_cjk_text")
        if CN_CHAR_RE.search(text) or re.search(r"\\text\s*\{[^}]*[\u3400-\u9fff]", text):
            reasons.append("prose_like_fragment_in_formula_text")
        if len(text) > 180 and text.count("\\frac") > 6:
            reasons.append("repeated_fraction_pattern")
        if len(text) > 260:
            reasons.append("formula_text_too_long")
        if geometry:
            if geometry["height"] < 14 and len(text) > 120:
                reasons.append("bbox_too_thin_for_complex_formula")
            if geometry["height"] < 12 and geometry["aspect_width_over_height"] > 12 and len(text) > 180:
                reasons.append("bbox_likely_line_or_separator")
            if geometry["b"] < 80:
                reasons.append("near_page_bottom_context_needed")
            page_width = page_width_by_no.get(int(page_no or 0))
            if page_width:
                midpoint = page_width / 2.0
                if geometry["l"] < midpoint < geometry["r"]:
                    reasons.append("bbox_crosses_expected_column_boundary")
        if source_metric:
            source_height = int(source_metric.get("pixel_height") or 0)
            source_width = int(source_metric.get("pixel_width") or 0)
            if source_width and source_height / source_width < 0.08 and len(text) > 180:
                reasons.append("source_crop_likely_too_thin")
            if source_height < 32 and len(text) > 180:
                reasons.append("source_crop_likely_useless_for_review")
        if _is_formula_number_only(text):
            reasons.append("formula_number_only")
            missing.append({"index": index, "text": text, "prov": prov})
        if reasons:
            suspicious.append(
                {
                    "index": index,
                    "text": text[:300],
                    "reasons": reasons,
                    "page_no": page_no,
                    "bbox": geometry,
                    "source_crop": source_metric,
                    "context_crop": context_metric,
                    "full_page_evidence": f"pages/page_{page_no}.png" if page_no else None,
                    "evidence": f"formulas/formula_{index}_context.png",
                    "nearby_nodes": nearby_nodes_for_formula(
                        page_nodes, index, page_no, geometry
                    ),
                }
            )

    section_text = combined_text(document)
    has_section_23 = bool(re.search(r"2\s*\.?\s*3|2\.3", section_text))
    formula_4 = formula_numbers.get("4")
    formula_4_status = "missing"
    if formula_4:
        formula_4_status = (
            "present_number_only_missing_body"
            if _is_formula_number_only(str(formula_4["text"]).strip())
            else "present"
        )
    # Do not synthesize a missing-formula finding from a filename substring.
    # The former ``"CN" in name`` branch polluted unrelated unseen papers
    # such as ``fooCN.pdf`` with a paper-specific formula-4 diagnostic.

    return {
        "formula_count": len(formulas),
        "formula_evidence_count": len(
            list((output_dir / "formulas").glob("formula_*_context.png"))
        ),
        "formula_crop_diagnostics": crop_metrics,
        "missing_formula_evidence_count": len(missing),
        "suspicious_formula_diagnostics": suspicious,
        "missing_formula_diagnostics": missing,
        "cn_section_2_3_diagnostic_summary": {
            "applies": input_file.name == "CN.pdf",
            "section_2_3_text_seen": has_section_23,
            "formula_4_status": formula_4_status,
            "formula_4_evidence": (
                f"formulas/formula_{formula_4['index']}_context.png"
                if formula_4
                else "pages/page_3.png"
            ),
            "right_column_text_contamination_indicators": [
                item
                for item in suspicious
                if item["page_no"] == 3 and "contains_cjk_text" in item["reasons"]
            ],
        },
    }


def write_review_index(
    output_dir: Path,
    metadata: dict[str, Any],
    status: dict[str, Any],
) -> None:
    def links_for(pattern: str) -> list[str]:
        return [
            str(path.relative_to(output_dir))
            for path in sorted(output_dir.glob(pattern))
            if path.is_file()
        ]

    sections = [
        ("Pages", links_for("pages/page_*.png")),
        ("Tables", links_for("tables/table_*.*")),
        ("Formulas", links_for("formulas/formula_*.png")),
        ("Pictures", links_for("pictures/picture_*.png")),
    ]
    warning_items = "".join(
        f"<li>{html.escape(str(item))}</li>" for item in status.get("warnings", [])
    )
    section_html = []
    for title, paths in sections:
        links = "".join(
            f'<li><a href="{html.escape(path)}">{html.escape(path)}</a></li>'
            for path in paths
        )
        section_html.append(f"<h2>{html.escape(title)} ({len(paths)})</h2><ul>{links}</ul>")
    suspicious_html = []
    for item in metadata.get("suspicious_formula_diagnostics") or []:
        source_path = f"formulas/formula_{item.get('index')}.png"
        context_path = item.get("evidence")
        page_path = item.get("full_page_evidence")
        links = []
        for label, path in (
            ("source", source_path),
            ("context", context_path),
            ("full page", page_path),
        ):
            if path:
                links.append(
                    f'<a href="{html.escape(str(path), quote=True)}">'
                    f"{html.escape(label)}</a>"
                )
        suspicious_html.append(
            "<li>"
            f"Formula {html.escape(str(item.get('index')))}: "
            f"{html.escape(', '.join(item.get('reasons') or []))} "
            f"({' | '.join(links)})"
            "</li>"
        )
    diagnostics = html.escape(
        json.dumps(
            metadata.get("cn_section_2_3_diagnostic_summary") or {},
            ensure_ascii=False,
            indent=2,
        )
    )
    (output_dir / "review_index.html").write_text(
        (
            "<!doctype html><html><head><meta charset=\"utf-8\">"
            "<style>body{font-family:system-ui,sans-serif;max-width:1100px;margin:24px auto;"
            "line-height:1.45}code,pre{background:#f4f4f4;padding:2px 4px}"
            "li{margin:3px 0}</style>"
            f"<title>Review artifacts: {html.escape(str(metadata.get('job_id')))}</title>"
            "</head><body>"
            f"<h1>Review artifacts: {html.escape(str(metadata.get('job_id')))}</h1>"
            '<p><a href="document.html">document.html</a> | '
            '<a href="document.md">document.md</a> | '
            '<a href="document.json">document.json</a> | '
            '<a href="metadata.json">metadata.json</a> | '
            '<a href="status.json">status.json</a></p>'
            f"<h2>Warnings</h2><ul>{warning_items}</ul>"
            + "".join(section_html)
            + "<h2>Suspicious Formula Evidence</h2><ul>"
            + "".join(suspicious_html)
            + "</ul>"
            + f"<h2>CN section 2.3 diagnostics</h2><pre>{diagnostics}</pre>"
            "</body></html>\n"
        ),
        encoding="utf-8",
    )


def add_document_review_banner(output_dir: Path) -> None:
    html_path = output_dir / "document.html"
    content = html_path.read_text(encoding="utf-8")
    banner = (
        '<div style="font-family:system-ui,sans-serif;padding:10px 12px;'
        'border:1px solid #999;margin:12px 0;background:#fffbe8">'
        '<strong>Review artifacts:</strong> '
        '<a href="review_index.html">review_index.html</a></div>'
    )
    if "<body" in content:
        content = re.sub(r"(<body[^>]*>)", r"\1" + banner, content, count=1, flags=re.I)
    else:
        content = banner + content
    html_path.write_text(content, encoding="utf-8")


def formula_review_targets(output_dir: Path) -> dict[int, dict[str, str]]:
    targets: dict[int, dict[str, str]] = {}
    for path in sorted((output_dir / "formulas").glob("formula_*.png")):
        match = re.match(r"formula_(\d+)(_context)?\.png$", path.name)
        if not match:
            continue
        index = int(match.group(1))
        key = "context" if match.group(2) else "source"
        targets.setdefault(index, {})[key] = str(path.relative_to(output_dir))
    return targets


def formula_source_links(index: int, targets: dict[str, str]) -> str:
    parts: list[str] = []
    for key, label in (("source", "source image"), ("context", "context crop")):
        path = targets.get(key)
        if not path:
            continue
        parts.append(
            f'<a href="{html.escape(path, quote=True)}">{html.escape(label)}</a>'
        )
    if not parts:
        return ""
    return (
        f' <span class="docling-formula-source" data-formula-index="{index}">'
        + " | ".join(parts)
        + "</span>"
    )


def link_formula_placeholders(document_html: str, targets_by_index: dict[int, dict[str, str]]) -> str:
    if "Formula not decoded" not in document_html:
        return document_html
    context_targets = [
        (index, targets["context"])
        for index, targets in sorted(targets_by_index.items())
        if "context" in targets
    ]
    if not context_targets:
        return document_html
    replacement_index = 0

    def replace(_match: re.Match[str]) -> str:
        nonlocal replacement_index
        formula_index, target = context_targets[
            min(replacement_index, len(context_targets) - 1)
        ]
        replacement_index += 1
        return (
            f'<a class="docling-formula-placeholder" '
            f'href="{html.escape(target, quote=True)}">'
            f"Formula not decoded (review formula {formula_index})"
            "</a>"
        )

    return re.sub(r"Formula not decoded", replace, document_html)


def inject_formula_source_links_by_mathml_order(
    document_html: str,
    targets_by_index: dict[int, dict[str, str]],
) -> tuple[str, int]:
    linked = 0

    def replace(match: re.Match[str]) -> str:
        nonlocal linked
        formula_index = linked + 1
        source_links = formula_source_links(formula_index, targets_by_index.get(formula_index, {}))
        if not source_links:
            return match.group(0)
        linked += 1
        return match.group(0) + source_links

    updated = re.sub(r"<div><math\b(?:(?!</math></div>).)*?</math></div>", replace, document_html, flags=re.S)
    return updated, linked


def inject_formula_source_links(
    output_dir: Path,
    formulas: list[dict[str, Any]],
) -> int:
    html_path = output_dir / "document.html"
    document_html = html_path.read_text(encoding="utf-8")
    targets_by_index = formula_review_targets(output_dir)
    if not targets_by_index:
        return 0

    updated_html = link_formula_placeholders(document_html, targets_by_index)
    linked_indexes: set[int] = set()
    for index, formula in enumerate(formulas, start=1):
        targets = targets_by_index.get(index)
        if not targets:
            continue
        formula_text = str(formula.get("text") or "").strip()
        if not formula_text or "Formula not decoded" in formula_text:
            continue
        source_links = formula_source_links(index, targets)
        if not source_links:
            continue
        for candidate in (formula_text, html.escape(formula_text)):
            if candidate and candidate in updated_html:
                updated_html = updated_html.replace(candidate, candidate + source_links, 1)
                linked_indexes.add(index)
                break

    if not linked_indexes:
        updated_html, mathml_link_count = inject_formula_source_links_by_mathml_order(
            updated_html, targets_by_index
        )
        linked_indexes.update(range(1, mathml_link_count + 1))

    if updated_html != document_html:
        html_path.write_text(updated_html, encoding="utf-8")
    return len(linked_indexes)


